The matching results in Tab.~\ref{tab:va} and Tab.~\ref{tab:sp} agree with those obtained using the external source method.
Below, we take the scalar operator $\mathcal{O}_1^{(6)}$ and the vector operator $\mathcal{O}_5^{(6)}$ as examples.


In the external source method, the chiral operators of $\mathcal{O}(p^2)$ 
and $\mathcal{O}(p^4)$ 
corresponding to the operator $\mathcal{O}_1^{(6)}$ can be obtained from Eqs.\eqref{eq:ubasis2}~\eqref{eq:ubasis}, respectively.
Following the notation in Ref.~\cite{Song:2025snz}, we rewrite the scalar operator
$\mathcal{O}_1^{(6)} \equiv (\bar e e)(\bar q \,{\rm T}\,
 q)$, where ${\rm T}$ is the coefficient matrix. Then the external scalar source $s = (\bar e e) \,{\rm T} $ is incorporated into the building blocks $\chi_\pm$:
 \begin{align}
     \chi_+
     =(\bar ee)(u^\dagger {\rm T}u^\dagger +u {\rm T} u) + \hat \chi_+ \;,\\
     \chi_-
     =(\bar ee)(u^\dagger {\rm T}u^\dagger -u {\rm T} u) + \hat \chi_-\;.
 \end{align}
Thus, 
the chiral Lagrangian up to $p^4$ order is given by
\begin{align}
    \mathcal{L}_{4, 1}^\prime=&\,  \frac{F^2_0}{4} (\bar{e}e) \langle u^\dagger {\rm T}u^\dagger +u {\rm T} u \rangle +L_3 (\bar{e}e) \langle u^\dagger {\rm T}u^\dagger +u {\rm T} u \rangle\langle u_\mu u^\mu\rangle \notag\\
    &+2L_7(\bar{e}e)\langle \hat \chi_+(u^\dagger {\rm T}u^\dagger +u {\rm T} u)\rangle +2L_8(\bar{e}e)\langle \hat \chi_-(u^\dagger {\rm T}u^\dagger -u {\rm T} u)\rangle \notag\\
    &+2L_9(\bar{e}e)\langle u^\dagger {\rm T}u^\dagger +u {\rm T} u \rangle\langle \hat \chi_+\rangle+2L_{10}(\bar{e}e)\langle u^\dagger {\rm T}u^\dagger -u {\rm T} u \rangle\langle \hat \chi_-\rangle \;.
\end{align}
This expression can be converted into the results in Tab.~\ref{tab:sp} by taking ${\rm T}= \mathcal{C}_1^{(6)} \Sigma^\dagger  =\mathcal{C}_1^{(6)} \Sigma $.



For the vector operator $\mathcal{O}_5^{(6)}=(\bar e\gamma_\mu e)(\bar q\gamma^\mu\,{\rm T}\,q)$, the vector external source $v_\mu=(\bar e\gamma_\mu e){\rm T}$, which is present in both $u_\mu$ and $f_\pm^{\mu\nu}$ in the external source method, see Eqs.~\eqref{eq:vielbein}~\eqref{eq:fmunu}. Thus, the relevant terms in the chiral Lagrangian up to $p^4$ order for $\mathcal{O}_5^{(6)}$ are given by
\begin{align}
    \mathcal{L}_{4, 5}^\prime=&\frac{F^2_0}{2}(\bar{e}\gamma_\mu e)\langle(u^\dagger {\rm T}u -u {\rm T} u^\dagger)\hat{u}^\mu\rangle+4L_1(\bar e\gamma_\mu e)\langle(u^\dagger {\rm T}u -u {\rm T} u^\dagger)\hat{u}^\mu\rangle\langle \hat{u}^\nu \hat{u}_\nu\rangle\notag\\
    &+4L_2(\bar e\gamma_\mu e)\langle(u^\dagger {\rm T}u -u {\rm T} u^\dagger)\hat{u}_\nu\rangle\langle \hat{u}^\mu \hat{u}^\nu\rangle+2L_3(\bar e\gamma_\mu e)\langle\chi_+\rangle\langle (u^\dagger {\rm T}u -u {\rm T} u^\dagger) \hat{u}^\mu\rangle\notag\\
    &+iL_4\langle f_+^{\mu\nu}\hat{u}_\mu \hat{u}_\nu\rangle\;.
\end{align}
This expression can be converted into the results in Tab.~\ref{tab:va} by taking ${\rm T}=\mathcal{C}_5^{(6)} \Sigma_L=\mathcal{C}_5^{(6)} \Sigma_R$. Especially, the $L_4$ term is transformed using the IBP and EOMs
\begin{align}
    i\langle f_+^{\mu\nu}\hat{u}_\mu \hat{u}_\nu\rangle&\sim i\langle [u(\partial^\mu v^\nu-\partial^\nu v^\mu) u^\dagger+u^\dagger(\partial^\mu v^\nu-\partial^\nu v^\mu) u][\hat{u}_\mu,\hat{u}_\nu]\rangle\;,\notag\\
    &\sim\langle (uv^\mu u^\dagger+u^\dagger v^\mu u)[\hat{u}_\mu,\hat \chi_-]\rangle\;,\notag\\
    &=(\bar e\gamma^\mu e)\langle Q_+[\hat{u}_\mu,\hat \chi_-]\rangle\;.
\end{align}
The treatment of other axial-vector and pseudo-scalar operators is similar to that of the operators $\mathcal{O}_1^{(6)}$ and $\mathcal{O}_5^{(6)}$. To clarify the matching for tensor operators, we have provided a detailed discussion of the matching for $\mathcal{O}_{11}^{(6)}$ using three different methods in Appendix~\ref{app:tensor}.




%%----------------------------
 \subsection{Conversion of results in three methods}
 \label{sec:conversion}
%%----------------------------



As detailed in Sec.~\ref{sec:spurion-conventional}, the matching results derived from the conventional spurion method and external source method have been explicitly compared. 
The correspondence between the external sources and spurions for the dimension-6 LEFT operators is
\begin{align}
    -s &= \lambda_S\;,  & ip &= \lambda_P \;,\\
    v^\mu &= \lambda_V\;, & a^\mu &= \lambda_A\;,\\
    \label{eq:tbar-lambda}
    \bar t^{\mu\nu} &= \lambda_T^{\mu\nu}+\frac{i}{2}\varepsilon^{\mu\nu}_{~~\alpha\beta}\lambda^{\alpha\beta}_\varepsilon\;,
\end{align}
where the spurions $\lambda_{V/A}$, $\lambda_{S/P}$ and $\lambda_{T/\varepsilon}$ are defined in Eqs.~\eqref{eq:lambva}~\eqref{eq:lambsp}~\eqref{eq:lambt}, respectively. 


The conversion relations between the spurions in the conventional and our systematic methods are
\begin{align}
    \label{eq:conv-s}
    \lambda_S  & =  j_\ell  \left( \Sigma^\dagger P_R + \Sigma P_L\right) + {\rm h.c.} \;,\\
    \label{eq:conv-p}
    \lambda_P \gamma^5  & =  j_\ell  \left( \Sigma^\dagger P_R - \Sigma P_L \right) - {\rm h.c.}\;,\\
    \label{eq:conv-v}
    \lambda_V & =  j_\ell^\mu  \left( \Sigma_R P_R + \Sigma_L P_L \right) + {\rm h.c.}\;,\\
    \label{eq:conv-a}
    \lambda_A \gamma^5 & =  j_\ell^\mu  \left( \Sigma_R P_R - \Sigma_L P_L \right) + {\rm h.c.}\;,\\
    \lambda_T^{\mu\nu}  & = j_\ell^{\mu\nu}   \left( \Sigma^\dagger P_R + \Sigma P_L \right) + {\rm h.c.}\;,\\
    \label{eq:conv-eps}
    \lambda_\varepsilon^{\mu\nu} \gamma^5  & = j^{\mu\nu}_{\ell}   \left( \Sigma^\dagger P_R - \Sigma P_L \right) - {\rm h.c.}\;,
\end{align}
where the last relation can also be expressed as
\begin{align}
    \lambda_\varepsilon^{\mu\nu}  & = \frac{i}{2}\varepsilon^{\mu\nu}_{~~\rho\sigma}j^{\rho\sigma}_{\ell}   \left( \Sigma^\dagger P_R - \Sigma P_L \right) + {\rm h.c.}\;.
\end{align}
In the above, the lepton currents are given by
\begin{align}
    j_\ell &= \alpha_{\ell \ell^\prime}\left\{ \mathcal{C}_{1[3]}^{(6)}\, \bar e e\;, \ \mathcal{C}_{2[4]}^{(6)}\,\bar e i \gamma^5 e\;,\ \mathcal{C}_{13[14]}^{(6)}\,\bar \nu_L e_R \right\}\;,\\
    j_\ell^\mu &= \alpha_{\ell \ell^\prime} \left\{\mathcal{C}_{5[7]}^{(6)}\,\bar e \gamma^\mu e\;, \ \mathcal{C}_{6[8]}^{(6)}\,\bar e \gamma^5 \gamma^\mu e\;,\  \mathcal{C}_{9[10]}^{(6)}\,\bar \nu_L \gamma^\mu \nu_L\;,\ \mathcal{C}_{15[16]}^{(6)}\,\bar \nu_L \gamma^\mu e_L \right\}\;,\\
    j_\ell^{\mu\nu} &= \alpha_{\ell \ell^\prime} \left\{ \mathcal{C}_{11}^{(6)}\, \bar e \sigma^{\mu\nu} e\;,\ \mathcal{C}_{12}^{(6)}\,\bar e i \gamma^5 \sigma^{\mu\nu} e\;,\ \mathcal{C}_{17}^{(6)}\,\bar \nu_L \sigma^{\mu\nu} e_R \right\}\;.
\end{align}
Here, the factor $\alpha_{\ell \ell^\prime} = 1$ for the charged lepton current, and $1/2$ for the neutral lepton current. For brevity, we have included $\alpha_{\ell \ell^\prime}$ and Wilson coefficients into the lepton currents. 
In case of the lepton current $\bar e e$, the Wilson coefficients are $\mathcal{C}_{1}^{(6)}$ and $\mathcal{C}_{3}^{(6)}$ for the scalar and pseudo-scalar sources, respectively. A similar indexing convention applies to the Wilson coefficients for other lepton currents.



A comparison of elements in the three methods for the matching from quark to hadronic operators is given in Tab.~\ref{tab:comparison}. In the table, we have compare the building blocks, bases at the quark/hadronic level, and their parameterizations across the external source method, conventional spurion method, and systematic spurion method.
