%%----------------------------------------------
\subsection{Dimension-8 derivative operators}
%%----------------------------------------------
Although the derivatives acting on the quark field can be transferred to the lepton part through the EOMs for dimension-7 operators, this is not always true for the dimension-8 derivative operators. 
The external source method is limited in its applicability due to its restriction to a specific set of five types of external sources. The conventional spurion method is cumbersome because of the inherent redundancies in its formulation. Both issues can be addressed in the systematic spurion method. 

We consider the effective Lagrangian at the dimension-8 level as follows:
\begin{align}
    \mathcal{L}_{\rm eff}^{(8)}=\sum_{i=1}^{22}\mathcal{O}_i^{(8)}+\left(\sum_{i=23}^{31}+ {\rm h.c.}\right)\;,
\end{align}
where the $\psi^4 D^2$ type operators~\cite{Li:2020tsi,Murphy:2020cly} in the $CP$ eigenstate are given by
\begin{align}
\mathcal{O}_1^{(8)}&=(\bar e\overleftrightarrow{D}^\mu\gamma^\nu e)[\bar q\overleftrightarrow{D}_\mu\gamma_\nu(\Sigma_R P_R+\Sigma_L P_L) q]\;,
&
\mathcal{O}_2^{(8)}&=(\bar e\overleftrightarrow{D}^\mu\gamma^\nu\gamma^5 e)[\bar q\overleftrightarrow{D}_\mu\gamma_\nu(\Sigma_R P_R+\Sigma_L P_L) q]\;,\notag\\
\mathcal{O}_3^{(8)}&=(\bar e\overleftrightarrow{D}^\mu\gamma^\nu e)[\bar q\overleftrightarrow{D}_\mu\gamma_\nu(\Sigma_R P_R-\Sigma_L P_L) q]\;,
&
\mathcal{O}_4^{(8)}&=(\bar e\overleftrightarrow{D}^\mu\gamma^\nu\gamma^5 e)[\bar q\overleftrightarrow{D}_\mu\gamma_\nu(\Sigma_R P_R-\Sigma_L P_L) q]\;,\notag\\
\mathcal{O}_5^{(8)}&=(\bar \nu_L\overleftrightarrow{D}^\mu\gamma^\nu \nu_L)[\bar q(\Sigma_R P_R+\Sigma_L P_L)\overleftrightarrow{D}_\mu\gamma_\nu q]\;,
&
\mathcal{O}_6^{(8)}&=(\bar \nu_L\overleftrightarrow{D}^\mu\gamma^\nu \nu_L)[\bar q(\Sigma_R P_R-\Sigma_L P_L)\overleftrightarrow{D}_\mu\gamma_\nu\gamma^5 q]\;,\notag\\
\mathcal{O}_{7}^{(8)}&=(\bar e e)D^2[\bar q(\Sigma^\dagger P_R+\Sigma P_L)q]\;,
&
\mathcal{O}_{8}^{(8)}&=(\bar e\gamma^5 e)D^2[\bar q(\Sigma^\dagger P_R+\Sigma P_L) q]\;,\notag\\
\mathcal{O}_{9}^{(8)}&=(\bar e e)D^2[\bar q(\Sigma^\dagger P_R-\Sigma P_L) q]\;,
&
\mathcal{O}_{10}^{(8)}&=(\bar e\gamma^5 e)D^2[\bar q(\Sigma^\dagger P_R-\Sigma P_L) q]\;,\notag\\
\mathcal{O}_{11}^{(8)}&=(\bar e\gamma^\mu e)D^2[\bar q\gamma_\mu(\Sigma_R P_R+\Sigma_L P_L) q]\;,
&
\mathcal{O}_{12}^{(8)}&=(\bar e\gamma^\mu\gamma^5 e)D^2[\bar q\gamma_\mu(\Sigma_R P_R+\Sigma_L P_L) q]\;,\notag\\
\mathcal{O}_{13}^{(8)}&=(\bar e\gamma^\mu e)D^2[\bar q\gamma_\mu(\Sigma_R P_R-\Sigma_L P_L) q]\;,
&
\mathcal{O}_{14}^{(8)}&=(\bar e\gamma^\mu\gamma^5 e)D^2[\bar q\gamma_\mu(\Sigma_R P_R-\Sigma_L P_L) q]\;,\notag\\
\mathcal{O}_{15}^{(8)}&=(\bar \nu_L\gamma^\mu \nu_L)D^2[\bar q\gamma_\mu(\Sigma_R P_R+\Sigma_L P_L) q]\;,
&
\mathcal{O}_{16}^{(8)}&=(\bar \nu_L\gamma^\mu \nu_L)D^2[\bar q\gamma_\mu(\Sigma_R P_R-\Sigma_L P_L) q]\;,\notag\\
\mathcal{O}_{17}^{(8)}&=(\bar e\overleftrightarrow{D}^\mu e)[\bar q\overleftrightarrow{D}_\mu(\Sigma^\dagger P_R+\Sigma P_L) q]\;,
&
\mathcal{O}_{18}^{(8)}&=(\bar e\overleftrightarrow{D}^\mu\gamma^5 e)[\bar q\overleftrightarrow{D}_\mu(\Sigma^\dagger P_R+\Sigma P_L) q]\;,\notag\\
\mathcal{O}_{19}^{(8)}&=(\bar e\overleftrightarrow{D}^\mu e)[\bar q\overleftrightarrow{D}_\mu(\Sigma^\dagger P_R-\Sigma P_L) q]\;,
&
\mathcal{O}_{20}^{(8)}&=(\bar e\overleftrightarrow{D}^\mu\gamma^5 e)[\bar q\overleftrightarrow{D}_\mu(\Sigma^\dagger P_R-\Sigma P_L) q]\;,\notag\\
\mathcal{O}_{21}^{(8)}&=(\bar e \sigma^{\mu\nu}e)D^2[\bar q\sigma_{\mu\nu}(\Sigma^\dagger P_R+\Sigma P_L) q]\;,
&
\mathcal{O}_{22}^{(8)}&=(\bar e \gamma^5\sigma^{\mu\nu}e)D^2[\bar q\sigma_{\mu\nu}(\Sigma^\dagger P_R+\Sigma P_L) q]\;,\notag\\
\mathcal{O}_{23}^{(8)}&=(\bar \nu_L\overleftrightarrow{D}^\mu\gamma^\nu e_L)[\bar q\overleftrightarrow{D}_\mu\gamma_\nu(\Sigma_R P_R+\Sigma_L P_L) q]\;,
&
\mathcal{O}_{24}^{(8)}&=(\bar \nu_L\overleftrightarrow{D}^\mu\gamma^\nu e_L)[\bar q\overleftrightarrow{D}_\mu\gamma_\nu(\Sigma_R P_R-\Sigma_L P_L) q]\;,\notag\\
\mathcal{O}_{25}^{(8)}&=(\bar \nu_L\overleftrightarrow{D}^\mu e_R)[\bar q\overleftrightarrow{D}_\mu(\Sigma^\dagger P_R+\Sigma P_L) q]\;,
&
\mathcal{O}_{26}^{(8)}&=(\bar \nu_L\overleftrightarrow{D}^\mu e_R)[\bar q\overleftrightarrow{D}_\mu(\Sigma^\dagger P_R-\Sigma P_L) q]\;,\notag\\
\mathcal{O}_{27}^{(8)}&=(\bar \nu_L\gamma^\mu e_L)D^2[\bar q\gamma_\mu(\Sigma_R P_R+\Sigma_L P_L) q]\;,
&
\mathcal{O}_{28}^{(8)}&=(\bar \nu_L\gamma^\mu e_L)D^2[\bar q\gamma_\mu(\Sigma_R P_R-\Sigma_L P_L) q]\;,\notag\\
\mathcal{O}_{29}^{(8)}&=(\bar \nu_L e_R)D^2[\bar q(\Sigma^\dagger P_R+\Sigma P_L) q]\;,
&
\mathcal{O}_{30}^{(8)}&=(\bar \nu_L e_R)D^2[\bar q(\Sigma^\dagger P_R-\Sigma P_L) q]\;,\notag\\
\mathcal{O}_{31}^{(8)}&=(\bar \nu_L\sigma^{\mu\nu}e_R)D^2[\bar q\sigma_{\mu\nu}(\Sigma^\dagger P_R+\Sigma P_L) q]\;.
\end{align}





We establish the following results:
\begin{itemize}
    \item The operators $\mathcal{O}_{7-16}^{(8)}$, $\mathcal{O}_{21-22}^{(8)}$ and $\mathcal{O}_{27-31}^{(8)}$, which involve two derivatives in the quark sector, can be matched to the chiral Lagrangian using the external source method. For example, the operator $(\bar e e)\partial^2[\bar q(\Sigma^\dagger P_R+\Sigma P_L)q]$ can match to $(\bar{e}e)\nabla^2\langle\Sigma_+\rangle$ as the scalar operators.
    \item The operators $\mathcal{O}_{17-20}^{(8)}$ and $\mathcal{O}_{25-26}^{(8)}$ can also be incorporated into the framework through the EOMs, similar to the treatment of dimension-7 operators.
    \item The operators $\mathcal{O}_{1-6}^{(8)}$ and $\mathcal{O}_{23-24}^{(8)}$ cannot be matched onto the chiral Lagrangian via the external source method.
\end{itemize}



