    \end{pmatrix}
    &\to 
    \begin{pmatrix}
        1 & 1 & -2\\
        1 & 1 & 2\\
    \end{pmatrix}
    \begin{pmatrix}
        \langle\Sigma_{+}\Sigma_{+}\rangle\\
        \langle\Sigma_{-}\Sigma_{-}\rangle\\
        \langle\Sigma_{-}\Sigma_{+}\rangle
    \end{pmatrix}\;.
\end{align}
It is noted that each four-quark operator in the chiral basis corresponds to an independent LEC after matching. 

The chiral operators can be explicitly expanded in terms of the $U$ field as follows
\begin{align}
    \langle Q_{+}Q_{+}\rangle&=
    2\langle U^\dagger \tau^+U\tau^+\rangle\;,\notag\\
    \langle Q_{-}Q_{-}\rangle&=
    -2\langle U^\dagger\tau^+U\tau^+\rangle\;,\notag\\
    \langle Q_{-}Q_{+}\rangle&=\langle U^\dagger\tau^+U\tau^+\rangle-\langle U\tau^+U^\dagger\tau^+\rangle\;,\notag\\
    \langle \Sigma_{+}\Sigma_{+}\rangle &= \langle U\tau^+U\tau^+\rangle + \langle U^\dagger\tau^+U^\dagger\tau^+\rangle \;,\notag\\
    \langle \Sigma_{-}\Sigma_{-}\rangle &= \langle U\tau^+U\tau^+\rangle + \langle U^\dagger\tau^+U^\dagger\tau^+\rangle \;,\notag\\
    \langle \Sigma_{-}\Sigma_{+}\rangle &= \langle U\tau^+U\tau^+\rangle - \langle U^\dagger\tau^+U^\dagger\tau^+\rangle \;.
\end{align}
In this case, we obtain LO matching yielding
\begin{align}
    \langle Q_{-} Q_{+} \rangle =0\;,
\end{align}
while 
\begin{align}
O_{1}^{(9)} &\to -2 \langle U^\dagger \tau^+ U \tau^+ \rangle + 2 \langle U^\dagger \tau^+ U \tau^+ \rangle =  0\;, \\
O_{4}^{(9)} &\to -2 \langle U^\dagger \tau^+ U \tau^+ \rangle - 2 \langle U^\dagger \tau^+ U \tau^+ \rangle = -4 \langle U^\dagger \tau^+ U \tau^+\rangle \;,\\
O_{2}^{(9)} &\to 2 \langle U^\dagger \tau^+ U^\dagger \tau^+ \rangle + 2 \langle U^\dagger \tau^+ U^\dagger \tau^+ \rangle = 4 \langle U\tau^+U\tau^+\rangle\;.
\end{align}
The color-mixed operators follow analogous matching relations:
\begin{align}
O_{3}^{(9)} &\to 4 \langle U\tau^+U\tau^+\rangle\;,\\
O_{5}^{(9)} &\to -4 \langle U^\dagger \tau^+ U \tau^+\rangle \;.
\end{align}
The matching for parity-conjugate operators is obtained through the substitution $U \leftrightarrow U^\dagger$, which is expressed as
\begin{align}
O_{1}^{(9)\prime} &\to 0\;, \\
O_{2}^{(9)\prime} &\to 4 \langle U^\dagger\tau^+U^\dagger\tau^+\rangle\;,\\
O_{3}^{(9)\prime} &\to 4 \langle U^\dagger\tau^+U^\dagger\tau^+\rangle\;.
\end{align}
These results are in complete agreement with those presented in Refs.~\cite{Cirigliano:2018yza,Prezeau:2003xn}.


From Tab.~\ref{tab:operator_matching} and Eq.~\eqref{eq:O45-03}, we obtain the matching for parity-even operators
\begin{align}
   O_{4 +}^{++, \mu} = - O_{AP} &\to -\langle Q_{+}\nabla^\mu\Sigma_{+}\rangle \sim  \pi^- \partial^\mu \pi^- \;,\\
   O_{5 +}^{++, \mu} = O_{VS} &\to \langle Q_{-}\nabla^\mu\Sigma_{-}\rangle \sim \pi^- \partial^\mu \pi^-\;.
\end{align}
Both contributions to the $0\nu\beta\beta$ decay amplitude are suppressed by the electron mass using
the IBPs,
rendering them negligible. This is consistent with the finding in Ref.~\cite{Prezeau:2003xn}. 


