\section{Some useful identities}
\label{app:identities}
%%----------------------------


The following identities facilitate comparison between results derived from the external source method and conventional spurion techniques:
\begin{align}
\label{eq:identity1}
    \left(D_\mu u\right) u^{\dagger}&=-u\left(D_\mu u\right)^{\dagger}\;,&
    u^{\dagger} \left(D_\mu u\right) &=-\left(D_\mu u\right)^{\dagger}u\;,\\
    \left(u D_\mu u^\dagger \right)^{\dagger} & = - u D_\mu u^\dagger\;,&
    \left(u^\dagger D_\mu u \right)^{\dagger} &= - u^\dagger D_\mu u\;,
\end{align}
and
\begin{align}
\label{eq:identity2}
    u D_\mu u^\dagger &= U \partial_\mu U^\dagger/2 \;,&
    u^\dagger D_\mu u &= U^\dagger \partial_\mu U/2\;,\\
    u^\dagger D_\mu u^\dagger &= \partial_\mu U^\dagger/2\;,&
    u D_\mu u &= \partial_\mu U/2\;.
\end{align}
Note that the relations in Eqs.~\eqref{eq:identity1}~\eqref{eq:identity2} were also given in Ref.~\cite{Liao:2019gex}.


The following identities are useful for  comparing results between the systematic and conventional spurion methods:
\begin{align}
\label{eq:u-mu-relations}
    u D^\mu u^\dagger &= \dfrac{i}{2} u \hat u^\mu u^\dagger\;,&
    u^\dagger D^\mu u &= - \dfrac{i}{2} u^\dagger \hat u^\mu u\;,\\
    u^\dagger D^\mu u^\dagger &= \dfrac{i}{2} u^\dagger \hat u^\mu u^\dagger\;,&
    u D^\mu u &= - \dfrac{i}{2} u \hat u^\mu u\;.
\end{align}


