\section{Discussions and examples of tensor interactions}
\label{app:tensor}
%%----------------------------

In this appendix, we will provide expanded discussions on matching for quark tensor interactions. 
Given the tensor interactions in Eq.~\eqref{eq:lambt}, we have 
\begin{align}
    \mathcal{L}_{T}^q &= \bar{q} \sigma_{\mu\nu} \lambda_T^{\mu\nu} q+ \dfrac{i}{2}\bar{q} \sigma_{\mu\nu} \varepsilon^{\mu\nu}{}_{\alpha\beta} \lambda_\varepsilon^{\alpha\beta} q\;,
\end{align}
by using the relation in Eq.~\eqref{eq:epsilon}, which implies that the operator of the form $\sigma_{\mu\nu} \gamma^5$ is redundant.  The tensor interaction at the quark-level in the external source method is
\begin{align}
\label{eq:tensor-source}
    \mathcal{L}_{\text{ext},\, T} = \bar{q} \sigma_{\mu \nu} \bar{t}^{\mu \nu} q\;,
\end{align}
where $\bar{t}^{\mu \nu}$ can be obtained from $\lambda_T^{\mu\nu}$ and $\lambda_\varepsilon^{\mu\nu}$ as in Eq.~\eqref{eq:tbar-lambda}. 


Introducing the chiral projectors
\begin{align}
    P_R^{\mu \nu \lambda \rho} = \frac{1}{4}\left(g^{\mu \lambda} g^{\nu \rho} - g^{\nu \lambda} g^{\mu \rho} + i \varepsilon^{\mu \nu \lambda \rho}\right) = \left(P_L^{\mu \nu \lambda \rho}\right)^{\dagger}\;,
\end{align}
one can express the tensor interaction as~\cite{Cata:2007ns}
\begin{align}
\label{eq:tensor_Lag}
    \mathcal{L}_{\text{ext},\, T} =  \bar{q}_L \sigma_{\mu \nu} t^{\mu \nu \dagger} q_R + \bar{q}_R \sigma_{\mu \nu} t^{\mu \nu} q_L\;,
\end{align}
with the relations
\begin{align}
    \label{eq:tensor1}
   \bar{t}^{\mu\nu} &= P_L^{\mu\nu \lambda \rho} t_{\lambda \rho} + P_R^{\mu\nu \lambda \rho} t_{\lambda \rho}^\dagger\;,\\
   \label{eq:tensor2}
   t^{\mu \nu} &= P_L^{\mu \nu \lambda \rho} \bar{t}_{\lambda \rho}\;.
\end{align}



The projectors $P_{L/R}^{\mu \nu \lambda \rho}$ are anti-symmetric under the interexchange of $\mu $ and $ \nu$. Thus the tensor sources $\bar{t}^{\mu\nu}$ and $t^{\mu \nu}$ in Eqs.~\eqref{eq:tensor1}~\eqref{eq:tensor2}  are anti-symmetric. However, when considering BSM interactions, they may not be anti-symmetric. In such cases, one could first anti-symmetrize the interactions as in Ref.~\cite{Li:2021phq}.

From Eq.~\eqref{eq:tensor-ubasis}~\eqref{eq:tensor}, we obtain that the interaction with mesons in the chiral Lagrangian is
\begin{align}
\label{eq:tensor-p4-pi}
    \Delta \mathcal{L}_{4,\pi}^\prime = - \dfrac{i}{2} \Lambda_2 \langle ( u^{\dagger}t^{\mu\nu}u^{\dagger} + ut^{\mu\nu\dagger}u) [\hat u_\mu, \hat u_\nu] \rangle\;.
\end{align}



To compare the matching for tensor interactions using different methods, we consider the dimension-6 LEFT operator $\mathcal{O}_{11}^{(6)}$, which describes the neutral-current interaction between electron and $u$ quark, 
\begin{align}
    \mathcal{L}_{\rm eff, 11}^{(6)} = \mathcal{C}_{11}^{(6)}
    \left(\bar{e} \sigma^{\mu \nu} e\right) \left(\bar{u} \sigma_{\mu \nu} u\right) = \mathcal{C}_{11}^{(6)}
    \left(\bar{e} \sigma^{\mu \nu} e\right) \left(\bar{q} \sigma_{\mu \nu} \tau^p q\right)\;.
\end{align}
The tensor source is defined as follows
\begin{align}
    \bar{t}_{\mu\nu} &= \mathcal{C}_{11}^{(6)} \left(\bar{e} \sigma^{\mu \nu} e\right) \tau^p \;.
\end{align}
Using Eq.~\eqref{eq:tensor2}, we obtain
\begin{align}
\label{eq:tensor-missing}
   t^{\mu\nu} &=  P_L^{\mu \nu \lambda \rho} \bar{t}_{\lambda \rho} = \frac{1}{2} \mathcal{C}_{11}^{(6)} \bar{e} \left(\sigma^{\mu \nu} - \frac{i}{2} \varepsilon^{\mu\nu\alpha\beta} \sigma_{\alpha\beta}\right) e\,  \tau^p \;,\nn\\
   t^{\mu\nu\dagger} &= P_R^{\mu \nu \lambda \rho} \bar{t}_{\lambda \rho} = \frac{1}{2} \mathcal{C}_{11}^{(6)} \bar{e} \left(\sigma^{\mu \nu} + \frac{i}{2} \varepsilon^{\mu\nu\alpha\beta} \sigma_{\alpha\beta}\right) e\, \tau^p\;.
\end{align}




In the chiral basis, the interactions are expressed as
\begin{align}
    \mathcal{L}_{\rm eff, 11}^{(6)} = \mathcal{C}_{11}^{(6)}
    \left(\bar{e} \sigma^{\mu \nu} e\right) \left(\bar{q}_L \sigma_{\mu \nu} \tau^p q_R\right) +  \mathcal{C}_{11}^{(6)}
    \left(\bar{e} \sigma^{\mu \nu} e\right) \left(\bar{q}_R \sigma_{\mu \nu} \tau^p q_L\right)\;,
\end{align}
then spurions in Eq.~\eqref{eq:tensormatching} are given by
\begin{align}
    \lambda^{\mu\nu\dagger} = \lambda^{\mu\nu} =  \mathcal{C}_{11}^{(6)} \bar{e} \sigma^{\mu \nu} e \, \tau^p\;.
\end{align}


From Eq.~\eqref{eq:Xmunu}, we find
\begin{align}
    X^{\mu\nu\dagger}& = \frac{1}{2}\lambda_{\mu\nu}^\dagger+\frac{i}{4}\varepsilon_{\mu\nu\alpha\beta}\lambda^{\alpha\beta\dagger}=\dfrac{1}{2} \mathcal{C}_{11}^{(6)} \bar{e} \left(\sigma^{\mu \nu} + \frac{i}{2} \varepsilon^{\mu\nu\alpha\beta} \sigma_{\alpha\beta}\right)e \, \tau^p =t^{\mu\nu \dagger}\;,\nn\\
    X^{\mu\nu}& = \frac{1}{2}\lambda_{\mu\nu}-\frac{i}{4}\varepsilon_{\mu\nu\alpha\beta}\lambda^{\alpha\beta}=\dfrac{1}{2} \mathcal{C}_{11}^{(6)} \bar{e} \left(\sigma^{\mu \nu} - \frac{i}{2} \varepsilon^{\mu\nu\alpha\beta} \sigma_{\alpha\beta}\right)e \, \tau^p =t^{\mu\nu }\;.
\end{align}
The matched chiral Lagrangian is provided in Eq.~\eqref{eq:tensor-X}. 
Therefore, if the LECs satisfy $g_{T}^{(2)} = g_{T}^{(2)\prime}$, the results obtained using the external source method and the systematic spurion method are consistent with the following correspondence
\begin{align}
    g_T^{(2)} = 2i \Lambda_2\;,
\end{align}
where the factor $i$ arises because $[\hat u_\mu, \hat u_\nu]$ is anti-Hermitian. 







Moreover, the combination of $\lambda^{\mu\nu}$ and $\lambda^{\mu\nu\dagger}$ yields 
\begin{align}
    \lambda_T^{\mu\nu} = \mathcal{C}_{11}^{(6)} \bar{e} \sigma^{\mu \nu} e \, \tau^p = \bar t^{\mu\nu}\;,\quad
    \lambda_\varepsilon^{\mu\nu} = 0\;.
\end{align}
Thus, the matching in the conventional spurion method can also be achieved in the $q$ basis, as indicated in Eq.~\eqref{eq:mathcing-t_non-chiral}. Since $\lambda^\dagger =\lambda = \lambda_T$, we can express 
\begin{align}
    \mathcal{L}_{\rm eff, 11}^{(6)}  \to & -\frac{1}{8}\mathrm{Tr}\left[(u\lambda^{\mu\nu\dagger}u+u^{\dagger}\lambda^{\mu\nu}u^{\dagger})[\hat{u}_{\mu},\hat{u}_{\nu}]\right]g_{T}^{(2)} \nn\\
 & -\frac{i}{16}\varepsilon_{\mu\nu\alpha\beta}\operatorname{Tr}\left[(u\lambda^{\alpha\beta\dagger}u-u^\dagger\lambda^{\alpha\beta}u^\dagger)[\hat{u}^\mu,\hat{u}^\nu]\right]g_T^{(2)\prime}\;,
\end{align}
which agrees with the results from the external source method under the assumption that $g_{T}^{(2)} = g_{T}^{(2)\prime}$. 



In the systematic spurion method, we have
\begin{align}
    \mathcal{L}_{\rm eff, 11}^{(6)} = \mathcal{C}_{11}^{(6)}(\bar{e}\sigma^{\mu\nu}e)[\bar{q}\sigma^{\mu\nu}(\Sigma^{\dagger}P_{R}+\Sigma P_{L})q]\;,
\end{align}
where $\Sigma^\dagger = \Sigma = \tau^p$. The matching at $p^4$ order is given by
\begin{align}
\label{eq:factor-i}
    \mathcal{L}_{\rm eff, 11}^{(6)}  \to &\, \mathcal{C}_{11}^{(6)} \left[ (\bar{e}\sigma^{\mu\nu}e)\langle\Sigma_+[\hat{u}_\mu,\hat{u}_\nu]\rangle  i \beta_1 + (\bar{e}\gamma^{5}\sigma^{\mu\nu}e)\langle\Sigma_{-}[\hat{u}_{\mu},\hat{u}_{\nu}]\rangle i \beta_2 \right]\;,
\end{align}
where we have used the relation in Eq.~\eqref{eq:epsilon}. Here, $\beta_1$ and $\beta_2$ are the LECs, and the building blocks $\Sigma_\pm$ are defined in Eq.~\eqref{eq:building}.
Note that we have included the factor $i$ has been included to maintain the Hermiticity of the chiral Lagrangian.

Utilizing the relation in Eq.~\eqref{eq:epsilon}, we find that the results from the conventional spurion method are consistent, and the LECs satisfy
\begin{align}
    i\beta_1 = -\dfrac{1}{8} g_T^{(2) }\;,\quad 
    i\beta_2 = -\dfrac{1}{8} g_T^{(2) \prime}\;. 
\end{align}

Similarly, for the dimension-6 operator $\mathcal{O}_{12}^{(6)}$, we have
\begin{align}
    \mathcal{L}_{\rm eff, 12}^{(6)} = &\, \mathcal{C}_{12}^{(6)}(\bar{e}i \gamma^5 \sigma^{\mu\nu}e)[\bar{q}\sigma^{\mu\nu}(\Sigma^{\dagger}P_{R}+\Sigma P_{L})q]\;,\nn\\
    \to & \, \mathcal{C}_{12}^{(6)} \left[ (\bar{e}i \gamma^5\sigma^{\mu\nu}e)\langle\Sigma_+[\hat{u}_\mu,\hat{u}_\nu]\rangle  \beta_1 + (\bar{e} i\sigma^{\mu\nu}e)\langle\Sigma_{-}[\hat{u}_{\mu},\hat{u}_{\nu}]\rangle \beta_2 \right]\;.
\end{align}


If the lepton interactions are defined in the chiral basis, 
\begin{align}
    \mathcal{L}_{\rm eff,\, LR}^{(6)} = \left[ \mathcal{C}_{LR}(\bar{e}_L\sigma^{\mu\nu}e_R) +\mathcal{C}_{LR}^\dagger (\bar{e}_R \sigma^{\mu\nu}e_L)\right][\bar{q}\sigma^{\mu\nu}(\Sigma^{\dagger}P_{R}+\Sigma P_{L})q]\;,
\end{align}
where the Wilson coefficient $\mathcal{C}_{LR}$ is generally complex. The matching for the terms $\bar{e}_L\sigma^{\mu\nu}e_R$ and $\bar{e}_R \sigma^{\mu\nu}e_L$ results in
\begin{align}
    &(\bar{e}_L\sigma^{\mu\nu}e_R) [\bar{q}\sigma^{\mu\nu}(\Sigma^{\dagger}P_{R}+\Sigma P_{L})q] \nn\\
    &\quad\to (\bar{e}_L\sigma^{\mu\nu}e_R)\langle\Sigma_+[\hat{u}_\mu,\hat{u}_\nu]\rangle i \beta_1 + (\bar{e}_L\sigma^{\mu\nu}e_R)\langle\Sigma_-[\hat{u}_\mu,\hat{u}_\nu]\rangle i \beta_2\;,\nn\\
    &(\bar{e}_R\sigma^{\mu\nu}e_L) [\bar{q}\sigma^{\mu\nu}(\Sigma^{\dagger}P_{R}+\Sigma P_{L})q] \nn\\
    &\quad\to (\bar{e}_R\sigma^{\mu\nu}e_L)\langle\Sigma_+[\hat{u}_\mu,\hat{u}_\nu]\rangle i \beta_1 - (\bar{e}_R\sigma^{\mu\nu}e_L)\langle\Sigma_-[\hat{u}_\mu,\hat{u}_\nu]\rangle i \beta_2\;.
\end{align}
Thus, we obtain 
\begin{align}
    \mathcal{L}_{\rm eff,\, LR}^{(6)}  \to & \,\left[ \mathcal{C}_{LR}(\bar{e}_L\sigma^{\mu\nu}e_R) +\mathcal{C}_{LR}^\dagger (\bar{e}_R \sigma^{\mu\nu}e_L)\right] \langle\Sigma_+[\hat{u}_\mu,\hat{u}_\nu]\rangle i \beta_1\nn\\
    &+ \left[ \mathcal{C}_{LR}(\bar{e}_L\sigma^{\mu\nu}e_R) -\mathcal{C}_{LR}^\dagger (\bar{e}_R \sigma^{\mu\nu}e_L)\right] \langle\Sigma_-[\hat{u}_\mu,\hat{u}_\nu]\rangle i \beta_2\;.
\end{align}
From the above, we see that the LECs $\beta_1$ and $\beta_2$ are real.  


Assuming both operators $\mathcal{O}_{11}^{(6)}$ and $\mathcal{O}_{12}^{(6)}$ are present, 
\begin{align}
    \mathcal{C}_{LR} = \mathcal{C}_{11}^{(6)}+i\,\mathcal{C}_{12}^{(6)}\;,
\end{align}
where $\mathcal{C}_{11}^{(6)}$ and $\mathcal{C}_{12}^{(6)}$ are real. 
The matching result becomes
\begin{align}
    \mathcal{L}_{\rm eff,\, LR}^{(6)}  \to & \, \mathcal{C}_{11}^{(6)} \left[ (\bar{e}\sigma^{\mu\nu}e)\langle\Sigma_+[\hat{u}_\mu,\hat{u}_\nu]\rangle  i \beta_1 + (\bar{e}\gamma^{5}\sigma^{\mu\nu}e)\langle\Sigma_{-}[\hat{u}_{\mu},\hat{u}_{\nu}]\rangle i \beta_2 \right]\nn\\
   &+ \mathcal{C}_{12}^{(6)} \left[ (\bar{e}i \gamma^5\sigma^{\mu\nu}e)\langle\Sigma_+[\hat{u}_\mu,\hat{u}_\nu]\rangle  i \beta_1 + (\bar{e} i\sigma^{\mu\nu}e)\langle\Sigma_{-}[\hat{u}_{\mu},\hat{u}_{\nu}]\rangle i \beta_2 \right]\;.
\end{align}
Therefore, we can obtain the same results if the operators are defined with chiral lepton fields. 


If the operators are defined with chiral quark fields~\cite{Jenkins:2017jig}
\begin{align}
    \mathcal{L}_{{\rm eff}, eu}^{(6)} = \mathcal{O}_{eu}^{T,RR} (\bar{e}_{L}\sigma^{\mu\nu}e_{R})(\bar{u}_{L}\sigma_{\mu\nu}u_{R}) + {\rm h.c.}\;,
\end{align}
we can use the relation in Eq.~\eqref{eq:epsilon} to show 
\begin{align}
    \mathcal{L}_{{\rm eff},\, eu}^{(6)} = \mathcal{C}_{eu}^{T,RR} (\bar{e}_{L}\sigma^{\mu\nu}e_{R})(\bar{u}\sigma_{\mu\nu}u) + {\rm h.c.}\;.
\end{align}
This result can also be derived using the Fierz identity. For instance, as shown in Ref.~\cite{Liao:2020jmn}, the following relation holds for Dirac fields $\psi_{1,2,3,4}$:
\begin{align}
    (\bar{\psi}_1\sigma^{\mu\nu}P_R\psi_2)(\bar{\psi}_3\sigma_{\mu\nu}P_L \psi_4)=0\;.
\end{align}
Then, one can perform the matching for $\mathcal{L}_{{\rm eff},\, eu}^{(6)}$ as that for $\mathcal{L}_{\rm eff,\, LR}^{(6)}$.



The above discussion can also be applied to the operator $\mathcal{O}_{17}^{(6)}$, which describes the charged-current neutrino non-standard interaction,
\begin{align}
    \mathcal{L}_{\rm eff, 17}^{(6)} 
    &\equiv \mathcal{C}_{17}^{(6)} \left(\bar{\nu}_L \sigma^{\mu \nu} e_R\right) \left(\bar{d} \sigma_{\mu \nu} u\right) + {\rm h.c.}\;.
\end{align}
In the basis of Ref.~\cite{Jenkins:2017jig}, the interaction is written as
\begin{align}
\label{eq:nuedu}
    \mathcal{L}_{{\rm eff},\, \nu edu}^{(6)} = 
    \mathcal{C}_{\nu edu}^{T,RR}  (\bar{\nu}_{L}\sigma^{\mu\nu}e_{R})(\bar{d}_{L}\sigma_{\mu\nu}u_{R}) + {\rm h.c.}\;.
\end{align}
Using the relation in Eq.~\eqref{eq:epsilon}  or the Fierz identity, we obtain
\begin{align}
     \mathcal{L}_{{\rm eff},\, \nu edu}^{(6)} = \mathcal{C}_{\nu edu}^{T,RR} 
    \left(\bar{\nu}_L \sigma^{\mu \nu} e_R\right) \left(\bar{d} \sigma_{\mu \nu} u\right) + {\rm h.c.}\;,
\end{align}
which indicates that $\mathcal{C}_{\nu edu}^{T,RR} =\mathcal{C}_{17}^{(6)}$.
In comparison with Eq.~\eqref{eq:tensor-source}, we get
\begin{align}
    \bar t^{\mu\nu} =\mathcal{C}_{17}^{(6)} (\bar{\nu}_{L}\sigma^{\mu\nu}e_{R}) \tau^- + {\rm h.c.}\;,
\end{align}
which can also be obtained with Eqs.~\eqref{eq:tbar-lambda}~\eqref{eq:nuedu}.

Using the chiral projectors, we obtain the tensor source
\begin{align}
   t^{\mu\nu} =  P_L^{\mu \nu \lambda \rho} \bar{t}_{\lambda \rho} &= \frac{1}{2} \mathcal{C}_{17}^{(6)} \bar{\nu}_L \left(\sigma^{\mu \nu} - \frac{i}{2} \varepsilon^{\mu\nu\alpha\beta} \sigma_{\alpha\beta}\right) e_R\,  \tau^- \nn\\
   &\quad +  \frac{1}{2} \mathcal{C}_{17}^{(6)\dagger} \bar{e}_R \left(\sigma^{\mu \nu} - \frac{i}{2} \varepsilon^{\mu\nu\alpha\beta} \sigma_{\alpha\beta}\right) \nu_L\,  \tau^+ \;,\nn\\
   t^{\mu\nu\dagger} = P_R^{\mu \nu \lambda \rho} \bar{t}_{\lambda \rho} &= \frac{1}{2} \mathcal{C}_{17}^{(6)} \bar{\nu}_L \left(\sigma^{\mu \nu} + \frac{i}{2} \varepsilon^{\mu\nu\alpha\beta} \sigma_{\alpha\beta}\right) e_R\, \tau^- \nn\\
   &\quad +  \frac{1}{2} \mathcal{C}_{17}^{(6)\dagger} \bar{e}_R \left(\sigma^{\mu \nu} + \frac{i}{2} \varepsilon^{\mu\nu\alpha\beta} \sigma_{\alpha\beta}\right) \nu_L\,  \tau^+ 
\end{align}
The chiral Lagrangian can thus be obtained from Eq.~\eqref{eq:tensor-p4-pi} in the external source method. 

In the conventional spurion method, the interaction is expressed in the chiral basis as follows 
\begin{align}
    \mathcal{L}_{{\rm eff}, 17}^{(6)} = \mathcal{C}_{17}^{(6)} (\bar{\nu}_{L}\sigma^{\mu\nu}e_{R})(\bar{q}_{L}\sigma_{\mu\nu} \tau^- q_{R}) + \mathcal{C}_{17}^{(6)} (\bar{\nu}_{L}\sigma^{\mu\nu}e_{R})(\bar{q}_{R}\sigma_{\mu\nu} \tau^- q_{L}) + {\rm h.c.}\;,
\end{align}
so that the spurions in Eq.~\eqref{eq:tensormatching} are
\begin{align}
    \lambda^{\mu\nu\dagger} &=  \mathcal{C}_{17}^{(6)} \bar{\nu}_L \sigma^{\mu \nu} e_R \, \tau^- + \mathcal{C}_{17}^{(6)\dagger} \bar{e}_R \sigma^{\mu \nu} \nu_L \, \tau^+ \;,\nn\\
    \lambda^{\mu\nu} &=  \mathcal{C}_{17}^{(6)\dagger} \bar{e}_R \sigma^{\mu \nu} \nu_L \, \tau^+  +   \mathcal{C}_{17}^{(6)} (\bar{\nu}_{L}\sigma^{\mu\nu}e_{R}) \tau^-\;.
\end{align}
From Eq.~\eqref{eq:Xmunu}, we have
\begin{align}
    X^{\mu\nu \dagger}& = \frac{1}{2}\lambda_{\mu\nu}^\dagger+\frac{i}{4}\varepsilon_{\mu\nu\alpha\beta}\lambda^{\alpha\beta\dagger} = t^{\mu\nu \dagger}\nn\\
    X^{\mu\nu}& = \frac{1}{2}\lambda_{\mu\nu}-\frac{i}{4}\varepsilon_{\mu\nu\alpha\beta}\lambda^{\alpha\beta}  = t^{\mu\nu} \;.
\end{align}



Besides, the combination of $\lambda^{\mu\nu}$ and $\lambda^{\mu\nu\dagger}$ gives 
\begin{align}
    \lambda_T^{\mu\nu} =\mathcal{C}_{17}^{(6)} (\bar{\nu}_{L}\sigma^{\mu\nu}e_{R}) \tau^- + {\rm h.c.} = \bar t^{\mu\nu}\;,\quad
    \lambda_\varepsilon^{\mu\nu} = 0\;.
\end{align}
Thus, the matching in the conventional spurion method can also be achieved in the $q$ basis, as indicated in Eq.~\eqref{eq:mathcing-t_non-chiral}. Since $\lambda^\dagger =\lambda = \lambda_T$, we can express 
\begin{align}
    \mathcal{L}_{\rm eff, 17}^{(6)}  \to & -\frac{1}{8}\mathrm{Tr}\left[(u\lambda^{\mu\nu\dagger}u+u^{\dagger}\lambda^{\mu\nu}u^{\dagger})[\hat{u}_{\mu},\hat{u}_{\nu}]\right]g_{T}^{(2)} \nn\\
 & -\frac{i}{16}\varepsilon_{\mu\nu\alpha\beta}\operatorname{Tr}\left[(u\lambda^{\alpha\beta\dagger}u-u^\dagger\lambda^{\alpha\beta}u^\dagger)[\hat{u}^\mu,\hat{u}^\nu]\right]g_T^{(2)\prime}\;,
\end{align}
which agrees with the results from the external source method under the assumption that $g_{T}^{(2)} = g_{T}^{(2)\prime}$. 

In the systematic spurion method, 
\begin{align}
\mathcal{L}_{{\rm eff}, 17} = \mathcal{C}_{17}^{(6)}(\bar{\nu}_L\sigma^{\mu\nu}e_R)[\bar{q}\sigma_{\mu\nu}(\Sigma^\dagger P_R+\Sigma P_L)q] + {\rm h.c.}\;,
\end{align}
where $\Sigma^\dagger = \Sigma = \tau^-$. The matching at $p^4$ order is 
\begin{align}
\mathcal{L}_{\mathrm{eff},17}^{(6)}\to\mathcal{C}_{17}^{(6)}\left[(\bar{\nu}_L\sigma^{\mu\nu}e_R)\langle\Sigma_{+}[\hat{u}_{\mu},\hat{u}_{\nu}]\rangle i\beta_{1}+(\bar{\nu}_L\sigma^{\mu\nu}e_R)\langle\Sigma_{-}[\hat{u}_{\mu},\hat{u}_{\nu}]\rangle i\beta_{2}\right] + {\rm h.c.}\;.
\end{align}





%%----------------------------------------------
\section{Matching for derivative operators
}
\label{sec:dim-7_derivative}
%%----------------------------------------------

In this appendix, we will give details of matching the dimension-7 derivative operators with single quark bilinear to the chiral Lagrangian in the conventional spurion method. 

The interaction with one partial derivative acting on the quark field is expressed as
\begin{align}
\mathcal{L}_{D,D5}^q &= \bar{q}_L \lambda_1 \overleftrightarrow{\partial}^\mu q_R + \bar{q}_R \lambda_2 \overleftrightarrow{\partial}^\mu q_L + \text{h.c.} \\
&= \bar{q}_L (-i\lambda)^\dagger \overleftrightarrow{\partial}^\mu q_R - \bar{q}_R (-i\lambda) \overleftrightarrow{\partial}^\mu q_L\;,
\end{align}
where the Hermitian spurion is $\lambda \equiv i(\lambda_1^\dagger - \lambda_2)$. The quark-level Lagrangian is matched to chiral Lagrangian $\mathcal{L}_{D,D5}^{(d)}$, 
\begin{align}
    \mathcal{L}_{D,D5}^q &= i \left( \bar{q}_L \lambda^\dagger \partial_\mu q_R - \partial_\mu \bar{q}_L \lambda^\dagger q_R \right) + \text{h.c.} \to \mathcal{L}_{D,D5}^{(d)}\;.
\end{align}
where $d$ represents the number of derivatives.

At $\mathcal{O}(p^2)$, the chiral Lagrangian is
\begin{align}
\mathcal{L}_{D,D5}^{(1)} &= i \Tr\left[ u \lambda^\dagger (D^\mu u^\dagger)^\dagger \right] g_{D,1}^{(1)} 
- i \Tr\left[ D^\mu u \lambda^\dagger u \right] g_{D,2}^{(1)} + \text{h.c.}\;.
\end{align}
Expressed in terms of $U$ or $\hat{u}^\mu$, one has
\begin{align}
\mathcal{L}_{D,D5}^{(1)} &= \frac{i}{2} \Tr\left( \lambda^\dagger \partial_\mu U - \lambda \partial_\mu U^\dagger \right) \tilde{g}_{D}^{(1)} \;, \quad \tilde{g}_{D}^{(1)} \equiv g_{D,1}^{(1)} - g_{D,2}^{(1)}\;,
\end{align}
or equivalently,
\begin{align}
\mathcal{L}_{D,D5}^{(1)} &= \frac{1}{2} \Tr\left[\left( u\lambda^\dagger u + u^\dagger \lambda u^\dagger \right) \hat{u}_\mu \right] \tilde{g}_{D}^{(1)}\;.
\end{align}


Similar to tensor current in Sec.~\ref{sec:tensor-current}, we consider the $C$ transformation, 
\begin{align}
    \mathcal{L}_{D,D5}^q &\stackrel{C}{\longrightarrow} -i \left(\bar{q}_L \lambda^{c \dagger} 
 \overleftrightarrow{\partial}^\mu  q_R + \bar{q}_R \lambda^c\overleftrightarrow{\partial}^\mu  q_L\right)\;,  
\end{align}
where
$\lambda^c$ and $\lambda^{c\dagger}$ are defined as in Eq.~\eqref{eq:lambda-c}.
The above relation shows that the chiral Lagrangian $\mathcal{L}_D^{(1)}$ 
has wrong sign under the $C$ transformation. 




Analogous to the tensor current case, we introduce the commutator, which transforms as
\begin{align}
\left[ \nabla_\mu \hat{u}_\nu, \hat{u}^\nu \right] &\stackrel{C}{\longrightarrow} \left[ (\nabla_\mu \hat{u}_\nu)^T, \left(\hat{u}^\nu\right)^T \right]\;,
\end{align}
yielding the correct transformation property as follows:
\begin{align}
    \Tr \left[ \left( u \lambda^\dagger u + u^\dagger \lambda u^\dagger\right) [\nabla_\mu \hat{u}_\nu, \hat{u}^\nu \right]  \stackrel{C}{\longrightarrow}&\ - \Tr \left[ \left( u \lambda^\dagger_c u + u^\dagger \lambda_c u^\dagger\right) [\nabla_\mu \hat{u}_\nu, \hat{u}^\nu] \right]\;.
\end{align}
The consistent chiral Lagrangian emerges at $\mathcal{O}(p^4)$ with $d=3$, which is expressed as
\begin{align}
\label{eq:derivative}
\mathcal{L}_{D,D5}^{(3)} &= \Tr \left[ \left( u\lambda^\dagger u + u^\dagger \lambda u^\dagger \right) \left[ \nabla_\mu \hat{u}_\nu, \hat{u}^\nu \right] \right] \tilde{g}_{D}^{(3)}.
\end{align}


Notice that in case of vanishing fied strength, $\nabla_\mu \hat{u}_\nu - \nabla_\nu \hat{u}_\mu = 0$, and $ \left[ \nabla_\nu \hat{u}_\mu, \hat{u}^\nu \right]$ is redundant in constructing the chiral Lagrangian. On the other hand, the commutator $\left[  \hat{u}_\mu, \nabla_\nu \hat{u}^\nu \right]$ gives rise to an independent chiral operator, which corresponds to the chiral operators with $\left\langle\hat{u}_\mu\left[\Sigma_{+}, \chi_{-}\right]\right\rangle$ or $\left\langle\hat{u}_\mu\left[\Sigma_{-}, \chi_{-}\right]\right\rangle$.







In the $q$ basis, we obtain
\begin{align}
\mathcal{L}_{D,D5}^q &= \bar{q} \lambda_D \overleftrightarrow{\partial}_\mu q + \bar{q} \gamma^5 \lambda_{D5} \overleftrightarrow{\partial}_\mu q\;,
\end{align}
where both $\lambda_D$ and $\lambda_{D5}$ are Hermitian. 

We can rewrite the above expression as follows
\begin{align}
\bar{q} \lambda_D \overleftrightarrow{\partial}_\mu q &= \bar{q}_L \lambda_D \overleftrightarrow{\partial}_\mu q_R + \bar{q}_R \lambda_D^\dagger \overleftrightarrow{\partial}_\mu q_L\;, \\
\bar{q} \gamma^5 \lambda_{D5} \overleftrightarrow{\partial}_\mu q &= \bar{q}_L \lambda_{D5} \overleftrightarrow{\partial}_\mu q_R - \bar{q}_R \lambda_{D5}^\dagger \overleftrightarrow{\partial}_\mu q_L\;,
\end{align}
which are formally invariant under chiral symmetry given the transformation of the 
spurions $\lambda_{D,D5} \to L \lambda_{D,D5} R^\dagger$ and  $\lambda_{D,D5}^\dagger \to R \lambda_{D,D5}^\dagger L^\dagger$.

The matched chiral operators become
\begin{align}
\bar{q} \lambda_D \overleftrightarrow{\partial}_\mu q &\to \Tr \left[ \left( u\lambda_D u + u^\dagger \lambda_D^\dagger u^\dagger \right) \left[ \nabla_\mu \hat{u}_\nu, \hat{u}^\nu \right] \right], \nn \\
\bar{q} \gamma^5 \lambda_{D5} \overleftrightarrow{\partial}_\mu q &\to \Tr \left[ \left( u\lambda_{D5} u - u^\dagger \lambda_{D5}^\dagger u^\dagger \right) \left[ \nabla_\mu \hat{u}_\nu, \hat{u}^\nu \right] \right].
\end{align}
We identify
\begin{align}
    \lambda_{D} = \lambda_D^\dagger &= i(\lambda^\dagger + \lambda)/2\;,\nn\\
    \lambda_{D5} = \lambda_{D5}^\dagger &= i(\lambda^\dagger - \lambda)/2\;,
\end{align}
and obtain that the matched chiral operators agree with Eq.~\eqref{eq:derivative}. 





