\section{Methods}
\subsection{Variance of back relaxation}
\label{Methods:Var-MBR}
For purely Gaussian random variables, MBR only depends on the conditioning time $\tau$ and $t$, and is length parameter independent. The length parameter dependence enters when we consider VBR. First, we need to define the fluctuating back relaxation 
\begin{align}
    \mbr = -\frac{x(t) - x(0)}{x(0) - x(-\tau)} \vartheta_l(x(0) - x(-\tau)) = -\frac{b}{d}\vartheta_l(d)
\end{align}
with $\MBR(\tau,t,l) = \mean{\mbr}$. We assume that the joint process of $b$ and $d$ is also given by a Gaussian process. 
In this case the conditioned distribution is given by \cite{bishop_pattern_2006}
\begin{align}
    p(b\vert d) = \frac{1}{\sqrt{2 \pi \sigma^2}} e^{ - \frac{1}{2} \frac{\left( b + d\mean{\mbr} \right)^2}{\sigma^2}}
    \label{eq:condition}
\end{align}
with $\sigma^2 = \Delta x^2(t) - \Delta x^2(\tau) \frac{1}{4} \left(1 - \frac{\Delta x^2(t+\tau) - \Delta x^2(t)}{\Delta x^2(\tau)}\right) =  \Delta x^2(t) - \Delta x^2(\tau) \MBR^2(\tau,t)$, with the mean squared displacement (MSD) $\Delta x^2(t) = \mean{(x(t) - x(0))^2}$. Because the variance $\sigma^2$ needs to be positive, $\alpha = \frac{1}{\MBR^2(\tau,t)}\frac{\Delta x^2(t)}{\Delta x^2(\tau)} > 1$ . Note that in the Gaussian case MBR is independent of $l$. From here we proceed to calculate the distribution of the back relaxation 
\begin{align}
    p(\mbr) &= \int \dif d \dif b~ \delta \left( \mbr + \frac{b}{d} \vartheta_(d) \right) p(b\vert d) p(d)\\
    &= \int \dif d ~  p \left( \left. \frac{\mbr d}{\vartheta_l(d)}  \right\vert d \right) p(d) \frac{d}{\vartheta_l(d)}
\end{align}
Using Eq.~\eqref{eq:condition} and the Gaussian probability distribution 
\begin{align}
    p(d) = \frac{1}{\sqrt{2\pi \Delta x^2(\tau)}} e^{-\frac{1}{2} \frac{d^2}{\Delta x^2(\tau)}}
\end{align}
for the general displacements we can calculate VBR
\begin{widetext}
\begin{align}
    \VBR(\tau,t,l) &= \mean{\mbr^2} - \mean{\mbr}^2 \\
    &= \int \dif d \frac{\sigma^2 \vartheta_l^2(d)}{d^2} p(d) + \frac{\MBR^2(\tau,t)}{\text{erfc}\left(\frac{l}{\sqrt{2 \Delta x^2(\tau)}}\right)} - \MBR^2(\tau,t)\\
     &= \frac{\sigma^2}{\mean{\theta(\vert d \vert - l)}^2} \int \dif d \frac{\theta(\vert d \vert -l)}{d^2} \frac{1}{\sqrt{2 \pi \Delta x^2_\tau}} e^{ -\frac{d^2}{2 \Delta x^2_\tau}} + \MBR^2(\tau,t) \left( \frac{1}{\text{erfc}\left(\frac{l}{\sqrt{2 \Delta x^2(\tau)}}\right)} - 1\right)
\end{align}
\end{widetext}
where we inserted $\vartheta_l(d) = \frac{\theta(\vert d \vert  - l)}{\mean{\theta(\vert d \vert  - l)}}$. The remaining terms can be solved using the Gaussian error functions to get 
\begin{widetext}
\begin{align}
    \VBR(\tau,t,l) &=  \frac{\sigma^2}{\text{erfc} \left( \frac{l}{\sqrt{2 \Delta x^2(\tau)}} \right)^2} \left( \sqrt{\frac{2}{\pi}} \frac{e^{-\frac{l^2}{2\Delta x^2(\tau)}}}{\sqrt{\Delta x^2(\tau)}l} -\frac{1}{\Delta x^2(\tau)} \text{erfc} \left( \frac{l}{\sqrt{2 \Delta x^2(\tau)}} \right)\right)\\
    &+ \MBR^2(\tau,t) \left( \frac{1}{\text{erfc}\left(\frac{l}{\sqrt{2 \Delta x^2(\tau)}}\right)} - 1\right)\\
    &= \frac{\sigma^2}{\Delta x^2(\tau)} \frac{1}{ \text{erfc}(\eta)^2} \left( \frac{1}{\sqrt{\pi}} \frac{e^{-\eta^2}}{\eta} - \text{erfc}(\eta) \right) + \MBR^2(\tau,t) \left( \frac{1}{\text{erfc}(\eta)} - 1 \right)\\
    &= \left( \frac{\Delta x^2(t)}{\Delta x^2(\tau)} - \MBR^2(\tau,t) \right) \frac{1}{ \text{erfc}(\eta)^2} \left( \frac{1}{\sqrt{\pi}} \frac{e^{-\eta^2}}{\eta} - \text{erfc}(\eta) \right) +\MBR^2(\tau,t) \left(\frac{1}{\text{erfc}(\eta)} -1 \right)\\
    &= \MBR^2(\tau,t) \left[ \left( \alpha - 1\right) g(\eta) + h(\eta)\right]
\end{align}
\end{widetext}
with a dimensionless $\eta = \frac{l}{\sqrt{2 \Delta x^2(\tau)}}, \alpha = \frac{1}{\MBR^2(\tau,t)} \frac{\Delta x^2(t)}{\Delta x^2(\tau)}$ and the $\eta$ dependent functions $g(\eta)=\frac{1}{\text{erfc}(\eta)^2} \left( \frac{1}{\sqrt{\pi}} \frac{e^{-\eta^2}}{\eta} - \text{erfc}(\eta) \right)$ and $h(\eta) =  \frac{1}{\text{erfc}(\eta)} - 1$. Again note that $\MBR(\tau,t,l) = \mean{\mbr}$. The expression $g(\eta)$ can be minimized numerically with $\eta^{(g)}_\text{min} \approx 0.654334$. To get an approximation for the minimum of VBR up to first order in $y = \frac{1}{\alpha - 1}$ we exprress the derivative of VBR
\begin{align}
    \frac{\dif \VBR}{\dif \eta} &= \MBR^2 \left( \frac{1}{y} g^\prime(\eta_\text{min}) + h^\prime(\eta_\text{min}) \right) \overset{!}{=} 0\\
    \Rightarrow 0 &= g^\prime(\eta_\text{min}(y)) + y h^\prime(\eta_\text{min}(y))
\end{align}
Expand the last expression around $y=0$ to linear order and use $\eta(y) - \eta(0) = y\eta^\prime(0) + \mathcal{O}(y^2)$
\begin{align}
\begin{split}
0 =& g^\prime(\eta_\text{min}(0)) + g^{\prime\prime}(\eta_\text{min}(0)) (\eta_\text{min}(y) - \eta_\text{min}(0))\\
    &+ h^\prime(\eta_\text{min}(0)) y +\mathcal{O}(y^2).
    \end{split}
\end{align}
At last $\eta_\text{min}(0) = \eta_\text{min}^{(g)}$ and therefore $g^\prime(\eta_\text{min}(0)) = 0$
\begin{align}
    \eta_\text{min}(y) &= \eta_\text{min}^{(g)} - \frac{h^\prime \left(\eta_\text{min}^{(g)} \right)}{g^{\prime  \prime} \left(\eta_\text{min}^{(g)} \right)}y  + \mathcal{O}(y^2)\\
    &= \eta_\text{min}^{(g)} - \frac{h^\prime \left(\eta_\text{min}^{(g)} \right)}{g^{\prime  \prime} \left(\eta_\text{min}^{(g)} \right)} \frac{1}{\alpha - 1} + \mathcal{O} \left( \left( \alpha - 1 \right)^{-2} \right)
\end{align}

The expansion coefficients can be determined as $h^\prime(\hat{\eta}_\text{min}) = 5.84259$ and $g^{\prime \prime}(\hat{\eta}_\text{min}) = 6.71207$.

\subsection{Random Horse and Cart model}
\label{subsec:Methods:HCM}

\subsubsection{Mean back relaxation}~\\
\label{subsec:HCM-MBR}
The mean back relaxation (MBR) is related to the mean squared displacement $\Delta x^2(t) = \mean{(x(t) - x(0))^2}$ because the statistics of the overall system is Gaussian

 \begin{align}
     \MBR(\tau,t,l) = \frac{1}{2} \left(1 - \frac{\Delta x^2(t+\tau) - \Delta x^2(t)}{\Delta x^2(\tau)} \right)
 \end{align}
 which is independent of the length parameter $l$. We, therefore, drop this index for brevity.
 To get the mean squared displacement we rewrite the equations into relative coordinates $r_1 = x_1 - x_2$ and $r_2 = x_1 - q$
 \begin{subequations}
 \begin{align}
     \dot r_1 &= - k_1 \left( \frac{1}{\gamma_1} + \frac{1}{\gamma_2} \right) r_1 - \frac{k_2}{\gamma_1} r_2 + \xi_{r_1}(t)\\
     \dot r_2 &= - \frac{k_1}{\gamma_1} r_1 - \frac{k_2}{\gamma_1} r_2 + \xi_{r_2}(t)\\
     \dot q &= \xi_q(t)
 \end{align}
  \end{subequations}
  with $\xi_{r_1} = \xi_1(t) - \xi_2(t)$ and $\xi{r_2}(t) = \xi_1(t) - \xi_q(t)$
  The relative coordinates can be solved using the matrix equation 
  \begin{align}
      \mathbf{r}(t) = \int_{-\infty}^t e^{\mathbf{M} (t-s)} \mathbf{\xi_r}(s) \dif s
  \end{align}
  with 
  \begin{align}
      \mathbf{M} = \left( \begin{array}{cc}
           -k_1 \left( \frac{1}{\gamma_1} + \frac{1}{\gamma_2} \right)& - \frac{k_2}{\gamma_1}  \\
           -\frac{k_1}{\gamma_1}& -\frac{k_2}{\gamma_1} 
      \end{array}\right).
  \end{align}
  After diagonalizing $\mathbf{M}$ and computing the correlation functions, the mean squared displacement of the particle $x_1$ is found by $\Delta x_1^2(t) = \mean{(r_2(t) + q(t) - r_2(0) - q(0))^2}$
 \begin{widetext}
 \begin{align}
    \beta k_2 \Delta x_1^2(t) = 2 \frac{D_q}{D_1} \frac{k_2}{\gamma_1} t + \left(f(\lambda_1,\lambda_2) + g(\lambda_1,\lambda_2) \frac{D_q}{D_1} \right) \left(1 - e^{-\lambda_1 t} \right) + \left(f(\lambda_2,\lambda_1) + g(\lambda_2,\lambda_1) \frac{D_q}{D_1} \right) \left(1 - e^{-\lambda_2 t} \right)
    \label{eq:HCM-MSD_2}
\end{align}
 \end{widetext}
with time scales 
\begin{align}
\begin{split}
    \lambda_{1,2} = \frac{k_2}{\gamma_1} \frac{1}{2} &\left[ 1 + \frac{k_1}{k_2}+ \frac{\gamma_1}{\gamma_2} \frac{k_1}{k_2} \right.\\
    &\left. \pm \sqrt{ \left(1 + \frac{k_1}{k_2} + \frac{\gamma_1}{\gamma_2} \frac{k_1}{k_2} \right)^2 - 4 \frac{\gamma_1}{\gamma_2} \frac{k_1}{k_2} } \right]
    \end{split}
\end{align}
and constants
\begin{align}
    f(\lambda_1,\lambda_2) &= 2 \frac{\frac{k_2}{\gamma_1} - \lambda_2}{\lambda_1 - \lambda_2}\\
    g(\lambda_1,\lambda_2) &= 2 \frac{k_2}{\gamma_1} \frac{(\lambda_2 -\frac{k_2}{\gamma_1}) (\lambda_2 + \frac{k_2}{\gamma_1})}{(\lambda_1 + \lambda_2) (\lambda_1 - \lambda_2) \lambda_1}
\end{align}
By introducing the coefficients $\Psi(\lambda_1,\lambda_2) = f(\lambda_1,\lambda_2) + g(\lambda_1,\lambda_2) \frac{D_q}{D_1}$
\begin{widetext}
\begin{align}
    \MBR(\tau,t) = \frac{1}{2} \frac{\Psi(\lambda_1,\lambda_2) \left( 1 - e^{-\lambda_1 t} \right)\left( 1 - e^{-\lambda_1 \tau} \right) + \Psi(\lambda_2,\lambda_1) \left( 1 - e^{-\lambda_2 t} \right)\left( 1 - e^{-\lambda_2 \tau} \right)}{2 \frac{D_q}{D_1} \frac{k_2}{\gamma_1} \tau + \Psi(\lambda_1,\lambda_2) (1 - e^{-\lambda_1 \tau}) + \Psi(\lambda_2,\lambda_1) (1 - e^{-\lambda_2 \tau})}.
    \label{eq:MBR-HCM}
\end{align}
In the limit $\tau \to 0$ we obtain
\begin{align}
     \MBR(\tau \to 0,t) = \frac{1}{2} \frac{\lambda_1\Psi(\lambda_1,\lambda_2) \left(1 - e^{-\lambda_1 t} \right) + \lambda_2\Psi(\lambda_2,\lambda_1) \left(1 - e^{-\lambda_2 t} \right)}{2 \frac{D_q}{D_1} \frac{k_2}{\gamma_1}  +\lambda_1\Psi(\lambda_1,\lambda_2)  + \lambda_2\Psi(\lambda_2,\lambda_1) }
\end{align}
\end{widetext}
and in the long time limit $t \to \infty$ this expression simplifies to
\begin{align}
    \MBR(\tau \to 0,t \to \infty) = \frac{1}{2} \left( 1 - \frac{D_q}{D_1}\right)
\end{align}
\subsubsection{Maximum of MBR}~\\
The MBR has for certain parmeters $\frac{\gamma_1}{\gamma_2}, \frac{k_1}{k_2}$ a maximum in $t$ which one can obtain by setting the derivative of Eq.\eqref{eq:MBR-HCM} to zero. The result is given by
\begin{align}
    t_\text{max} = \frac{1}{\lambda_1 - \lambda_2} \log \left( - \frac{\lambda_1 \Psi(\lambda_1, \lambda_2) \left(1 - e^{-\lambda_1 \tau} \right)}{\lambda_2 \Psi(\lambda_2, \lambda_1) \left(1 - e^{-\lambda_2 \tau} \right)} \right).
\end{align}
However, not for every time scales $\lambda_1,\lambda_2$ there is a finite time solution as is illustrated in Fig.~\ref{fig:HCM-MBR-typical} because the expression in the log can be negative or smaller than 1. For activities smaller than 
\begin{align}
    \frac{D_q}{D_1} < \frac{(\lambda_1 + \lambda_2)\lambda_2}{\frac{k_2}{\gamma_1}+ \lambda_1}
\end{align}
there is no maximum, which is remarkably independent of $\tau$. Also for too high activities there is no maximum, which we find by setting $\displaystyle{\lim_{t \to 0}} \frac{\dif}{\dif t} \MBR(\tau,t) \overset{!}{=} 0$
\begin{align}
\begin{split}
    &\frac{D_q}{D_1}\\ &>- \frac{\lambda_1 f(\lambda_1,\lambda_2) \left(1 - e^{-\lambda_1 \tau} \right) + \lambda_2 f(\lambda_2,\lambda_1) \left(1 - e^{-\lambda_2 \tau} \right)}{\lambda_1 g(\lambda_1,\lambda_2) \left(1 - e^{-\lambda_1 \tau} \right) + \lambda_2 g(\lambda_2,\lambda_1) \left(1 - e^{-\lambda_2 \tau} \right)},
    \end{split}
\end{align}
however, this bound is $\tau$ dependent. In the limit $\tau \to 0$ we obtain Eq.~\eqref{eq:cond3}.
\subsubsection{Critical Activity}~\\
The critical activity is given by the ration of active to passive diffusion $\frac{D_q}{D}$, for which the long time MBR gets negative and has a local minimum. This property depends on the timescales of the system $\lambda_1$ and $\lambda_2$. The long time MBR for $\tau \gg \lambda_1,\lambda_2$ is given by
\begin{align}
    \MBR(\tau,t\to \infty) = \frac{1}{2} \frac{\Psi(\lambda_1,\lambda_2) + \Psi(\lambda_2,\lambda_1)}{2 \frac{D_q}{D_1} \tau + \Psi(\lambda_1,\lambda_2) + \Psi(\lambda_2,\lambda_1)}.
\end{align}
Because $\frac{D_q}{D_1} > 0$ the sign of the long time MBR is determined by the sign of $\Psi(\lambda_1,\lambda_2)+\Psi(\lambda_2,\lambda_1)$. Using $\Psi(\lambda_1,\lambda_2) = f(\lambda_1,\lambda_2) + \frac{D_q}{D_1} g(\lambda_1,\lambda_2)$ we find for the critical activity  $\Psi(\lambda_1,\lambda_2) + \Psi(\lambda_2,\lambda_1) = 0$
\begin{align}
    \frac{D_q}{D} = -\frac{f(\lambda_1,\lambda_2)  + f(\lambda_2,\lambda_1) }{g(\lambda_1,\lambda_2)  + g(\lambda_2,\lambda_1) }
    \label{eq:HCM-act-crit2}
    \end{align}
\subsubsection{Effective energy}~\\
The diffusing potential with memory can be described by the following Langevin equations

\begin{subequations}
\begin{align}
    \dot x_1 &= -\frac{k_1}{\gamma_1} (x_1 - x_2) - \frac{k_2}{\gamma_1} (x_1 - q) + \xi_1(t)\\
    \dot x_2 &= - \frac{k_1}{\gamma_2} (x_2 - x_1) + \xi_2(t)\\
    \dot q &= \xi_q
\end{align}
\end{subequations}

with $x_1$ the tracer particle, $x_2$ the bath particle that mimics the viscoelastic environment and $q$ the trap position. The system is projected onto $x_1$ coordinate and by integrating out the bath particle a generalized Langevin equation can be found by
\begin{align}
    -k_2x(t) + \int_{-\infty}^t \Gamma(t-s) \dot x(s) = k_2q(t) + f(t)
\end{align}
with a Gaussian random force $\mean{f(t) f(t^\prime)} = k_B T \Gamma (\vert t- t^\prime \vert)$. The correlation function in Fourier space is therefore given by
\begin{align}
    \mean{x(\omega) x(-\omega)} = \frac{k_2^2 \mean{q(\omega) q(-\omega) + \mean{f(\omega)f(-\omega)}}}{\omega^2 \Gamma(\omega) \Gamma(-\omega) + k_2^2 + ik_2\omega (\Gamma(\omega) - \Gamma(-\omega))} 
\end{align}
To get the effective energy we compare the correlation function with the active driving $q$ to the correlation function without the active driving and obtain
\begin{align}
    \frac{E_\text{eff}(\omega)}{k_B T} &= 1 + \frac{k_2^2 \mean{q(\omega)q(-\omega)}}{\mean{f(\omega) f(-\omega)}}\\
    &= 1 + \frac{k_2^2 \mean{q(\omega)q(-\omega)}}{k_B T \Tilde{\Gamma} (\omega)}\\
    &= 1 + \frac{D_q}{D} \frac{k_2^2}{\gamma_1} \frac{1}{\omega^2}\frac{1}{\Tilde{\Gamma} (\omega)}
\end{align}
with $\Tilde{\Gamma}(\omega)$ the Fourier transform of $\Gamma(\vert t\vert)$ and the Fourier transform of the free diffusion $\mean{q(\omega) q(-\omega)} = \frac{D_q}{\omega^2}$ with $D = \frac{k_B T}{\gamma_1}$. For the model system the memory kernel is given by
\begin{align}
    \Gamma(t) = \left[2 \gamma_1 \delta(t) + k_1 e^{-\frac{k_1}{\gamma_2} t} \right] \theta(t)
\end{align}
with the Fourier transform $\Tilde{\Gamma}(\omega) = \gamma_1 + \frac{k_1^2}{\gamma_2} \frac{1}{\frac{k_1^2}{\gamma_2^2} + \omega^2 }$ we get the final expression for the effective energy in the main text that scales with $\frac{D_q}{D}$.

\subsection{Active and passive microrheology}
\label{Methods: Active and passive microrheology}
The experiments conducted in order to determine the complex shear modulus and the effective energy of different cell types have been described in detail elsewhere \cite{muenker_accessing_2024}. Briefly, a home-build optical tweezers setup with a movable \SI{808}{\nano\meter} laser (LU0808M250, Lumics, \SI{75}{\milli\watt} at sample plane) and an \SI{976}{\nano\meter} laser (BL976-PAG500, Throlabs, \SI{0.3}{\milli\watt} at sample plane) were focused by a high NA objective (CFI Plan Apochromat VC 60XC WI NA 1.2, Nikon) onto the sample to exert well defined forces and detect particle motion.\\ \newline
For active microrheology, the \SI{808}{\nano\meter} trapping laser was used to apply oscillatory forces at different frequencies ($f_{\text{Drive}} \in \{1,2,4,8,16,32,64,128,256,512,1025\} \si{\hertz}$) onto phagocytosed probe particles in the cytoplasm of cells. The resulting forces $F_{f_{\text{Drive}}}(t)$ were directly obtained using back focal plane interferometry \cite{farre2010force}.
Simultaneously, the second \SI{976}{\nano\meter} laser (detection laser) was directed at the probe particle to monitor its displacement $x_{f_{\text{Drive}}}(t)$ in response to the applied force.\\
For each driving frequency, the response function $\chi({f_{\text{Drive}}})$ was calculated according to 
\begin{align}
    \chi({f_{\text{Drive}}})= \frac{\Tilde{x}_{f_{\text{Drive}}}(t)}{\Tilde{F}_{f_{\text{Drive}}}(t)},
\end{align}
where the tilde denotes the Fourier Transformation.\\
\newline
For passive microrheology, only the \SI{976}{\nano\meter} detection laser was used to monitor the free particle fluctuations $x(t)$ in the absence of any relevant trapping forces. These passive trajectories were later used to calculate MBR. Additionally, $x(t)$ was used to calculate the power spectral density $C(f)$:
\begin{align}
    C(f)=\mean{\Tilde{x}(f)\Tilde{x}(f)^*},
\end{align}
with $\Tilde{x}(f)^*$ denoting the complex conjugate of the Fourier Transformation of $x(f)$.\\
\newline
The effective energy $E_\text{Eff}(f)$ was determined by combining results from passive and active microrheology:
\begin{align}
    E_\text{Eff}(f) = \frac{C(f_{\text{Drive}})\pi f_{\text{Drive}}}{ \chi^{\prime\prime}({f_{\text{Drive}}})}.
\end{align}
Finally, effective energies were fit with 
\begin{align}
    E_{\text{Eff}}(f)=E_0 \left( \frac{f_0}{f} \right)^{\nu}+ k_B T ,
\end{align}
with $f_0 = \SI{1}{\hertz}$ in order to obtain the effective energy amplitude $E_0$. In this publication, the average $E_0$ values for each cell type and condition are displayed.
\subsection{Biological samples}
\label{Methods: Cells}
The exact procedure of cell preparation has been described elsewhere in detail \cite{muenker_accessing_2024}. Briefly, A549 (N=61), C2C12 (N=59), CT26 (N=60), HeLa (N=79), MCF7 (N=60), MDCK (N=62) and HoxB8 (N=60) cells were seeded onto a coverslip previously incubated with 1\% Fibronectin diluted in PBS. After the cells attached, the medium was replaced with fresh medium containing probe particles (Polybead® Microspheres $\SI{1}{\micro \metre}$) at 1:10,000 dilution. After approximately 17 hours of incubation, the samples were washed with PBS. During this time, a portion of probe particles got phagocytosed by the cells. Then a second cover slip was placed over the sample with a $\SI{400}{\micro\metre}$ thick, double-sided adhesive strip as a spacer. After this step, the active and passive microrheology experiments were conducted.\\


\subsection{MBR calculation}
\label{Methods: MBR calculation}
MBR was calculated for trajectories $x_i=x(t_i)$ with positions recorded at discrete time points $t_i$, with a sampling rate $srt$ and being $N$ samples long. We calculated MBR for different lagtimes $t$, length parameter values $l$ and conditioning times $\tau$: $\text{MBR}(t,l,\tau)$. We chose each time-point $t_i$ of the trajectory as a starting point for the calculation of the back relaxation and then took the average to calculate the mean back relaxation. The back relaxation for a position point at time $t_i$ is given as ,
\begin{align}
\begin{split}
    \mbr(t,\tau,l_i)_i&= -\frac{x(t_i+t)-x(t_i)}{x(t_i)-x(t_i-\tau)}\\
    &\text{ if } (l_i = x(t_i)-x(t_i-\tau) > l) 
    \end{split}
\end{align}
but we only consider starting times $t_i$ were $l_i$ is larger than the length parameter $l$.\\
Then we calculated MBR as the average overall $N$ back relaxations where $l_i >=l$:
\begin{align}
    \text{MBR}(t) = \frac{\sum_{i=1}^{N} \mbr(t, \tau, l_i) \text{ if } (l_i > l)}{\sum_{i=1}^{N} 1 \text{ if } (l_i > l)}
\end{align}


\subsection{Statistical tests}
\label{Methods: Statistical tests}
\subsubsection{Determination of $R^2$-values}
\label{Methods: R2 values calculation}
The coefficient of determination, $R^2$, was calculated to assess the goodness of fit for the regression models. First, the independent variable values $x$ and the dependent variable values $y$ were provided, along with the model function used for fitting the data. Optimal values for the parameters of the model function were obtained from curve fitting. For this, the \textit{scipy} function \textit{curve\_fit} was used \cite{2020SciPy-NMeth}. The model function was then evaluated at each value in $x$ using these optimal parameters to obtain the fitted values $ y_{fit}$.\\
The residual sum of squares $SS_{res}$ was computed as the sum of the squared differences between the observed values $y$ and the fitted values $y_{fit}$:
\begin{align}
    SS_{res} = \sum (y_{fit} - y)^2
\end{align}
Next, the total sum of squares $SS_{tot}$ was calculated as the sum of the squared differences between the observed values $y$ and their mean value $\bar{y}$:
\begin{align}
    SS_{tot} = \sum (y - \bar{y})^2
\end{align}
The $R^2$ value was then derived, indicating the proportion of the variance in the dependent variable that is predictable from the independent variables:
\begin{align}
    R^2 = 1 - \frac{SS_{res}}{SS_{tot}}
\end{align}

