\includegraphics[scale=0.8]{AttrRegions.pdf}
\caption{Graphs of regions $R_i$ for $i \in \brc{1,2,3,4,5}$ and $\D_2^{(0)}$.}
\label{fig:attrregions}
\end{figure}

It can be shown that whenever $\alpha > 1$ and $\beta - 1 \leq \alpha \leq \beta$, then we obtain exactly the same automata as Case 1 of Theorem \ref{thm:attractor}. We now assume that $0 < \alpha \leq 1$ and $0 < \beta - 1 < \alpha < \beta$. Then under these assumptions, $1 < \beta \leq 2$. We will also impose that $\alpha + \beta > 2$ (which implies that $\alpha>1/2$) and $\beta > 2\alpha$. Apart from the states $\pm P,\dots,\pm T$ introduced in Section~\ref{SMR}, we now introduce new states $\pm E, \dots, \pm H$ defined as follows:
\begin{align*}
    (\sigma^{\pm E})_A &= (\sigma)_A \mp A(2c,0)^\top \mp (2a-c,0)^\top \\
    (\sigma^{\pm F})_A &= (\sigma)_A \pm (2c,0)^\top \\
    (\sigma^{\pm G})_A &= (\sigma)_A \pm A(c,0)^\top \pm (a-2c,0)^\top \\
    (\sigma^{\pm H})_A &= (\sigma)_A \mp A(2c,0)^\top \mp (2a,0)^\top.
\end{align*}
For this case, the relations involving $\sigma^{\pm P}, \sigma^{\pm Q}, \sigma^{\pm R}, \sigma^{\pm S}$ is the same as in Section~\ref{Case1}. The remaining states satisfy the following relations.
\begin{align*}
    (\sigma\nu)^{\pm T} &=
    \begin{cases}
        \sigma^{\mp Q} \, \ol{\nu \pm a \pm c \mp b}, & 0 \leq \nu \pm a \pm c \mp b < b \\
        \sigma^{\pm E} \, \ol{\nu \pm a \pm c \mp 2b}, & 0 \leq \nu \pm a \pm c \mp 2b < b
    \end{cases} \\
    (\sigma\nu)^{\pm E} &=
    \begin{cases}
        \sigma^{\pm G} \, \ol{\nu \mp 2a \pm c \pm b}, & 0 \leq \nu \mp 2a \pm c \pm b < b \\
        \sigma^{\mp F} \, \ol{\nu \mp 2a \pm c}, & 0 \leq \nu \mp 2a \pm c < b
    \end{cases} \\
    (\sigma\nu)^{\pm F} &=
    \begin{cases}
        \sigma^{\pm R} \, \ol{\nu \pm 2c \mp b}, & 0 \leq \nu \pm 2c \mp b < b \\
        \sigma^{\pm H} \, \ol{\nu \pm 2c \mp 2b}, & 0 \leq \nu \pm 2c \mp 2b < b
    \end{cases} \\
    (\sigma\nu)^{\pm G} &=
    \begin{cases}
        \sigma^{\pm T} \, \ol{\nu \pm a \mp 2c \pm b}, & 0 \leq \nu \pm a \mp 2c \pm b < b \\
        \sigma^{\pm S} \, \ol{\nu \pm a \mp 2c}, & 0 \leq \nu \pm a \mp 2c < b 
    \end{cases} \\
    (\sigma\nu)^{\pm H} &=
    \begin{cases}
        \sigma^{\pm G} \, \ol{\nu \mp 2a \pm b}, & 0 \leq \nu \mp 2a \pm b < b \\
        \sigma^{\mp F} \, \ol{\nu \mp 2a}, & 0 \leq \nu \mp 2a < b 
    \end{cases}
\end{align*}

