\includegraphics[scale=0.9]{Fig8L.pdf}
\caption{Transducer that realizes the addition by $(1,0)^\top$ whenever $0 < \alpha \leq 1$, $0 < \beta - 1 < \alpha < \beta$, $\alpha + \beta > 2$, and $\beta > 2\alpha$.}
\label{fig:automaton51}
\end{figure}

Observe that the condition $\beta > 2\alpha$ is needed for the relations of states $\pm H$ to hold, and $\alpha + \beta > 2$ is required to satisfy those of states $\pm E$ and $\pm G$. The transducer which captures this case is given in Figure~\ref{fig:automaton51}. Here, only edge labels of the form $0 \mid k$ are shown and edges containing a label of this form are displayed as double lines. Observe that any input string of the form $\sigma = 0^\infty w$ with $w$ a finite word over $\D$ will lead to a terminal state once fed to the transducer. Hence, the corresponding output string has the same form as $\sigma$. By the arguments of Cases 1 and 3 of Theorem \ref{thm:attractor}, the dynamical system $\Phi$ has zero attractor. This leads to the following result.

\begin{theorem} \label{thm:automaton51}
Consider the digit system $(A,\D)$ where $A$ is the companion matrix of the irreducible polynomial $p(x) = x^2 + \alpha x + \beta
\in \Q[x]$ and $\D = \brc{(0,0)^\top,(1,0)^\top,\dots,(\abs{b}-1,0)^\top}$. Let $\A_\Phi$ be the attractor of the dynamical system $\Phi$ induced by $(A,\D)$, $c$ be the unique positive integer for which the polynomial $q(x):=cp(x)$ is a polynomial with coprime integer coefficients, and $a = c\alpha, b = c\beta$. Then the following hold:
\begin{enumerate}
    \item If $\alpha > 1$ and $\beta - 1 \leq \alpha \leq \beta$, then $\A_\Phi = \brc{0}$.
    \item If $0 < \alpha \leq 1$ and $0<\beta - 1 < \alpha < \beta$, then $\A_\Phi = \brc{0}$ provided that one of the following conditions hold.
    \begin{enumerate}
        \item $\alpha + \beta > 2$ and $\beta > 2\alpha$
        \item $\alpha + 2 < 2\beta$ and $\beta \leq 2\alpha$
    \end{enumerate}
\end{enumerate}
\end{theorem}

As in the preceding discussion, let $x = 1/\beta$ and $y = \alpha/\beta$ and consider the following regions in $\R^2$:
\begin{align*}
    S_1 &= \brc{(x,y) \in \R^2 \mid y > x \text{ and } 1-x \leq y \leq 1} \\
    S_2 &= \brc{(x,y) \in \R^2 \mid 0 < y \leq x, 0<1-x < y < 1, y+1 > 2x, \text{ and } 2y < 1} \\
    S_3 &= \brc{(x,y) \in \R^2 \mid 0 < y \leq x, 0<1-x < y < 1, y+2x < 2, \text{ and } 2y \geq 1}.
\end{align*}
Then $(x,y) \in S_1$ (respectively $S_2$, $S_3$) precisely when $\alpha$ and $\beta$ satisfy the conditions of Case 1 (respectively Case 2(a), Case 2(b)) in Theorem~\ref{thm:automaton51}. The graphs of regions $R_1$, $R_3$, $S_1$, $S_2$, and $S_3$ are shown in Figure~\ref{fig:regions}. Notice that all their interiors are contained in $\D_2^{(0)}$.

