\section{Quantile-Quantile (Q-Q) plot Analysis}
 The GTS distribution lacks a closed-form probability density function (\ref{eq:l821}), making direct sampling challenging. However, we know the closed form of the Fourier of the density function, $\scrF[f]$ (\ref{eq:l6}), and the relationship in (\ref{eq:l822}) provides the Fourier of the cumulative distribution function, $\scrF[F]$. And the GTS distribution function, $F(x)$, was computed from the inverse of the Fourier of the cumulative distribution, $\scrF[F]$, in (\ref{eq:l823}):
  \begin{align}
 Y &\sim GTS(\textbf{$\mu$}, \textbf{$\beta_{+}$}, \textbf{$\beta_{-}$}, \textbf{$\alpha_{+}$},\textbf{$\alpha_{-}$}, \textbf{$\lambda_{+}$}, f\textbf{$\lambda_{-}$}) \label{eq:l820}\\
   F(x)&= \int_{-\infty}^{x} f(t) \mathrm{d}t \hspace{5mm}  \hbox{$f$ is the density function of $Y$} \label{eq:l821}\\
 \scrF[F](x)&=\frac{\scrF[f](x)}{ix} + \pi\scrF[f](0)\delta (x) \label{eq:l822}\\
F(x) &= \frac{1} {2\pi}\int_{-\infty}^{+\infty}\! \frac{\scrF[f](y)}{iy}e^{ixy}\, \mathrm{d}y + \frac{1}{2}\label{eq:l823}
 \end{align}
% \noindent
See Appendix A in \cite{nzokem2021fitting} for (\ref{eq:l823}) proof.\\

  \begin{theorem} \label{lem08} \ \\
{Let} 
 a probability cumulative function $F(x)$ be at least four times continuously differentiable and let $\left(F_{j}\right)_{1 \leq j \leq m}$ be a sample of $F(x)$  on a sequence of evenly spaced input values $\left(x_{j}\right)_{1 \leq j \leq m}$, with  $F(x_{j})=F_{j}$.  We also consider $x_{\alpha}$, a $\alpha^{th}$ quantile defined by $F(x_{\alpha})=\alpha$, with $x_{i}<x_{\alpha}<x_{i+1}$ and $F_{i}<F(x_{\alpha})<F_{i+1}$. {There } exists a unique value, $y \in (0,1)$, and $b_{0}$, $b_{1}$, $b_{2}$, $b_{3}$, $b_{4}$ coefficients such that $y$ is a solution of the polynomial equation of degree 4 (\ref{eq:l85}).
  \begin{equation}
b_{0} + b_{1} y  + b_{2} y^{2} + b_{3} y^{3} + b_{4} y^{4} = 0
\label{eq:l85}
\end{equation}

The $\alpha^{th}$ quantile ($x_{\alpha}$) can be written as follows:
\begin{equation}
 x_{\alpha}=x_{i} + y(x_{i+1} - x_{i}).
\label{eq:l86}
\end{equation}
\end{theorem}
Refer to \cite{mca29030044} for the proof of Theorem \ref{lem08} 

