\section{Appendix: Proofs for lemmas and propositions}
\subsection{Proof of Lemma~\ref{lm:loss-L2}}\label{sec:proof1} 
\begin{proof}  
Let $M = \mathrm{ess\,sup}_x \, w(x)$. For any $f$ with   $\Pi(f) = 0$, we have 
$$\sigma^2(Q, f) = \Pi(f^2 w) \leq M \, \Pi(f^2) = M \sigma^2(\Pi, f).$$ This proves that we always have $R(Q,  \cL^2(\Pi)) \leq  M $. 

It remains to show that $R(Q,  \cL^2(\Pi)) \geq  M $. 
Assume  $M < \infty$ first.  
Fix some $\epsilon \in (0, M]$ and define $B = \{ x  \in \cX \colon w(x) \geq M - \epsilon  \}.$  We have $\Pi(B) > 0$ since $M$ is the essential supremum of $w$. 
By a classical result for atomless probability measures from~\cite{sierpinski1922fonctions},  there exists a measurable set $B_0 \subset B$ such that $\Pi(B_0) = \Pi(B) / 2$. 
Let $B_1 = B \setminus B_0$ and define a test function $f$ by 
$$f(x) = \ind_{B_0} (x) - \ind_{B_1}(x).$$   
Clearly, $f \in \cL^2(\Pi)$ and $\Pi(f) = 0$. Hence, 
\begin{align*}
    R(Q,  \cL^2(\Pi)) \geq  \frac{\sigma^2(Q, f)}{\sigma^2(\Pi, f)} = \frac{  \Pi(f^2 w) }{  \Pi(f^2) }  = \frac{ \int_B   w \, \dd \Pi }{ \Pi(B)}
    \geq M - \epsilon.
\end{align*}
Taking supremum on both sides over all $\epsilon > 0$,  we get $ R(Q,  \cL^2(\Pi)) \geq M$. 
When $M = \infty$, by an analogous argument, we have $ R(Q,  \cL^2(\Pi)) \geq C$ for any $C < \infty$, which implies that  $ R(Q,  \cL^2(\Pi)) = \infty$. 
\end{proof}



\subsection{Proof of Lemma~\ref{lm:worst-case} } \label{sec:proof2}

\begin{proof} 
For notational simplicity,  we write $\pi_i = \pi(x_i)$, $q_i = q(x_i)$ and $f_i = f(x_i)$. 
By equation~\eqref{eq:default-loss}, we only need to find the function $f$ that maximizes $\Pi(f^2 w)$ under the constraint $\Pi(f) = 0$ and $\Pi(f^2) = 1$. 
If $w_i = \infty$ for some $i$, we have $\pi_i > q_i = 0$ (recall that we assume $\pi > 0$ everywhere), and thus $\Pi(f^2 w ) = \infty$ whenever $f_i \neq 0$.   So henceforth we assume $q_i > 0$ for every $i$. 
Using Lagrange multipliers, we introduce the loss function 
\begin{equation}\label{eq:lagrange}
   J(Q,  \lambda, \eta) = \Pi\left(f^2  w \right)  - \lambda \left(\Pi(f^2) - 1 \right) - \eta \Pi(f). 
\end{equation}
Writing $f_i = f(x_i)$, we get $\dd J / \dd f_i =  2 f_i \pi_i w_i  - 2 \lambda f_i \pi_i  - \eta \pi_i.$ 
Setting all derivatives of $J$ to zero, we find that the optimal $(f, \lambda, \eta)$ should satisfy   
\begin{align}
 ( w_i - \lambda) f_i   &=   \frac{\eta}{2}, \quad \forall \, 1 \leq i \leq N,  \label{eq:lambda1}  \\
 \Pi(f) & = 0,  \label{eq:f1} \\
 \Pi(f^2) & = 1. \label{eq:f2}
\end{align}
We now split the proof into two cases: (1) $\lambda = w_i$ for some $i$, and (2) $\lambda \neq w_i$ for any $i$. 

\medskip 

\noindent\textit{Case 1: $\lambda = w_i$ for some $i$.}
To satisfy~\eqref{eq:lambda1}, we need $\eta = 0$  and $f_j = 0$ whenever $w_j \neq w_i$. Since we do not allow $f$ to be the zero function and $f$ should satisfy $\Pi(f) = 0$, there must exist some $j \neq i$ such that $w_i = w_j$. 
Now choose $f_i, f_j$ (assuming all other coordinates of $f$ are zero) such that~\eqref{eq:f1} and~\eqref{eq:f2} are satisfied. Then $f$ must satisfy 
\begin{equation}\label{eq:case1}
    \Pi(f^2 w) = \sum\nolimits_{j=1}^N f_j^2 w_j = w_i (f_i^2 + f_j^2)  = w_i. 
\end{equation} 
In particular, when $w_{(1)} = w_{(2)}$, there exists a solution $(f, \lambda, \eta)$ to~\eqref{eq:lambda1}, ~\eqref{eq:f1} and~\eqref{eq:f2} with $\lambda = w_{(1)}$. 
The function $f$ also satisfies $\Pi(f^2 w) = w_{(1)}$, which implies that  $R(Q,  \cL^2(\Pi)) \geq w_{(1)}$. 
Since we always have $ R(Q,  \cL^2(\Pi)) \leq w_{(1)}$, we conclude that $R(Q,  \cL^2(\Pi)) = w_{(1)}$. 


\medskip 
\noindent\textit{Case 2: $\lambda \neq w_i$ for any $i$.} 
By~\eqref{eq:lambda1}, the optimal $f$ takes the form 
\begin{equation}\label{eq:opt-f}
    f_i = \frac{ \eta / 2}{ w_i - \lambda}, \quad \forall \, 1 \leq i \leq n. 
\end{equation}
We find using the constraint~\eqref{eq:f1} that $\lambda$ must solve equation~\eqref{eq:lambda}, and given $\lambda$, $\eta$ can be determined by the constraint~\eqref{eq:f2}.      
Assuming $w_{(1)} > w_{(2)}$, on the open interval $(w_{(2)}, w_{(1)})$, the left-hand side of~\eqref{eq:lambda} is strictly monotone increasing in $\lambda$ with limits
\begin{equation}
  \lim_{\lambda \downarrow w_{(2)}}   \sum_{i=1}^N \frac{\pi_i }{w_i - \lambda} = -\infty, \quad   \lim_{\lambda \uparrow w_{(1)}}   \sum_{i=1}^N \frac{\pi_i }{w_i - \lambda} = \infty. 
\end{equation} 
Hence, on $(w_{(2)}, w_{(1)})$, there is a unique solution to equation~\eqref{eq:lambda}. 
The same argument shows that there is one solution to~\eqref{eq:lambda} on each interval $(w_{(k-1)}, w_{(k)})$ with $w_{(k)} > w_{(k-1)}$. 
To figure out which solution is the optimizer,  we multiply both sides of~\eqref{eq:lambda1} by $\pi_i f_i$, sum over $i$, and use~\eqref{eq:f1} and~\eqref{eq:f2}  
to get $\lambda = \Pi(f^2 w)$.  
Therefore, to maximize $\Pi (f^2 w)$, we should pick the largest solution to~\eqref{eq:lambda}, which is the one on $(w_{(2)}, w_{(1)})$. 


\medskip 
To conclude, if $w_{(1)} = w_{(2)}$, we have already proved in Case 1  that $R(Q,  \cL^2(\Pi))  = w_{(1)}$. 
If $w_{(1)} > w_{(2)}$ and we set $\lambda = w_i$ for some $i$, by~\eqref{eq:case1}, any function $f$ solving~\eqref{eq:lambda1},~\eqref{eq:f1} and~\eqref{eq:f2} satisfies $\Pi(f^2 w) = w_i \leq w_{(2)}$. Hence, when $w_{(1)} > w_{(2)}$,  the function $f$ that  maximizes $\Pi(f^2 w)$ under the constraints~\eqref{eq:f1} and~\eqref{eq:f2}  is the one given by~\eqref{eq:opt-f}, which satisfies $\Pi(f^2 w)  = \lambda$ with $\lambda \in (w_{(2)}, w_{(1)}) $ solving~\eqref{eq:lambda}.  
\end{proof}

\subsection{Proof of Lemma~\ref{lm:two}}\label{sec:proof3}
\begin{proof}
It is easy to verify that $\Pi(f) = 0$ and $\Pi(f^2) = 1$. Hence, $\sigma^2 (Q, f) = \Pi(f^2 w)$.  
By the Cauchy--Schwarz inequality,
\begin{align*} 
\Pi(w \ind_E) Q(E) =  \left(  \int_{E}  \frac{\pi(x)^2 }{q(x)}  \mu(\dd x)  \right)
  \left( \int_{E}  q(x) \mu (\dd x) \right) \geq  \left( \int_{E}  \pi(x)  \mu(\dd x)  \right)^2 = p^2. 
\end{align*}
It follows that $\Pi(w \ind_E) \geq p^2 / Q(E)$, and similarly, 
$\Pi(w \ind_{E^c}) \geq (1 - p)^2 / Q(E^c)$. Hence, 
\begin{equation}
   \frac{ 1 - p}{ p } \,  \Pi(w \ind_E) +  \frac{ p }{ 1 - p} \,  \Pi(w \ind_{E^c})
    \geq \frac{  p ( 1 - p ) }{Q(E) ( 1 - Q(E) )} \geq 4 p ( 1 - p ), 
\end{equation}
since $u(1 - u) \leq 1/4$ for any $u \in [0, 1]$.
\end{proof}


\subsection{Proof of Proposition~\ref{th:multi}}\label{sec:proof-multi}
\begin{proof} 
Let $a_X =  t^2 / \delta, a_Y = (1-t)^2 / (1 - \delta)$.  
The large atom case is easy. We  apply Lemma~\ref{lm:two} with $E = \{x^*\}$ to obtain that  $\sigma^2(Q_X, f) \geq 4 p(1 - p)$ and  $\sigma^2(Q_Y, f) \geq 4 p(1 - p)$ for the test function $f$ given in Lemma~\ref{lm:two} (which does not depend on the trial distribution). 
Hence, $V(f) \geq a_X + a_Y$, and by a routine application of the Cauchy--Schwarz inequality, we have $a_X + a_Y \geq 1$ with equality attained by $\delta = t$. 

For the case where no large atom exists, we need to find a measurable function $f$ such that $V(f) \geq 1$. 
To this end, define the ``average'' importance weight by 
    \begin{equation}
        \bar{w}(x) = a_X w_X(x) + a_Y w_Y(x), 
    \end{equation} 
    which yields 
    \begin{equation}\label{eq:V2}
        V(f) = a_X \Pi (f^2 w_X) + a_Y \Pi(f^2 w_Y) = \Pi( f^2 \bar{w} ).   
    \end{equation}
    Define the ``average'' trial density by 
    \begin{equation}
        \bar{q}(x) = \frac{ a_X q_X(x) + a_Y q_Y(x) }{ a_X + a_Y }.  
    \end{equation}
    It is easy to check that $\int \bar{q} \dd \mu = 1$, which verifies that  $\bar{q}$ is indeed a probability density function with respect to $\mu$. Observe that 
    \begin{align*}
        \int_{\cX} \bar{q}(x) \bar{w}(x) \mu (\dd x) 
        &=  \frac{1}{a_X + a_Y}  \int_{\cX} \pi(x) \left\{ a_X^2 + a_Y^2 + a_X a_Y \frac{q_Y(x)}{q_X(x)} + a_X a_Y \frac{q_X(x)}{q_Y(x)}   \right\} \mu (\dd x)   \\
        & \overset{(i)}{\geq} a_X + a_Y \geq 1,
    \end{align*}
    where in step (i) we use  $u + u^{-1} \geq 2$ for any $u > 0$ and $\int \pi \dd \mu = 1$.  Note that (i) becomes an equality when $q_X = q_Y$. Since $\bar{q}$ is a probability density function, we have $ \mathrm{ess\,sup}_x \, \bar{w}(x) \geq 1$. 

    The remainder of the argument is similar to the proof of Theorem~\ref{th:opt-Q-no-atom}. First, let  $\cX_0$ denote the non-atomic part of $\cX$ (assuming that it is not empty).   
    We can construct a sequence of functions $f_k$ such that $\Pi(f_k)=0, \Pi(f_k^2) = 1$, and the infimum of $\bar{w}$ on the support of $f_k$ increases to $\mathrm{ess\,sup}_{x \in \cX_0} \bar{w}(x)$ (see the proof of Lemma~\ref{lm:loss-L2} for details.) By~\eqref{eq:V2}, we have $\sup_{k} V(f_k) \geq \mathrm{ess\,sup}_{x \in \cX_0} \bar{w}(x)$. Hence, we only need to prove the case where there is an atom $x^*$ such that $w(x^*) =  \mathrm{ess\,sup}_x \, \bar{w}(x) \geq 1$. Let $f$ be the test function constructed in Lemma~\ref{lm:two} with $E = \{x^*\}$. Repeating the argument for Theorem~\ref{th:opt-Q-no-atom}, we get $\Pi(f^2 \bar{w}) \geq \Pi(\bar{w})$. By the Cauchy--Schwarz inequality,
    $\Pi(\bar{w})  \geq a_X + a_Y \geq 1,$ 
    which concludes the proof. 
\end{proof}


\subsection{Proof of Proposition~\ref{coro:lip}}\label{sec:proof-coro-lip}
\begin{proof}
   The lower bound given in~\eqref{eq:lower}  follows from Lemma~\ref{lm:two} with $E = A$, which is still applicable since the test function $f$ in Lemma~\ref{lm:two} is constant on $E$. 

   To prove the upper bound on $R(Q^*, \cF(A, r)) $, fix some $f \in \cF(A, r)$. Following the proof argument for Theorem~\ref{th:discrete}, we get 
   \begin{equation}\label{eq:tmp2}
       (1 - p) \left[ 1 - \Pi(f^2 \ind_A) \right] \geq \Pi(f \ind_A)^2. 
   \end{equation} 
   Let $\Pi|_A$ denote the probability measure on $A$ with  $\Pi|_A(B) = \Pi(B)/\Pi(A)$ for each measurable $B \subset A$. 
   Since $\mathrm{osc}(f, A) \leq r$,  the variance of $f|_A$ with respect to $\Pi|_A$ is at most $r^2 / 4$.  
   Thus, we obtain that 
   \begin{equation}\label{eq:tmp3}
       \Pi( f \ind_A)^2 \geq p \, \Pi(f^2 \ind_A) -  p^2 r^2 / 4,  
   \end{equation}
   which, combined with~\eqref{eq:tmp2}, yields that 
   \begin{equation}\label{eq:tmp4}
       \Pi(f^2 \ind_A) \leq 1 - p + p^2 r^2 / 4. 
   \end{equation} 
   Finally,  letting $w^* = \pi / q^* $ and using $\Pi(f^2) = 1$, we get 
   \begin{align*}
       \Pi(f^2 w^*) = 2p \,\Pi(f^2 \ind_A) + 2(1 - p) \Pi(f^2 \ind_{A^c})
       =  2 (2 p - 1)  \Pi(f^2 \ind_A)  + 2(1 - p). 
   \end{align*} 
   Plugging in the bound from~\eqref{eq:tmp4}  proves the claim. 
\end{proof} 



\subsection{Proof of Proposition~\ref{coro:exp}}\label{sec:proof-exp}
\begin{proof}
We first show that  $ (\sA V)(x)  \leq - \alpha V(x)$  on $ [D, \infty)$,
where $D, \alpha$ are as specified in the theorem and $V(x) = 2 - e^{-|x| / \xi}$. 
On $(0, \infty)$, we have 
\begin{equation}
    V''(x) = - \frac{1}{\xi^2} e^{- x / \xi}, 
\end{equation}
and thus $V$ is concave. The function $\phi$ defined in~\eqref{eq:alpha-theorem} can be expressed by $\phi(x) =\xi^{-2} e^{- (x + \xi)/ \xi} $.  
Using~\eqref{eq:kappa} and numerically computing the cumulative distribution function of the normal distribution, we get 
\begin{equation}
    \kappa(\xi) \geq  \frac{ 1.4 \, e^{-1/2} }{ \sqrt{2 \pi \xi^2} }. 
\end{equation} 
Hence, by Theorem~\ref{th:drift-general},  we have $ (\sA V)(x)  \leq - \alpha V(x)$  on $ [D, \infty)$ if 
\begin{equation}\label{eq:drift-inf}
   \inf_{x \colon x \geq D} \frac{  1.4 \, e^{-3/2}  e^{-|x| / \xi} } { 6 \sqrt{2 \pi} \, Z_\beta \, \pi(x)^{1 - \beta}} 
   \geq \alpha =  \frac{  \beta^{1/\omega} }{49}     \exp\left[   a  (1 - \beta)D^\omega - \xi^{-1} D  \right]. 
\end{equation}   
Using $ \int_0^\infty  \exp\left( -b x^\omega\right)  \dd x 
    =  \omega^{-1} b^{-1/\omega} \Gamma (\omega^{-1})$, we find that 
\begin{align*}
   \frac{1}{Z_\beta \, \pi(x)^{1 - \beta}} =  \frac{\pi(x)^{\beta} }{ Z_\beta \, \pi(x) }  = \beta^{1/\omega} \exp\left[  a  (1 - \beta)|x|^\omega\right]. 
\end{align*} 
A routine calculation shows that the mapping $x \mapsto    a  (1 - \beta) |x|^\omega - |x| / \xi$  is minimized when 
\begin{equation}
    |x| = \left[ \frac{1}{a \xi  \omega (1 - \beta)} \right]^{  1/(\omega - 1)} \leq D. 
\end{equation}
Hence, the infimum in~\eqref{eq:drift-inf} is attained at $x = D$, and one can easily check that the inequality in~\eqref{eq:drift-inf} holds. 
Applying the same argument on $(-\infty, -D]$ yields that 
\begin{equation}
   (\sA V)(x)  \leq - \alpha V(x), \quad \forall \, x \in (-\infty, D] \cup [D, \infty). 
\end{equation}

Since $V$ is bounded, the uniform ergodicity follows from~\citet[Th. 5.2]{down1995exponential} once we can verify that the set $[-D, D]$ is petite for $(Y_t)_{t \geq 0}$. 
To prove this, we note that (1) the average holding time at any $x \in [-D, D]$ is bounded from above by $ Z_\beta  \pi(0)^{ 1-\beta} < \infty$ and from below by $ Z_\beta  \pi(D)^{ 1-\beta} > 0$, 
and (2) the set $[-D, D]$ is small for the discrete-time chain $\cT$. 
%for any integer $m > 2D/\xi$,  we have $\cT^{m}(x, [D - \xi, D] ) > 0 $ for any $x \in [-D, D]$. 
Together, they imply that the set $[-D, D]$ is also small for  $(Y_t)_{t \geq 0}$.  
The bound on $\bbE_x[ e^{\alpha \tau_D} ]$  follows from~\citet[Th. 6.1]{down1995exponential} and the fact $V \leq 2$. 
\end{proof}


\subsection{Proof of Proposition~\ref{coro:poly}} \label{sec:proof-poly}

\begin{proof} 
We first check that $\pi(x)^\beta$ is a proper un-normalized density. Since $\beta < (\gamma - 2) / \gamma < 1$, we have $\pi(x)^\beta \leq 1 \vee \pi(x)$, which implies that $\pi^\beta$ is integrable over any compact set. Condition~\eqref{eq:power-law} implies that there exists $C  < \infty$ such that $\pi(x) \leq C  |x|^{- \gamma }$ for all $x \geq C$. Using $\beta > 1/\gamma$, we find that $\int_C^\infty \pi(x)^\beta \dd x    < \infty$. This proves $Z_\beta = \int \pi(x)^\beta \dd x < \infty$.  


Now we establish a drift condition $ (\sA V)(x)  \leq - \alpha V(x)$ on $(-\infty, D] \cup [D, \infty)$ for any $D \geq 2 \xi$. 
We let $\nu = \gamma (1 - \beta) - 2$ and define the drift function by 
\begin{equation}
    V(x) = 1 + \xi^{-\nu} -  (|x| \vee \xi)^{-\nu}. 
\end{equation}
Note that $\nu > 0$ since $\beta < (\gamma - 2) / \gamma$, which implies that $V$ is  concave on $[\xi, \infty)$.    
Applying Theorem~\ref{th:drift-general}  with $\phi(x) = \nu(\nu + 1) / (x + \xi)^{2 + \nu}$ and using $Z_\beta < \infty$ yields  
\begin{equation} 
    \alpha = \inf_{x \colon |x| \geq D} \frac{\tilde{C}  \nu(\nu + 1)  \xi^2  } {  (1 + \xi^{-\nu} ) (|x| + \xi)^{2 + \nu} \,  \pi(x)^{1 - \beta}},
\end{equation}  
for some fixed constant $\tilde{C} < \infty$. 
Since $x^{2 + \nu}  \pi(x)^{1 - \beta} = [x^{\gamma} \pi(x)]^{1 - \beta}$, it follows from condition~\eqref{eq:power-law} that  $\limsup_{x \rightarrow \infty} x^{2 + \nu}  \pi(x)^{1 - \beta} < \infty$. Hence, $\alpha > 0$, and the uniform ergodicity and hitting time bound follow by the same argument for Proposition~\ref{coro:exp}.  
\end{proof}


\subsection{Proof of Lemma~\ref{lm:negative-drift} } \label{sec:lm-drift}

\begin{proof}
    One can verify by differentiation that $\log(1 + u) \geq u - u^2$ for $u \geq -1/2$. Hence, for $x > 0$ and $|z| \leq (1 + x)/ 2$, 
    \begin{equation}\label{eq:hit1}
        V(x + z) - V(x) = \log \left(1 + \frac{z}{1 + x} \right) \geq \frac{z}{ 1+x } - \frac{  z^2}{(1+x)^2  }. 
    \end{equation}
    Meanwhile, for $x \geq z \geq 0$,  
    \begin{equation}\label{eq:hit2}
                \frac{\pi(x+z)^\beta}{\pi(x)^\beta}
                = \left( 1 + \frac{ z }{1 + x}\right)^{- \gamma \beta} \geq 1 - \frac{\gamma \beta z}{1 + x}. 
    \end{equation}
    Similar to the proof of Theorem~\ref{th:drift-general}, we use $\kappa(z) = 0$ for $|z| > \xi$ to get 
    \begin{equation} 
     \int_{\bbR} \left[ V(y) - V(x) \right] \cT(x, \dd y) =  \int_0^\xi   \kappa(z)   h(x, z)   \dd z,   
    \end{equation}
    where
    \begin{equation}
        h(x, z) = \left[ V(x - z) - V(x)  \right] + \left[ V(x + z) - V(x)  \right]  \frac{\pi(x+z)^\beta}{\pi(x)^\beta}. 
    \end{equation}
    It follows from~\eqref{eq:hit1} and~\eqref{eq:hit2} that for $ x \geq D \geq 2 \xi > 0$ and $0 \leq z \leq \xi$, 
    \begin{equation}
        h(x, z) \geq  - \frac{(  \gamma \beta + 2) z^2}{(1+x)^2  }. 
    \end{equation}
By~\eqref{eq:kappa}, $\kappa(z) \leq 0.6 / \xi$ for any $z$, which yields
\begin{equation}
    \int_{\bbR} \left[ V(y) - V(x) \right] \cT(x, \dd y) 
    \geq -   \frac{ 0.6 (\gamma \beta + 2) }{(1+x)^2  \xi } \int_0^\xi z^2 \dd z =  -   \frac{  (\gamma \beta + 2) \xi^2 }{5 (1+x)^2 }, 
    %\frac{0.6 (2 + \gamma \beta) \xi^2 }{3 (1+x)^2 \log (1 + x)}, 
    \quad \forall \, x \geq D. 
\end{equation} 

Using the definition of $\sA$, we find that for $|x| \geq D$, 
\begin{equation}
    (\sA V)(x) \geq  -   \frac{  (\gamma \beta + 2) \xi^2 }{5 (1+|x|)^2 \, Z_\beta \, \pi(x)^{1 - \beta} } 
    = - \frac{ C(\gamma, \beta, \xi) }{ (1+|x|)^{2- \gamma(1 - \beta)}  },  
\end{equation}
where the constant $C(\gamma, \beta, \xi)$ is given by 
\begin{equation}
    C(\gamma, \beta, \xi) = \frac{ (\gamma \beta - 1) (   \gamma \beta + 2) \xi^2 }{5 (\gamma - 1)} > 0. 
\end{equation} 
Since $\gamma(1 - \beta) \leq 2$,  $(1+|x|)^{2- \gamma(1 - \beta)}$ is monotone increasing on $(0, \infty)$, from which the claimed drift condition follows.  
\end{proof}


