	\section{2-D scenario}
	\label{sec2}
	We first consider the 2-D scenario where the sensors and the signal source are in the 2-D space. This corresponds to the localization problem on the water surface or on the flat ground, for instance. Meanwhile, the 2-D problem is also a part of the 3-D problem that will be addressed later.
	\subsection{Problem formulation}
	Suppose there are \( n \) sensors distributed in a 2-D space, each with precisely known coordinates \( p_i = [x_i, ~ y_i]^T \) for \( i = 1, \ldots, n \). Let \( p^0 = [x^0, ~ y^0]^T \) represent the unknown coordinates of the source that need to be estimated using bearing-only measurements from the sensors.
	Fig. \ref{fig:2D} illustrates the scenario of the 2-D source localization using a bearing-only sensor array, where $a_i^0$ is the noise-free bearing-only measurement obtained by sensor $i,~i=1,...,n$, while the bearing-only measurement of the source obtained by sensor $i$ is given by
	\begin{equation}
		\label{mea_2d}
		a_i = \arctan\left(\frac{y_i-y^0}{x_i-x^0} \right) + \varepsilon_i^a, \quad i=1,...,n,
	\end{equation}
	where $\varepsilon_i^a$ is the measurement noise. For the measurement noises, we make the following assumption.

	\begin{figure}[!t]
		\centering
		\includegraphics[width=0.45\textwidth]{figure/2D_no_grid2.pdf}
		\caption{Illustration of bearing-only measurements in the 2-D scenario. The red dot represents the signal source while the blue dots represent the sensors.}
		\label{fig:2D}
	\end{figure}

	%Every sensor is assigned with a known local coordinate system (LCS). Denote the matrix of coordinate transformation from the CCS to LCS of sensor $i$ by $A_i$, which is a $2 \times 2$ orthonormal matrix. Denote the target's coordinates under the LCS of sensor $i$ by $p^0^i = [x^0^i \,\, y^0^i]^T$, which satisfy:

	%\begin{equation}
	%	\label{2d_trans}
	%	\begin{bmatrix}
		%	x^0^i	\\
		%	y^0^i	
		%	\end{bmatrix} = A_i	\begin{bmatrix}
		%	x^0 - x_i	\\
		%	y^0 - y_i	
		%	\end{bmatrix}, \quad i=1,...,m.
	%\end{equation}

	\begin{assum}
		\label{assum_mea_noise_2d}
		The measurement noises $\varepsilon_i^a, i=1,...,n$ are i.i.d. Gaussian random variables with mean zero and finite variance $\sigma_a^2$.
	\end{assum}

	Based on Assumption \ref{assum_mea_noise_2d}, the log-likelihood function of the model \eqref{mea_2d} is:
	\begin{equation*}
		\ell_n(p) \eq -n \ln(\sqrt{2\pi}\sigma_a) - \frac{1}{2\sigma_a^2}\sum_{i=1}^n\left(a_i-\arctan\left(\frac{y_i-y}{x_i-x}\right)\right)^2.
	\end{equation*}
	Consequently, the ML estimation of the problem is given by:
	\begin{equation}
		\label{ML_2d}
		{\rm \textbf{ML-2D}}: \quad \min_{p = [x,~y]^T \in \mathbb{R}^2}~\frac{1}{n}\sum_{i=1}^n\left(a_i-\arctan\left(\frac{y_i-y}{x_i-x}\right)\right)^2,
	\end{equation}
	which is equivalent to maximize $\ell_n(p)$. 
	Denote the ML estimator as $\widehat{p}_n^{\rm ML}$, which maximizes $\ell_n(p)$.

	\subsection{Asymptotic properties of the ML estimator}

	Before investigating the asymptotic properties of the ML estimator, we present geometric assumptions on the coordinates of the signal source and sensors.
	\begin{assum}
		\label{assum_coordinates_2d}
		The source's coordinates $p^0$ fall in a bounded set $\mathcal{P}^0$ and for $i=1,...,n$, the coordinates of sensors $p_i$ belong to a bounded set $\mathcal{P}$, regardless of $n$. Moreover, $\mathcal{P}^0 \cap \mathcal{P} = \emptyset$. 
	\end{assum}

	%We also denote the angles of arrival under CCS:
	%\begin{equation*}
	%	a^c_i = \arctan\frac{y^0-y_i}{x^0-x_i}.
	%\end{equation*}

	\begin{assum}
		\label{assum_distribution}
		The empirical distribution function $F_n$ of the sequence $p_1, p_2,...$ converges to a distribution function $F_\mu$.	
	\end{assum}

	We denote the probability measure generated by $F_\mu$ as $\mu$. For the asymptotic distribution $F_\mu$ to which the sample distribution of sensors’ coordinates converge, we make the following assumption.

	\begin{assum}
		\label{assum_colinearity}
		For any positive integer $n$, the sensors $p_1,...,p_n$ do not lie on a line. Further, there does not exist   a subset $\mathcal{P'}$ of $\mathcal{P}$ with $\mu(\mathcal{P'}) = 1$ such that $\mathcal{P'}$ is a line. 
	\end{assum}

	Let $f_i(p) \eq \arctan\left((y_i-y)/(x_i-x)\right),~i=1,...,n$ for $p=[x,~y]^T$. We have the following lemma that establishes the asymptotic identifiability of the AOA localization problem.

	\begin{lem}
		\label{lem_uniq_2d}
		Under Assumptions \ref{assum_coordinates_2d}-\ref{assum_colinearity}, the signal source is asymptotically uniquely identifiable. Or equivalently, the limit of $\frac{1}{n}\sum_{i=1}^n\big(f_i(p)-f_i(p^0)\big)^2$ exists and has a unique minimum at $p=p^0$.
	\end{lem}

	\begin{proof}
		It is straightforward that
		\begin{equation*}
			\lim_{n\to \infty}\frac{1}{n}\sum_{i=1}^n\big(f_i(p)-f_i(p^0)\big)^2 = \mathbb{E}_\mu \left\{\left[  \arctan\left(\frac{\tilde{y}-y}{\tilde{x}-x}\right)-\arctan\left(\frac{\tilde{y}-y^0}{\tilde{x}-x^0}\right) \right]^2\right\},
		\end{equation*}
		where $\mathbb{E}_\mu$ is taken over $\tilde{p} = [\tilde{x},~\tilde{y}]^T$ with respect to $\mu$. 

		Suppose that there exists some $p \neq p^0$ such that $$\mathbb{E}_\mu \left\{\left[  \arctan\left(\frac{\tilde{y}-y}{\tilde{x}-x}\right)-\arctan\left(\frac{\tilde{y}-y^0}{\tilde{x}-x^0}\right) \right]^2\right\}=0.$$ Define $\mathcal{P}_p \eq \left\{\tilde{p} \in \mathcal{P}~|~ \arctan((\tilde{y}-y)/(\tilde{x}-x))=\arctan((\tilde{y}-y^0)/(\tilde{x}-x^0)) \right\}$. Then $\mu(\mathcal{P}_p) = 1$. However,  $\arctan((\tilde{y}-y)/(\tilde{x}-x))=\arctan((\tilde{y}-y^0)/(\tilde{x}-x^0))$ is equivalent to the fact that vectors $\tilde{p}-p$ and $\tilde{p}-p^0$ are parallel. Note that $p \neq p^0$, that is to say that $\tilde{p}$ lies on the line going through $p$ and $p^0$. This contradicts Assumption \ref{assum_colinearity}. Note that $\lim_{n \to \infty}\frac{1}{n}\sum_{i=1}^n\big(f_i(p)-f_i(p^0)\big)^2 \geq 0$ and $\lim_{n \to \infty}\frac{1}{n}\sum_{i=1}^n\big(f_i(p^0)-f_i(p^0)\big)^2=0$. Hence, $\lim_{n \to \infty}\frac{1}{n}\sum_{i=1}^n\big(f_i(p)-f_i(p^0)\big)^2$ has a unique minimum at $p=p^0$.

		This completes the proof.
	\end{proof}
	Let $\nabla f_i(p)$ be the gradient vector of $f_i(p)$ with respect to $p$, i.e.,
	\begin{align*}
		\nabla f_{i}(p) &\eq \left[\frac{\partial f_i(p)}{\partial x},~\frac{\partial f_i(p)}{\partial y}\right]\\
		& = \left[ \frac{y_i-y}{\|p_i-p\|^2},~\frac{-x_i+x}{\|p_i-p\|^2}   \right].
	\end{align*}

	To derive the asymptotic variance of the ML estimator $\widehat{p}_n^{\rm ML}$, we first show the following lemmas.

	\begin{lem}
		\label{lem_converge_M}
		Under Assumptions \ref{assum_coordinates_2d}-\ref{assum_colinearity}, the limit of $ \frac{1}{n}\sum_{i=1}^n\big(\nabla f_i(p^0)\big)^T \nabla f_i(p^0)$ exists for the true source $p^0$.
	\end{lem}

	\begin{proof}
		It is straightforward that
		\begin{equation}
			\label{M_p}
			\frac{1}{n}\sum_{i=1}^n\big(\nabla f_i(p^0)\big)^T \nabla f_i(p^0)
			=\frac{1}{n}\sum_{i=1}^n \left( \frac{1}{\|p_i-p^0\|^4}\begin{bmatrix}
				y_i-y^0\\-x_i+x^0
			\end{bmatrix}\left[y_i-y^0, ~ -x_i+x^0\right]\right).
		\end{equation}
		Under  Lemmas \ref{assum_coordinates_2d}-\ref{assum_distribution},  taking the entry of the first row and the first column as an example, it holds that
		\begin{equation*}
			\lim_{n \to \infty}\frac{1}{n^2}\mathbb{V}_\mu\left( \frac{1}{\|p-p^0\|^4}(y-y^0)^2 \right) \to 0,
		\end{equation*}
		where the variance $\mathbb{V}_\mu$ is taken over $p = [x,~y]^T$ with respect to $\mu$. Thus, the limit of $\frac{1}{n}\sum_{i=1}^n\big(\nabla f_i(p^0)\big)^T \nabla f_i(p^0)$ exists.

		This completes the proof.
	\end{proof}

	Then, we  define $M^0 \in \mathbb{R}^{2 \times 2}$ for every $p^0 $   by 
	\begin{equation*}
		M^0 \eq  \lim_{n\to \infty}\frac{1}{n}\sum_{i=1}^n\big(\nabla f_i(p^0)\big)^T \nabla f_i(p^0).
	\end{equation*}
	%of which $[\mathbf{M}(p)]_{jk} = \langle f'_j(p), f'_k(p) \rangle _m$. 
	The following lemma indicates $M^0$ is non-singular.
	\begin{lem}
		\label{lem_invertM_2d}
		Under Assumptions \ref{assum_mea_noise_2d}-\ref{assum_colinearity}, the matrix $M^0$ is non-singular.
	\end{lem}

	\begin{proof}
		By the definition of $M^0$ and Lemma \ref{lem_converge_M}, we have
		\begin{align*}
			M^0 =& \lim_{n\to \infty}\frac{1}{n}\sum_{i=1}^n\big(\nabla f_i(p^0)\big)^T \nabla f_i(p^0)\\
			=&\mathbb{E}_\mu \left( \frac{1}{\|p-p^0\|^4}\begin{bmatrix}
				y-y^0\\-x+x^0
			\end{bmatrix}\left[y-y^0, ~ -x+x^0\right]\right),
		\end{align*}
		where $\mathbb{E}_\mu$ is taken over $p = [x,~y]^T$ with respect to $\mu$.

		Suppose that there exists some $\theta \neq 0$ such that
		\begin{align*}
			\theta^T M^0\theta =& \mathbb{E}_\mu \left( \frac{1}{\|p-p^0\|^4}\theta^T \begin{bmatrix}
				y-y^0\\-x+x^0
			\end{bmatrix}\left[y-y^0, ~ -x+x^0\right]\theta\right]\\
			=& \mathbb{E}_\mu \left[\left(\frac{1}{\|p-p^0\|^2}\left[y-y^0, ~ -x+x^0\right]\theta\right)^2\right]= 0.
		\end{align*}
		Define $\mathcal{P}_\theta \eq \{p\in \mathcal{P}~|~ \left[y-y^0,  ~ -x+x^0\right]\theta = 0\}$.  Then $\mu(\mathcal{P}_\alpha)=1$.  Notice that $\left[x-x^0, ~ y-y^0\right]^T = p-p^0$ and $\left[x-x^0, ~ y-y^0\right]^T$ is perpendicular to $\left[y-y^0, ~ -x+x^0\right]^T$. We have that for every $\tilde{p} \in \mathcal{P}_\theta$, $\theta$ and $\tilde{p}-p^0$ are parallel. That is to say that $\mathcal{P}_\theta$ is a line, which contradicts Assumption \ref{assum_colinearity}. 

		This completes the proof.
	\end{proof}

	Now, we are on the point to give the asymptotic property of the ML estimator. Under Assumptions \ref{assum_mea_noise_2d}-\ref{assum_colinearity}, the ML estimator $\widehat{p}_n^{\rm ML}$ embraces the following consistency and asymptotic normality. The proof is straightforward by checking the conditions in \cite[Theorem 3]{Jennrich1969}, and we omit the proof.

	\begin{thm}[Consistency and asymptotic normality]
		\label{thm_consis_asymnormal_2d}
		Under Assumptions \ref{assum_mea_noise_2d}-\ref{assum_colinearity}, we have $\widehat{p}_n^{\rm ML} \to p^0$ with probability one as $n \to \infty$ with the asymptotic normality
		\begin{equation}
			\label{asy_normal_2d}
			\sqrt{n}(\widehat{p}_n^{\rm ML}-p^0) \to \mathcal{N}\left(0,\sigma_a^2\left(M^0\right)^{-1}\right) \quad {\rm as} ~ n\to \infty.
		\end{equation}
	\end{thm}

	The matrix $M^0$ is tightly related to the Fisher information matrix $F$ of model \eqref{mea_2d}. %Denote $a = [a_1 ~...~a_n]^T$. 
	To see this, firstly we have
	\begin{equation*}
		\frac{\partial \ell_n(p^0)}{\partial p^0} = \frac{1}{\sigma_a^2}\sum_{i=1}^n \varepsilon_i^a \frac{1}{\|p_i-p^0\|^2} \begin{bmatrix}
			y_i-y^0\\-x_i+x^0
		\end{bmatrix}.
	\end{equation*}
	Then we obtain the Fisher information matrix
	\begin{align*}
		F =& \mathbb{E}\left[ \frac{\partial \ell_n(p^0)}{\partial p^0} \left(\frac{\partial \ell_n(p^0)}{\partial p^0}\right)^T \right]\\
		=& \frac{1}{\sigma_a^2} \sum_{i=1}^n\frac{1}{\|p_i-p^0\|^4} \begin{bmatrix}
			y_i-y^0\\-x_i+x^0
		\end{bmatrix}\left[y_i-y^0, ~ -x_i+x^0\right].
	\end{align*}
	This means $\lim_{n\to \infty}nF^{-1} = \sigma_a^2 \left(M^0\right)^{-1}$, which implies that the ML estimator $\widehat{p}_n^{\rm ML}$ is asymptotically efficient. Notice that the CRLB is given by the trace of the inverse of the Fisher
	information matrix, i.e., CRLB $= {\rm tr}(F^{-1})$. From \eqref{asy_normal_2d}, we have $\widehat{p}_n^{\rm ML}$ converges to the true value $p^0$ with the asymptotic covariance of $\sigma_a^2\left(M^0\right)^{-1}/n$.

	Next, we will prove that the ML objective function converges to a function that is convex in a small neighborhood around $p^0$, which forms the feasibility of the two-step scheme. Intuitively, this guarantees that we can break down the difficult ML problem into two easier problems.

	\begin{thm}
		\label{thm_converge_ML_objfunc}
		Under Assumption \ref{assum_mea_noise_2d}-\ref{assum_colinearity}, $\ell_n(p)/n$ converges uniformly to 
		\begin{equation*}
			\ell(p)\eq -\ln(\sqrt{2\pi}\sigma_a)-\frac{1}{2}-\frac{1}{2\sigma_a^2}\lim_{n \to \infty}\frac{1}{n}\sum_{i=1}^n\big(f_i(p)-f_i(p^0)\big)^2
		\end{equation*}
		on $\mathcal{P}^0$. In addition, $\nabla^2(-\ell(p^0)) = M^0/\sigma_a^2$.
	\end{thm}

	\begin{proof}
		It is straightforward that 
		\begin{align*}
			\ell_n(p)/n &= -\ln(\sqrt{2\pi}\sigma_a)-\frac{1}{2\sigma_a^2  n}\sum_{i=1}^n \left[a_i - \arctan\left(\frac{y_i-y}{x_i-x}\right)\right]^2\\
			&= -\ln(\sqrt{2\pi}\sigma_a) - \frac{1}{2\sigma_a^2 n }\sum_{i=1}^n\big(f_i(p^0)-f_i(p)+\varepsilon_i^a\big)^2 \\ &= -\ln(\sqrt{2\pi}\sigma_a) - \frac{1}{2\sigma_a^2}\left[\frac{1}{n}\sum_{i=1}^n \big(f_i(p^0)-f_i(p)\big)^2 + \frac{1}{n}\sum_{i=1}^n2\big(f_i(p^0)-f_i(p)\big)\varepsilon_i^a + \frac{1}{n}\sum_{i=1}^n\varepsilon_a^2\right].
		\end{align*}
		By Lemma \ref{lem_sqrtm} in the Appendix, it holds that $\lim_{n \to \infty}\frac{1}{n}\sum_{i=1}^n2\big(f_i(p^0)-f_i(p)\big)\varepsilon_i^a = 0$ uniformly for $p \in \mathcal{P}_0$. Therefore, it holds that
		\begin{equation*}
			\lim_{n \to \infty} \frac{1}{n}\ell_n(p) = -\ln(\sqrt{2\pi}\sigma_a)-\frac{1}{2}-\frac{1}{2\sigma_a^2}\lim_{n \to \infty}\frac{1}{n}\sum_{i=1}^n\big(f_i(p)-f_i(p^0)\big)^2 = \ell(p)
		\end{equation*}
		uniformly for $p \in \mathcal{P}^0$. Since $\lim_{n \to \infty}\frac{1}{n}\sum_{i=1}^n\big(f_i(p)-f_i(p^0)\big)^2$ has a unique minimizer $p=p^0$ by Lemma \ref{lem_uniq_2d}, so does $\ell_n(p)/n$.

		Next, we show that $\nabla^2(-\ell(p^0)) = M^0/\sigma_a^2$. Notice that $\nabla(-\ell_n(\widehat{p}_n^{\rm ML})) = 0$. The Taylor expansion of $-\ell_n(p)/n$ in a small neighborhood of $\widehat{p}_n^{\rm ML}$ is 
		\begin{equation*}
			-\ell_n(p)/n = -\ell_n(\widehat{p}_n^{\rm ML})/n + \frac{1}{2}(p - \widehat{p}_n^{\rm ML})^T \left( \nabla^2(-\ell_n(\widehat{p}_n^{\rm ML})/n) \right)(p - \widehat{p}_n^{\rm ML})+ o(\|p - \widehat{p}_n^{\rm ML}\|^2),
		\end{equation*}
		where $\nabla^2(-\ell_n(p)/n) = \frac{1}{\sigma_a^2 n}\sum_{i=1}^n \left[\big(\nabla f_i(p)\big)^T \nabla f_i(p) - \nabla^2 f_i(p)(a_i-f_i(p))\right]$. Notice that 
		\begin{equation*}
			\nabla^2(-\ell_n(p^0)/n) = \frac{1}{\sigma_a^2 n}\sum_{i=1}^n \left[\big(\nabla f_i(p^0)\big)^T \nabla f_i(p^0) - \nabla^2 f_i(p^0)(a_i-f_i(p^0))\right] \to \frac{1}{\sigma_a^2}M^0.
		\end{equation*}
		Since $\ell_n(p)/n$ converges uniformly to $\ell(p)$ on $\mathcal{P}^0$, and $\nabla^2(-\ell_n(p)/n)$ converges uniformly on $\mathcal{P}^0$. By combining Assumptions \ref{assum_coordinates_2d}-\ref{assum_distribution}, and the  Helly-Bray theorem, we have $\nabla^2(-\ell_n(p^0)/n) \to \nabla^2 (-\ell(p^0))$ as $n \to \infty$, which implies $\nabla^2(-\ell(p^0)) = M^0/\sigma_a^2$. 

		This completes the proof.
	\end{proof}

	By Lemma \ref{lem_invertM_2d}, it holds that $M^0$ is positive definitive, and so is $\nabla^2(-\ell(p^0))$.

	\subsection{The two-step estimator}
	\label{sec2c}
	We have shown that the ML estimator owns consistency and asymptotic efficiency. However, the ML problem~\eqref{ML_2d} is non-convex and its global solution is hard to achieve. In this section, we introduce a two-step estimation scheme, which can realize the same asymptotic property that the ML estimator possesses.  

	Theorem \ref{thm_converge_ML_objfunc} tells that, although $-\ell_n(p)/n$ is non-convex globally, it can be approximated as a convex function in a small neighborhood around the global minimum $p^0$. When using local iterative methods, e.g., GN
	iterations, if the initial value falls within this
	attraction region, the global minimum can be found. Note that a consistent estimator that converges to $p^0$ will eventually fall within the attraction region as $n$ increases. 
	As a result, the two-step estimator is formally stated as follows \cite{Gourieroux1995,Mu2017}:

	\textbf{Step 1.} Derive a globally consistent estimator $\widehat{p}_n$ for the source's coordinates $p^0$.

	\textbf{Step 2.} Run the GN iteration algorithm with this preliminary estimator as its initial value.

	In Step 2, the GN iteration algorithm  for the ML problem \eqref{ML_2d} has the following form:

	\begin{align} \label{gn_2d}
		\widehat{p}_n(k+1) &= \widehat{p}_n(k) +  \left((J(k))^T J(k)\right)^{-1}(J(k))^T(a - f(k)),
	\end{align}
	where 
	\begin{align*}
		a &=  [a_1,~\cdots ~a_n]^T,\\
		f(k)& = [f_1(\widehat{p}_n(k)), ~ \cdots ~ f_n(\widehat{p}_n(k)]^T,\\
		J(k)& = \left[\big(\nabla f_1(\widehat{p}_n(k))\big)^T, ~ \cdots ~ \big(\nabla f_n(\widehat{p}_n(k))\big)^T\right]^T,\\
		\widehat{p}_n(0)& = \widehat{p}_n.
	\end{align*}

	The two-step scheme described above has the attractive property that only a one-step GN iteration is sufficient to theoretically guarantee that the resulting two-step estimator has the same asymptotic property as the ML estimator \cite{Mu2017,Lehmann1998}. The conclusion is summarized in the following lemma.

	\begin{lem}{\cite[Theorem 2]{Mu2017}\cite[Chapter 6, Theorem 4.3]{Lehmann1998}}
		\label{lem_onestepGN}
		Suppose that $\widehat{p}_n$ is a $\sqrt{n}$-consistent estimator of $p^0$, i.e., $\widehat{p}_n-p^0 = O_p(1/\sqrt{n})$. Denote the one-step GN iteration of $\widehat{p}_n$ by $\widehat{p}_n^{\rm GN}$. Then under Assumptions \ref{assum_mea_noise_2d}-\ref{assum_colinearity}, we have
		\begin{equation*}
			\widehat{p}_n^{\rm GN}-\widehat{p}_n^{\rm ML} = o_p(1/\sqrt{n}).
		\end{equation*}
		This indicates that $\widehat{p}_n^{\rm GN}$ has the same asymptotic property that $\widehat{p}_n^{\rm ML}$ possesses.
	\end{lem}

	The same asymptotic property means that $\widehat{p}_n^{\rm GN}$ is also consistent and asymptotically efficient. From Lemma \ref{lem_onestepGN} we know that the key in the two-step estimation scheme is to obtain a $\sqrt{n}$-consistent estimator in the first step. In the next subsection, we aim to derive such consistent estimator.

	\subsection{Deriving $\sqrt{n}$-consistent estimator for the source's coordinates}

	Define $r_i^0 \eq \sqrt{(x_i-x^0)^2 + (y_i-y^0)^2}$ and $a_i^0 \eq \arctan\left((y_i-y^0)/(x_i-x^0)\right)$ for every $i=1,...,n$.
	Thus, the measurement equation \eqref{mea_2d} is equivalent to
	\begin{equation}
		\label{linear_2d}
		(x_i-x^0)\sin(a_i) - (y_i-y^0)\cos(a_i) = r_i^0 \sin(\varepsilon_i^a),\quad i=1,...,n,
	\end{equation}
	which are derived by using \eqref{trigono_2d_2} and \eqref{trigono_2d_3} in the Appendix.
	%To obtain \eqref{linear_2d}, two equations are applied:
	% \begin{align*}
		%	&(x_i-x^0)\cos(a_i^0) + (y_i-y^0)\sin(a_i^0) = r_i^0,\\
		%	&(x_i-x^0)\sin(a_i^0)-(y_i-y^0)\cos(a_i^0) = 0.
		% \end{align*}

	Define $h_i \eq [\sin(a_i), ~ -\cos(a_i)]^T$. We rewrite \eqref{linear_2d} in the following linear regression form \cite{Lingren1978,Aidala1979,Nardone1984}:
	\begin{equation}
		\label{linear_2d_mat}
		h_i^T p_i = h_i^T p^0 + r_i^0\sin(\varepsilon_i^a), \quad i=1,...n.
	\end{equation}
	By stacking \eqref{linear_2d_mat} for $n$ sensors, we obtain the following matrix form
	\begin{equation}
		Y = Xp^0 + V,\label{eq8}
	\end{equation}
	where 
	\begin{equation*}
		Y  = \begin{bmatrix}
			h_1^T p_1	\\
			h_2^T p_2	\\
			\vdots	\\
			h_n^Tp_n
		\end{bmatrix}, \quad
		X = \begin{bmatrix}
			h_1^T	\\
			h_2^T	\\
			\vdots	\\
			h_n^T
		\end{bmatrix}, \quad 
		V = \begin{bmatrix}
			r_1^0\sin(\varepsilon_1^a)	\\
			r_2^0\sin(\varepsilon_2^a)	\\
			\vdots	\\
			r_m^0\sin(\varepsilon_m^a)
		\end{bmatrix}.
	\end{equation*}
	Then,  the LS estimator corresponding to \eqref{eq8} is given by
	\begin{equation}
		\label{p_biased}
		\widehat{p}^{\rm B}_{n} = \left(X^TX\right)^{-1}X^TY.
	\end{equation}
	For the linear regression model \eqref{eq8}, note that the regressor matrix  $X$ is correlated with the noise vector $V$ due to the measurement noises $\{\varepsilon_i^a,~i=1,...,n\}$.
	As a results, the LS estimator \eqref{p_biased} is biased.
	In the following, we will eliminate the bias of the LS estimator \eqref{p_biased} and eventually obtain an asymptotically unbiased and consistent estimator. 
	For achieving this, we establish a new linear regression form different from \eqref{eq8} based on the noise-free counterpart $X^0$ of $X$. Denote the regressors $h_i^0 \eq [\sin(a_i^0), ~ -\cos(a_i^0)]^T,~ i=1,...,n$, which are the noise-free counterpart of $h_i$.
	Thus,   $h_i$ are connected with $h_i^0$ in the following way
	\begin{equation*}
		h_i = \cos(\varepsilon_i^a)h_i^0 + \sin(\varepsilon_i^a)[\cos(a_i^0), ~ \sin(a_i^0)]^T,\quad i=1,...,n,
	\end{equation*}
	and based on which we rewrite  the linear regression \eqref{linear_2d_mat} as follows
	\begin{equation}
		\label{linear_2d_biaseli}
		h_i^Tp_i = e^{-\sigma_a^2/2}(h_i^0)^Tp^0 + (\cos(\varepsilon_i^a)-e^{-\sigma_a^2/2})(h_i^0)^Tp^0 + \sin(\varepsilon_i^a)[\cos(a_i^0), ~ \sin(a_i^0)]p_i,\quad i=1,...,n.
	\end{equation}
	The matrix form of \eqref{linear_2d_biaseli} is
	\begin{equation}
		\label{linear_2d_biaseli_mat}
		Y = X^0p^0+W,
	\end{equation}
	where
	\begin{equation*}
		X^0 =e^{-\sigma_a^2/2}\begin{bmatrix}
			(h_1^0)^T	\\
			(h_2^0)^T	\\
			\vdots	\\
			(h_n^0)^T
		\end{bmatrix}, \quad 
		W = \begin{bmatrix}
			(\cos(\varepsilon_1^a)-e^{-\sigma_a^2/2})(h_1^0)^Tp^0 + \sin(\varepsilon_1^a)[\cos(a_1^0), ~ \sin(a_1^0)]p_1	\\
			(\cos(\varepsilon_2^a)-e^{-\sigma_a^2/2})(h_2^0)^Tp^0 + \sin(\varepsilon_2^a)[\cos(a_2^0), ~ \sin(a_2^0)]p_2	\\
			\vdots	\\
			(\cos(\varepsilon_n^a)-e^{-\sigma_a^2/2})(h_n^0)^Tp^0 + \sin(\varepsilon_n^a)[\cos(a_n^0), ~ \sin(a_n^0)]p_n
		\end{bmatrix}.
	\end{equation*}

	\begin{prop}
		\label{prop_noise_free_gram}
		Under Assumptions \ref{assum_coordinates_2d}-\ref{assum_colinearity},
		the matrix $\left(X^0\right)^TX^0/n$ is non-singular, and its limit $\lim_{n \to \infty}\left(X^0\right)^TX^0/n$ exists and is non-singular.	
	\end{prop}

	\begin{proof}
		It follows that
		\begin{align*}
			\frac{1}{n}\left(X^0\right)^TX^0 =& e^{-\sigma_a^2}\sum_{i=1}^{n}\frac{1}{n}h_i^0(h_i^0)^T\\
			=&e^{-\sigma_a^2}\sum_{i=1}^{n}\frac{1}{n}\begin{bmatrix}
				\sin^2(a_i^0)	& -\sin(a_i^0)\cos(a_i^0) \\
				-\sin(a_i^0)\cos(a_i^0)	& \cos(a_i^0)
			\end{bmatrix}\\
			=&e^{-\sigma_a^2}\sum_{i=1}^{n}\frac{1}{n}\left(I_2-\frac{1}{(r_i^0)^2}\begin{bmatrix}
				x_i-x^0	\\
				y_i-y^0	
			\end{bmatrix}\left[x_i-x^0, ~ y_i-y^0\right]\right)\\
			=&e^{-\sigma_a^2}\left[I_2 - \frac{1}{n}\sum_{i=1}^{n}\frac{1}{(r_i^0)^2}(p_i-p^0)(p_i-p^0)^T\right].
		\end{align*}
		Notice that the trace of the $2 \times 2$ matrix $\frac{1}{n}\sum_{i=1}^{n}(r_i^0)^{-2}(p_i-p^0)(p_i-p^0)^T$ is 1, then $I_2 - \frac{1}{n}\sum_{i=1}^{n}(r_i^0)^{-2}(p_i-p^0)(p_i-p^0)^T$ is non-singular if $\frac{1}{n}\sum_{i=1}^{n}(r_i^0)^{-2}(p_i-p^0)(p_i-p^0)^T$ is non-singular. Otherwise, suppose that $\frac{1}{n}\sum_{i=1}^{n}(r_i^0)^{-2}(p_i-p^0)(p_i-p^0)^T$ is not non-singular. Thus there exists some $\theta = [\theta_1, ~ \theta_2]^T \neq 0$ such that for all $i=1,...,n$,
		\begin{equation*}
			(p_i-p^0)^T\theta = 0,
		\end{equation*}
		which is equivalent to that for all the sensors $\{p_i,~i=1,...,n\}$ lie on a line. This
		contradicts Assumption \ref{assum_colinearity}.

		The existence of $\lim_{n \to \infty} \left(X^0\right)^T X^0 / n$ can be established using a method similar to the one used in the proof of Lemma \ref{lem_converge_M}.  Further, if $\lim_{n \to \infty}\left(X^0\right)^TX^0/n$ is singular, then there exists some $\theta \in \mathbb{R}^2$ with $\| \theta\|=1$ such that
		\begin{equation*}
			\theta^T\lim_{n \to \infty}\frac{1}{n}\left(X^0\right)^TX^0\theta = e^{-\sigma_a^2}\mathbb{E}_{\mu}\left[1 - \frac{1}{\|p-p^0\|^2}\theta^T(p-p^0)(p-p^0)^T\theta\right]=0.
		\end{equation*}

		Define $\mathcal{P}_\theta = \{p\in \mathcal{P}~|~ (p-p^0)^T\theta = \|p-p^0\|\}$. Notice that for any $p$, $(p-p^0)^T\theta \leq \|p-p^0\|$. Thus there holds that $\mathcal{P}_\theta = 1$. However, $(p-p^0)^T\theta = \|p-p^0\|$ means that $p-p^0$ and $\theta$ are parallel, which means $\mathcal{P}_\theta$ is a line. This contradicts Assumption \ref{assum_colinearity}. 

		This completes the proof.
	\end{proof}

	The non-singularity of the matrix $\left(X^0\right)^TX^0/n$ derived in Proposition \ref{prop_noise_free_gram} provides the theoretical foundation for using the LS estimator of the linear regression model \eqref{linear_2d_biaseli_mat} to estimate $p^0$:
	\begin{equation}
		\label{unbiased_esti_2d}
		\widehat{p}_{n}^{\rm UB} = \left(\left(X^0\right)^TX^0\right)^{-1}\left(X^0\right)^TY.
	\end{equation} 
	The estimator \eqref{unbiased_esti_2d} has the desired statistical properties, which are presented in the following theorem.
	\begin{thm}
		\label{thm_ub_2d}
		Under Assumption \ref{assum_mea_noise_2d}-\ref{assum_colinearity}, the  estimator $\widehat{p}_n^{\rm UB}$ is unbiased and further $\sqrt{n}$-consistent, i.e., $\widehat{p}_{n}^{\rm UB}-p^0 = O_p(1/\sqrt{n})$.
	\end{thm}

	\begin{proof}
		It is straightforward from \eqref{linear_2d_biaseli_mat} that 
		\begin{equation*}
			\widehat{p}^{\rm UB}_{n} = \left(\left(X^0\right)^TX^0\right)^{-1}\left(X^0\right)^T(X^0p^0+W) = p^0 + \left(\frac{1}{n}\left(X^0\right)^TX^0\right)^{-1}\left(\frac{1}{n}\left(X^0\right)^TW\right)
		\end{equation*}
		and $\mathbb{E}\widehat{p}^{\rm UB}_{n}=p^0$.
		The noise sequence of the model \eqref{linear_2d_biaseli_mat} has zero mean and its variance is upper bounded by
		\begin{align*}
			\mathbb{E}&\left((\cos(\varepsilon_i^a)-e^{-\sigma_a^2/2})(h_i^0)^Tp^0 + \sin(\varepsilon_i^a)[\cos(a_i^0), ~ \sin(a_i^0)]p_i\right)^2 \\
			&=\mathbb{E}\left(\big(\cos(\varepsilon_i^a\big)-e^{-\sigma_a^2/2})^2\left((h_i^0)^Tp^0\right)^2\right) 
			+ \mathbb{E}\left(\sin^2(\varepsilon_i^a)([\cos(a_i^0),~\sin(a_i^0)]p_i)^2\right)\\
			&\leq\mathbb{V}(\cos(\varepsilon_i^a))\|p^0\|^2 + \mathbb{V}(\sin(\varepsilon_i^a))\|p_i\|^2
		\end{align*}
		according to Lemma \ref{lem_moment_cos_sin} in the Appendix  and Assumption \ref{assum_coordinates_2d}. Then, by Lemma \ref{lem_sqrtm} in the Appendix, we have
		\begin{equation}
			\frac{1}{n}\left(X^0\right)^TW = O_p(1/\sqrt{n}).\label{xw}
		\end{equation}
		Thus, we obtain from \eqref{xw} and Proposition \eqref{prop_noise_free_gram} that
		\begin{equation*}
			\widehat{p}_{n}^{\rm UB} - p^0 = \left(\frac{1}{n}\left(X^0\right)^TX^0\right)^{-1}\left(\frac{1}{n}\left(X^0\right)^TW\right) =O(1)O_p(1/\sqrt{n})=O_p(1/\sqrt{n}).
		\end{equation*}
		This completes the proof.
	\end{proof}
	So far, we have obtained two  LS estimators, \eqref{p_biased} and \eqref{unbiased_esti_2d}, for the measurement equation \eqref{mea_2d}. The LS estimator \eqref{p_biased} is implementable using the available data; however, it is biased. On the other hand, the LS estimator \eqref{unbiased_esti_2d} is $\sqrt{n}$-consistent but cannot be implemented with the given data since the regressor matrix \(X^0\) is not available.
	To derive an implementable $\sqrt{n}$-consistent estimator, which is the main focus of this subsection, we aim to establish a direct relationship between these two LS estimators. Specifically, we intend to eliminate the bias of the LS estimator \eqref{p_biased} by calculating the non-negligible differences between \(X^TX/n\) and \((X^0)^TX^0/n\), and between \(X^TY/n\) and \((X^0)^TY/n\).
	%  By subtracting the gap, we can eliminate the bias of $\widehat{p}^{\rm B}_{n}$ and achieve the estimator $\widehat{p}_{n}^{\rm UB}$ asymptotically.
	We first present the BELS estimator
	\begin{equation}
		\label{biaseli_esti_2d}
		\widehat{p}^{\rm BE}_{n} = \left(\frac{1}{n}X^TX - \mathbb{V}(\sin(\varepsilon_1^a)) I_2\right)^{-1}\left(\frac{1}{n}X^TY-\mathbb{V}(\sin(\varepsilon_1^a))\Big(\frac{1}{n}\sum_{i=1}^{n}p_i\Big)
		\right),
	\end{equation}
	from which we clearly see the differences between the two  LS estimators, where $\mathbb{V}(\sin(\varepsilon_1^a)=\frac{1}{2}(1-e^{-2\sigma_a^2})$ (See Equation \eqref{lm10-5} of Lemma \ref{lem_moment_cos_sin} in the Appendix) represents the variance of the random variable $\sin(\varepsilon_1^a)$. 
	Note that the BELS estimator~\eqref{biaseli_esti_2d} requires the prior information  $\mathbb{V}(\sin(\varepsilon_1^a))$.

	The BELS estimator \eqref{biaseli_esti_2d} possesses the desired property of being $\sqrt{n}$-consistent, as established in the following theorem. Moreover, the proof of the theorem will clarify why the BELS estimator is constructed in this manner to eliminate the bias of the LS estimator \eqref{p_biased}.
	\begin{thm}
		\label{thm_be_2d}
		Under Assumptions \ref{assum_mea_noise_2d}-\ref{assum_colinearity}, the BELS estimator is $\sqrt{n}$-consistent, i.e., $\widehat{p}^{\rm BE}_{n}- p^0 = O_p(1/\sqrt{n})$.
	\end{thm}

	The proof can be found in Appendix \ref{proof_thm_be_2d}.

	If \(\mathbb{V}(\sin(\varepsilon_1^a))\), or equivalently \(\sigma^2_a\), is not available, then a consistent estimator for \(\mathbb{V}(\sin(\varepsilon_1^a))\) can achieve the same goal. This result is presented in the following corollary as a direct extension of Theorem~\ref{thm_be_2d}.
	\begin{cor}
		\label{cor_consis_var_2d}
		In the case that $\sigma_a^2$ is unknown, the BELS estimator $\widehat{p}_{n}^{\rm BE}$ is still $\sqrt{n}$-consistent if $\mathbb{V}(\sin(\varepsilon_1^a))$ is replaced by a $\sqrt{n}$-consistent estimator of $\mathbb{V}(\sin(\varepsilon_1^a))$.
	\end{cor}

	In the next subsection, we will give a $\sqrt{n}$-consistent estimator of $\mathbb{V}(\sin(\varepsilon_1^a))$ using the data.

	\subsection{Deriving $\sqrt{n}$-consistent estimator of the variance of the sine of the noise}
	In this section, we will derive a $\sqrt{n}$-consistent estimator for $\mathbb{V}(\sin(\varepsilon_1^a))$, drawing inspiration from \cite[Proposition 2]{Stoica1982}. 

	Define
	\begin{equation}
		\label{QS}
		Q_n \eq \frac{1}{n}\begin{bmatrix}
			X^T	\\
			Y^T	\end{bmatrix}\left[X ~ Y\right], \quad
		S_n \eq \begin{bmatrix}
			I_2	&\frac{1}{n}\sum\limits_{i=1}^{n}p_i  \\
			\frac{1}{n}\sum\limits_{i=1}^{n}p_i^T	& \frac{1}{n}\sum\limits_{i=1}^{n}\|p_i\|^2
		\end{bmatrix}.
	\end{equation}
	We proposed the estimator for $\mathbb{V}(\sin(\varepsilon_1^a))$  given by
	\begin{equation}
		\widehat{v}^a_n = \frac{1}{\lambda_{\rm max}\left(Q_n^{-1}S_n\right)},\label{sina}
	\end{equation}
	where $\lambda_{\rm max}(\cdot)$ denotes the maximum eigenvalue of a square matrix.

	The following theorem shows that $\widehat{v}^a_n$ is a $\sqrt{n}$-consistent estimator of $\mathbb{V}(\sin(\varepsilon_1^a))$.

	\begin{thm}
		\label{thm_var_2d}
		Under Assumptions \ref{assum_mea_noise_2d}-\ref{assum_colinearity},
		$\widehat{v}^a_n$ is a $\sqrt{n}$-consistent estimator of $\mathbb{V}(\sin(\varepsilon_1^a))$, i.e.,  $\widehat{v}^a_n-\mathbb{V}(\sin(\varepsilon_1^a)) = O_p(1/\sqrt{n})$.
	\end{thm}

	The proof can be found in Appendix \ref{proof_thm_var_2d}.

	We summarize the estimation procedure for the variance of the sine of the noise in Algorithm \ref{algo1}.

	\begin{algorithm}
		\caption{The estimation algorithm for the variance of the sine of the noise (2-D scenario)}  
		\label{algo1}
		\begin{algorithmic}[1]
			\Require Sensor locations $\{p_i,~i=1,...,n\}$ and noisy bearing-only measurements $\{a_i,~i=1,..,n\}$.
			\State Calculate $Q_n$ and $S_n$ according to \eqref{QS};
			\State Calculate the maximum eigenvalue of $Q_n^{-1}S_n$;
			\Ensure The estimate of the variance of the sine of noise $\widehat{v}^a_n = 1/\lambda_{\rm max}(Q_n^{-1}S_n)$.
		\end{algorithmic}
	\end{algorithm}

	Algorithm \ref{algo2} presents the complete procedure for source localization using the proposed two-step estimator based on bearing-only measurements in the 2-D scenario.
	\begin{algorithm}
		\caption{The estimation algorithm for consistent and asymptotically efficient two-step estimator   using bearing-only measurements (2-D scenario)}  
		\label{algo2}
		\begin{algorithmic}[1]
			\Require Sensor locations $\{p_i,~i=1,...,n\}$, bearing-only measurements $\{a_i,~i=1,...,n\}$, and noise variance $\sigma_a^2$ (if available).
			\If {$\sigma_a^2$ is available}
			\State Calculate the variance of the sine of noise according to  \eqref{lm10-5} of Lemma \ref{lem_moment_cos_sin} in the Appendix;
			\State Calculate the bias-eliminated estimate $\widehat{p}_n^{\rm BE}$ according to \eqref{biaseli_esti_2d};
			\Else
			\State Run Algorithm \ref{algo1} to obtain the estimate $\widehat{v}^a_n$ of the variance of the sine of the noise;
			\State Calculate the bias-eliminated estimate $\widehat{p}_n^{\rm BE}$ according to \eqref{biaseli_esti_2d} with $\mathbb{V}(\sin(\varepsilon_1^a))$ being replaced by  $\widehat{v}^a_n$;
			\EndIf

			\State Run a one-step GN iteration \eqref{gn_2d} for $\widehat{p}_n^{\rm BE}$ to obtain $\widehat{p}_n^{\rm GN}$;
			\Ensure The source location estimate $\widehat{p}_n^{\rm GN}$.
		\end{algorithmic}
	\end{algorithm}

	In Algorithm \ref{algo1}, note that $[X~Y] \in \mathbb{R}^{n \times 3}$ and $S_n \in \mathbb{R}^{3 \times 3}$. The computational complexity is primarily determined by the matrix summation and multiplication in Line 1. Consequently, the computational complexity of Algorithm \ref{algo1} is $\mathcal{O}(n)$. For Algorithm \ref{algo2}, with $X \in \mathbb{R}^{n \times 2}$ and $Y \in \mathbb{R}^{n \times 1}$, the computational complexity of Line 3 or 6 and Line 8 is also $\mathcal{O}(n)$. Therefore, the overall computational complexity of Algorithm \ref{algo2} is $\mathcal{O}(n)$, meaning that its execution time increases linearly with the number of measurements.

	\section{3-D scenario}
	\label{sec3}
	In this section, we focus on the 3-D scenario, where both the sensors and the signal source are located in a 3-D space. This scenario is more complex than the previously discussed 2-D scenario and can be regarded as an extension of it.
	\subsection{Problem formulation}
	Suppose there are \( n \) sensors distributed in a 3-D space, each with precisely known coordinates \( p_i = [x_i, ~ y_i, ~ z_i]^T \) for \( i = 1, \ldots, n \). Let \( p^0 = [x^0, ~ y^0, ~ z^0]^T \) represent the unknown coordinates of the source that need to be estimated using bearing-only measurements from the sensors. Formally, the bearing-only measurement of the signal source obtained by sensor \( i \) is given by
	\begin{subequations}
		\label{mea_3d}
		\begin{align}
			\label{mea_3d_b}
			a_i &= \arctan\left(\frac{y_i-y^0}{x_i-x^0} \right) + \varepsilon_i^a, \quad i=1,...,n, \\
			\label{mea_3d_e}
			e_i &= \arctan\left(\frac{z_i-z^0}{\sqrt{(x_i-x^0)^2 + (y_i-y^0)^2}} \right) + \varepsilon_i^e, \quad i=1,...,n,
		\end{align}
	\end{subequations}
	where $\varepsilon_i^a$ and $\varepsilon_i^e$ are the measurement noises. For the measurement noises, we make the following assumption.

	\begin{assum}
		\label{assum_mea_noise_3d}
		\begin{enumerate}[(i)]
			\item The azimuth angle measurement noises $\varepsilon_i^a,~ i=1,...,n$ are i.i.d. Gaussian random variables with mean zero and finite variance $\sigma_a^2$. 
			\item The elevation angle measurement noises $\varepsilon_i^e,~ i=1,...,n$ are i.i.d. Gaussian random variables with mean zero and finite variance $\sigma_e^2$. \item $\{\varepsilon_i^a,~i=1,...,n\}$ and $\{\varepsilon_i^e,~i=1,...,n\}$ are mutually independent.
		\end{enumerate}
	\end{assum}
	Assumption \ref{assum_mea_noise_3d} entails that the log-likelihood function of the ML estimation for the problem \eqref{mea_3d} is
	\begin{align*}
		\ell_n(p) =& -n\ln(\sqrt{2\pi}\sigma_a)-n\ln(\sqrt{2\pi}\sigma_e)\\
		&-\frac{1}{2}\sum_{i=1}^n\left(\frac{1}{\sigma_a^2}\left( a_i-\arctan\left(\frac{y_i-y}{x_i-x}\right) \right)^2 + \frac{1}{\sigma_e^2}\left( e_i-\arctan\left(\frac{z_i-z}{\sqrt{(x_i-x)^2+(y_i-y)^2}}\right) \right)^2\right).
	\end{align*}
	Therefore, the ML estimation is given by
	\begin{equation}
		\label{ML_3d}
		{\rm \textbf{ML-3D}}:~ \min_{p=[x,y,z]^T \in \mathbb{R}^3}\frac{1}{n}\sum_{i=1}^n\left(\frac{1}{\sigma_a^2}\left( a_i-\arctan\left(\frac{y_i-y}{x_i-x}\right) \right)^2 + \frac{1}{\sigma_e^2}\left( e_i-\arctan\left(\frac{z_i-z}{\sqrt{(x_i-x)^2+(y_i-y)^2}}\right) \right)^2\right),
	\end{equation}
	which is equivalent to maximizing $\ell_n(p)$. Denote the ML estimator as $\widehat{p}_n^{\rm ML}$, which maximizes $\ell_n(p)$.

	\subsection{Asymptotic properties of the ML estimator}
	Let $(p_i)_{1:2} \eq [x_i, ~ y_i]^T$ be the first two coordinates of $p_i$ for $i=1,...,n$. We make the assumptions on the coordinates of the signal source and sensors that are similar to the 2-D scenario.

	\begin{assum}
		\label{assum_coordinates_3d}
		The source's coordinates $p^0$ fall in a bounded set $\mathcal{P}^0$ and for $i=1,...,n$, the coordinates of sensors $p_i$ belong to a bounded set $\mathcal{P}$, regardless of $n$. Moreover, $\mathcal{P}^0 \cap \mathcal{P} = \emptyset$.
	\end{assum}

	\begin{assum}
		\label{assum_projection}
		Denote $\mathcal{P}^0_{1:2} \eq \{[x^0, ~ y^0]^T ~|~ [x^0, ~ y^0, ~ z^0]^T \in \mathcal{P}^0\}$ and $\mathcal{P}_{1:2} \eq \{[x, ~ y]^T ~|~ [x, ~ y, ~ z]^T \in \mathcal{P}\}$. 
		\begin{enumerate}[(i)]
			\item $\mathcal{P}^0_{1:2} \cap \mathcal{P}_{1:2} = \emptyset$;
			\item The empirical distribution function $F_n$ of the sequence $p_1, p_2,...$ converges to a distribution function $F_\mu$;
			\item 
			For any positive integer $n$, $p_1,...,p_n$ do not lie on a line. Further, there does not exist   a subset $\mathcal{P'}$ of $\mathcal{P}$ with $\mu(\mathcal{P'}) = 1$ such that $\mathcal{P'}$ is a line. 


		\end{enumerate}
	\end{assum}
	For each $p=[x,y,z]^T\in \mathcal{P}$, we modify the notation $f_i(p)$ in the 2-D scenario to suit the 3-D scenario here:
	\begin{align*}
		&f_{i}(p) \eq 
		\left[
		\frac{1}{\sigma_a}
		\arctan\left(\frac{y_i-y}{x_i-x}\right),~
		\frac{1}{\sigma_e}
		\arctan\left(\frac{z_i-z}{\sqrt{(x_i-x)^2+(y_i-y)^2}}\right)
		\right]^T
	\end{align*} 
	for $i=1,\cdots,n$.
	Furthermore, let $\nabla f_{i}(p)$  be the the Jacobian of $f_{i}(p)$ with respect to $p$, i.e.,
	\begin{align*}
		\nabla f_{i}(p) &= \left[\frac{\partial f_{i}(p)}{\partial x}, ~ \frac{\partial f_{i}(p)}{\partial y},~ \frac{\partial f_{i}(p)}{\partial z}  \right]\\
		&=\begin{bmatrix}
			\frac{1}{\sigma_a}\frac{y_i-y}{(x_i-x)^2+(y_i-y)^2} & -\frac{1}{\sigma_a}\frac{x_i-x}{(x_i-x)^2+(y_i-y)^2}& 0\\
			\frac{1}{\sigma_e}\frac{(x_i-x)(z_i-z)}{\sqrt{(x_i-x)^2+(y_i-y)^2}\|p_i-p\|^2} & \frac{1}{\sigma_e}\frac{(y_i-x)(z_i-z)}{\sqrt{(x_i-x)^2+(y_i-y)^2}\|p_i-p\|^2} & \frac{1}{\sigma_e} \frac{-\sqrt{(x_i-x)^2+(y_i-y)^2}}{\|p_i-p\|^2}
		\end{bmatrix}.
	\end{align*}
	%{\color{red}Let $g(p)\eq[g_{11}(p), ~ f_{21}(p),\cdots,~f_{1n}(p),~f_{2n}(p)]^T$ for $p=[x,y,z]^T$ with
		%\begin{align*}
		%&f{1i}(p) \eq \sigma_a^{-1}\arctan\left((y_i-y)/(x_i-x)\right),~i=1,\cdots,n\\
		%&f_{2i}(p) \eq \sigma_e^{-1}\arctan\left((z_i-z)/\sqrt{(x_i-x)^2+(y_i-y)^2}\right)~i=1,\cdots,n.
		%\end{align*} }
		The following lemma  establishes the asymptotic identifiability and local strong convexity of the problem \eqref{mea_3d}. 
		\begin{lem}
			\label{lem_uniq_3d}
			Suppose that Assumptions \ref{assum_coordinates_3d}-\ref{assum_projection} hold.
			\begin{enumerate}[(i)]
				\item The true signal source is asymptotically uniquely identifiable, equivalently
				\begin{equation*}
					\lim_{n \to \infty}\frac{1}{n}\sum_{i=1}^n \big(f_{i}(p)-f_{i}(p^0)\big)^T\big(f_{i}(p)-f_{i}(p^0)\big)
				\end{equation*}
				has a unique minimum at $p=p^0$.
				\item For the true source $p^0$, the matrix  
				$$  \frac{1}{n}\sum_{i=1}^n \big(\nabla f_{i}(p^0)\big)^T \nabla f_{i}(p^0)$$ tends to a deterministic matrix as $n\xra{}\infty$   and further the limiting matrix, denoted by $M^0 \in \mathbb{R}^{3 \times 3}$, is non-singular.
			\end{enumerate}


		\end{lem}

		The proof can be found in Appendix \ref{proof_lem_3d}.


		%By Lemma \ref{lem_uniq_3d} (ii), we use the notation $M^0 \in \mathbb{R}^{3 \times 3}$ to denote the limiting matrix
		%\begin{equation*}
		%  M^0 \eq \lim_{n \to \infty} \frac{1}{n}\sum_{i=1}^n \big(\nabla f_{i}(p^0)\big)^T \nabla %f_{i}(p^0).
		%\end{equation*}
		Based on  Lemma \ref{lem_uniq_3d}, the ML estimator $\widehat{p}_n^{\rm ML}$ shares the consistency and asymptotic normality presented in the following theorem, which is the counterpart of Theorem \ref{thm_consis_asymnormal_2d} in the 2-D scenario. 
		\begin{thm}[Consistency and asymptotic normality]
			\label{thm_consis_asymnormal_3d}
			Under Assumptions \ref{assum_mea_noise_3d}-\ref{assum_projection}, we have $\widehat{p}_n^{\rm ML} \to p^0$ with probability one as $n \to \infty$ with the asymptotic normality
			\begin{equation*}
				\sqrt{n}(\widehat{p}_n^{\rm ML} - p^0) \to \mathcal{N}\left(0,\left(M^0\right)^{-1}\right), \quad {\rm as} ~ n \to \infty.
			\end{equation*}
		\end{thm}
		Similar to the  2-D scenario,  the ML estimator $\widehat{p}_n^{\rm ML}$ is asymptotically efficient.

		%Further, similar to the 2-D scenario, we give the convergence of the  objective function of the ML problem \eqref{ML_3d}. The proof is the same as that of Theorem \ref{thm_converge_ML_objfunc} is omitted here.

		%\begin{thm}
		%\label{lem_converge_ML_objfunc_3d}
		%Under Assumptions \ref{assum_mea_noise_3d}-\ref{assum_projection}, %$\ell_n(p)/n$ converges uniformly to 
		%\begin{equation*}
		%   \ell(p) \eq -n\ln(\sqrt{2\pi}\sigma_b)-n\ln(\sqrt{2\pi}\sigma_e) - 1 - \frac{1}{2}\lim_{n\to \infty}\frac{1}{n}\sum_{i=1}^n(f_{1i}(p)-f_{1i}(p^0))^2 - \frac{1}{2}\lim_{n\to \infty}\frac{1}{n}\sum_{i=1}^n(f_{2i}(p)-f_{2i}(p^0))^2.
		%\end{equation*}
		%on $\mathcal{P}^0$. In addition, $\nabla^2(-\ell(p^0)) = M^0$.
		%\end{thm}

		\subsection{The two-step estimator}

		In this subsection, we present a two-step estimation scheme for localization using bearing-only measurements in the 3-D scenario. This approach is similar to the one described for the 2-D scenario in Section \ref{sec2c}, but with a different GN iteration algorithm.

		Let $\widehat{p}_n$ be the consistent estimator for $p^0$ derived in the first step.
		Thus, the GN iteration algorithm in the second step is
		\begin{align}\label{gn_3d}
			\widehat{p}_n(k+1) &= \widehat{p}_n(k) +  \left((J(k))^T J(k)\right)^{-1}(J(k))^T(\eta - g(k)),
		\end{align}
		where 
		\begin{align*}
			\eta &= [a_1,~ e_1, ~ \cdots, a_n,~ e_n]^T,\\
			g(k) &= [(f_{1}(\widehat{p}_n(k)))^T, ~ \cdots ~ (f_{n}(\widehat{p}_n(k)))^T]^T,\\
			J(k) &= [(\nabla f_{1}(\widehat{p}_n(k)))^T, ~ \cdots ~  (\nabla f_{n}(\widehat{p}_n(k)))^T]^T,\\
			\widehat{p}_n(0) &= \widehat{p}_n.
		\end{align*}
		As the theoretical properties of Lemma \ref{lem_onestepGN} for the 2-D scenario, the two-step estimator with one-step GN iteration is asymptotically equivalent to the ML estimator  if the estimator derived in the first step is $\sqrt{n}$-consistent \cite{Mu2017}, \cite{Lehmann1998}. 

		In what follows, we will focus on deriving a $\sqrt{n}$-consistent estimator for localization using bearing-only measurements in the 3-D scenario.

		\subsection{Deriving $\sqrt{n}$-consistent estimator for localization using bearing-only measurements}

		For $i=1,...,n$, define
		\begin{align*}
			&r_i^0 \eq \sqrt{(x_i-x^0)^2 + (y_i-y^0)^2},\\
			&d_i^0 \eq \sqrt{(x_i-x^0)^2 + (y_i-y^0)^2 + (z_i-z^0)^2},\\
			&a_i^0 \eq \arctan\left((y_i-y^0)/(x_i-x^0)\right),\\
			&e_i^0 \eq \arctan\left((z_i-z^0)/\sqrt{(x_i-x^0)^2+(y_i-y^0)^2}\right).
		\end{align*}
		The measurement equations \eqref{mea_3d} are equivalent to
		\begin{subequations}
			\label{linear_3d}
			\begin{align}
				\label{linear_3d_b}
				&(x_i-x^0) \sin(a_i) - (y_i-y^0) \cos(a_i) = r_i^0 \sin(\varepsilon_i^a),\quad i=1,...,n,\\
				\label{linear_3d_e}
				&	r_i^0\sin(e_i) - (z_i-z^0)\cos(e_i) = d_i^0\sin(\varepsilon_i^e), \quad i=1,...,n,
			\end{align}
		\end{subequations}
		which are derived by using \eqref{trigono_2d} and \eqref{trigono_3d} in the Appendix.

		Moving terms of Equations \eqref{linear_3d} produces the following linear regression form with respect to $p^0$
		\begin{subequations}
			\label{linear_3d_mat}
			\begin{align}
				\label{linear_3d_b_mat}
				h_i^T (p_i)_{1:2} &= h_i^T p^0_{1:2} + r_i^0\sin(\varepsilon_i^a), \quad i=1,...n,\\
				\label{linear_3d_e_mat}
				\sin(e_i)r_i^0-\cos(e_i)z_i &= -\cos(e_i)z^0 + d_i^0\sin(\varepsilon_i^e) , \quad i=1,...n,
			\end{align} 
		\end{subequations}
		where $h_i = [\sin(a_i), ~ -\cos(a_i)]^T$.

		Under Assumptions \ref{assum_mea_noise_3d}-\ref{assum_coordinates_3d}, model \eqref{linear_3d_b_mat} is exactly model \eqref{linear_2d_mat} in the 2-D scenario. 
		Therefore, according to \eqref{biaseli_esti_2d}, the BELS estimator of the first two coordinates $p^0_{1:2}$ of $p^0$  is given by
		\begin{equation}
			\label{biaseli_esti_3d_b}
			(\widehat{p}_{1:2})_{n}^{\rm BE} = \left(\frac{1}{n}X^TX - \mathbb{V}(\sin(\varepsilon_1^a)) I_2\right)^{-1}\left(\frac{1}{n}X^TY-\mathbb{V}(\sin(\varepsilon_1^a))\Big(\frac{1}{n}\sum_{i=1}^{n}(p_i)_{1:2}\Big)
			\right),
		\end{equation}
		where \begin{equation*}
			X =  \begin{bmatrix}
				h_1^T	\\
				h_2^T	\\
				\vdots	\\
				h_n^T
			\end{bmatrix}, \quad
			Y = \begin{bmatrix}
				h_1^T(p_1)_{1:2}	\\
				h_2^T(p_2)_{1:2}	\\
				\vdots	\\
				h_n^T(p_n)_{1:2}
			\end{bmatrix}.
		\end{equation*}
		The $\sqrt{n}$-consistency of $(\widehat{p}_{1:2})_{n}^{\rm BE}$ follows directly from Theorem \ref{thm_be_2d} in the 2-D scenario, which is presented in the following proposition.
		\begin{prop}
			\label{prop_be_3d_b}
			The BELS estimator of the first two coordinates of the source is $\sqrt{n}$-consistent, i.e., $(\widehat{p}_{1:2})_{n}^{\rm BE}- p^0_{1:2} = O_p(1/\sqrt{n})$.
		\end{prop}
		In what follows, we will derive the BELS estimator for the third coordinate $z^0$.

		By stacking \eqref{linear_3d_e_mat} for $n$ sensors, we obtain the following linear regression form with respect to $z^0$:
		\begin{equation}\label{zphi}
			\Gamma = \Phi z^0+\zeta,
		\end{equation}
		where
		\begin{equation*}
			\Gamma =\begin{bmatrix}
				\sin(e_1)r_1^0-\cos(e_1)z_1	\\
				\sin(e_2)r_2^0-\cos(e_2)z_2	\\
				\vdots	\\
				\sin(e_n)r_n^0-\cos(e_n)z_n
			\end{bmatrix}, \quad
			\Phi=\begin{bmatrix}
				-\cos(e_1)	\\
				-\cos(e_2)	\\
				\vdots	\\
				-\cos(e_n)
			\end{bmatrix}, \quad
			\zeta = \begin{bmatrix}
				d_1^0\sin(\varepsilon_1^e)	\\
				d_2^0\sin(\varepsilon_2^e)	\\
				\vdots	\\
				d_n^0\sin(\varepsilon_n^e)	
			\end{bmatrix}.	
		\end{equation*}
		The resulting LS estimator is
		\begin{equation}
			\label{z_biased}
			\widehat{z}_n^{\rm B} = \left(\Phi^T\Phi\right)^{-1}\Phi^T\Gamma.
		\end{equation}
		The correlation between $\Phi$  and $\zeta$ and the unavailability of $\{r_i^0,~i=1,...,n\}$ involved in $\Gamma$  make the LS estimator \eqref{z_biased} neither consistent nor applicable.
		Similar to the 2-D scenario, we rewrite   \eqref{linear_3d_e_mat} as
		\begin{equation}
			\label{linear_3d_biaseli_e}
			\sin(e_i)r_i^0-\cos(e_i)z_i = -e^{-\sigma_e^2/2}\cos(e_i^0)z^0 - (\cos(\varepsilon_i^e)-e^{-\sigma_e^2/2})\cos(e_i^0)z^0+\sin(\varepsilon_i^e)(d_i^0+\sin(e_i^0)z^0).
		\end{equation}
		Its vector-matrix form  is
		\begin{equation}
			\label{gg}
			\Gamma = \Phi^0 z^0 + \omega,
		\end{equation}
		where
		\begin{equation*}
			\Phi^0=e^{-\sigma_e^2/2}\begin{bmatrix}
				-\cos(e_1^0)	\\
				-\cos(e_2^0)	\\
				\vdots	\\
				-\cos(e_n^0)
			\end{bmatrix}, \quad
			\omega = \begin{bmatrix}
				-(\cos(\varepsilon_1^e)-e^{-\sigma_e^2/2})\cos(e_1^0)z^0+\sin(\varepsilon_1^e)(d_1^0+\sin(e_1^0)z^0)	\\
				-(\cos(\varepsilon_2^e)-e^{-\sigma_e^2/2})\cos(e_2^0)z^0+\sin(\varepsilon_2^e)(d_2+\sin(e_2^0)z^0)	\\
				\vdots	\\
				-(\cos(\varepsilon_n^e)-e^{-\sigma_e^2/2})\cos(e_n^0)z^0+\sin(\varepsilon_n^e)(d_n^0+\sin(e_n^0)z^0)	
			\end{bmatrix}.	
		\end{equation*}

		For the regressor matrix $\Phi^0$, we have the following proposition.
		\begin{prop}
			\label{prop3}
			Under Assumptions \ref{assum_coordinates_3d}-\ref{assum_projection}, $\left(\Phi^0\right)^T\Phi^0/n$ is below bounded by a positive constant for all large $n$.
		\end{prop}
		\begin{proof}
			It follows that
			\begin{equation*}
				\frac{1}{n}\left(\Phi^0\right)^T\Phi^0 = e^{-\sigma_e^2}\sum_{i=1}^{n}\frac{1}{n}\cos^2(e_i^0)
				=e^{-\sigma_e^2}\frac{1}{n}\sum_{i=1}^{n}\frac{(x_i-x^0)^2 + (y_i-y^0)^2}{(x_i-x^0)^2 + (y_i-y^0)^2 + (z_i-z^0)^2}.
			\end{equation*}

			On the one hand, $(x_i-x^0)^2 + (y_i-y^0)^2 + (z_i-z^0)^2$ is upper bounded by a positive constant since $\mathcal{P}$ and $\mathcal{P}^0$ are bounded. On the other hand, since $\mathcal{P}_{1:2} \cap \mathcal{P}^0_{1:2} = \emptyset$ and both two sets are bounded, $(x_i-x^0)^2 + (y_i-y^0)^2$ is below bounded by a positive constant. Therefore, $(\Phi^0)^T\Phi^0/n$ is uniformly below bounded by a positive constant for all $n$.

			This completes the proof.
		\end{proof}
		Thus, we  define the LS estimator of the model \eqref{gg} for $z^0$ by
		\begin{equation}
			\label{unbiased_esti_z}
			\widehat{z}_n^{\rm UB} = \left((\Phi^0)^T\Phi^0\right)^{-1}(\Phi^0)^T\Gamma,
		\end{equation}
		which shares the $\sqrt{n}$-consistency given in the following theorem.
		\begin{thm}
			\label{thm_ub_z}
			Under Assumptions \ref{assum_mea_noise_3d}-\ref{assum_projection}, the LS estimator $\widehat{z}_{n}^{\rm UB}$ is $\sqrt{n}$-consistent, i.e., $\widehat{z}_{n}^{\rm UB}-z^0 = O_p(1/\sqrt{n})$.
		\end{thm}
		The proof can be found in Appendix \ref{proof_thm_ub_z}.



		Although the $\sqrt{n}$-consistent LS estimator $\widehat{z}_{n}^{\rm UB}$ cannot be implemented in practice due to the inaccessibility of the unavailable $r_i^0$ values, the first two coordinates of the source involved in $r_i^0$ can be estimated using the BELS estimator $(\widehat{p}_{1:2})_n^{\rm BE}$, as given in \eqref{biaseli_esti_3d_b}.
		Write $(\widehat{p}_{1:2})_n^{\rm BE}$ as the element-wise form $(\widehat{p}_{1:2})_n^{\rm BE}= [\widehat{x}_n^{\rm BE}, ~ \widehat{y}_n^{\rm BE}]^T$ and define
		\begin{align}
			\widehat{r}_i = \sqrt{(x_i-\widehat{x}_n^{\rm BE})^2 + (y_i-\widehat{y}_n^{\rm BE})^2}\label{hatr}
		\end{align}
		for all $i=1,...,n$. Thus, we have
		\begin{align}
			\nonumber
			\widehat{r}_i =& \sqrt{(x_i-\widehat{x}_n^{\rm BE})^2 + (y_i-\widehat{y}_n^{\rm BE})^2}\\
			\nonumber
			=&\sqrt{(x_i-x^0)^2 + (x^0-\widehat{x}_n^{\rm BE})^2 +2(x^0-\widehat{x}_n^{\rm BE})(x_i-x^0) + (y_i-y^0)^2 + (y^0-\widehat{y}_n^{\rm BE})^2+2(y^0-\widehat{y}_n^{\rm BE})(y_i-y^0)}\\
			\nonumber
			=&\sqrt{(r_i^0)^2 + O_p(1/\sqrt{n})}\\
			=&r_i^0 + O_p(1/\sqrt{n}),\label{rr}
		\end{align}
		where the third equation holds because of Proposition \ref{prop_be_3d_b} and Assumption \ref{assum_coordinates_3d}.

		Let
		\begin{equation}
			\label{hat_beta}
			\widehat{\Gamma} = \begin{bmatrix}
				\sin(e_1)\widehat{r}_1-\cos(e_1)z_1	\\
				\sin(e_2)\widehat{r}_2-\cos(e_2)z_2	\\
				\vdots	\\
				\sin(e_n)\widehat{r}_n-\cos(e_n)z_n
			\end{bmatrix}.	
		\end{equation}

		We propose the following BELS estimator for $z^0$:
		\begin{equation}
			\label{biaseli_esti_z}
			\widehat{z}_n^{\rm BE} =  \left(\frac{1}{n}\Phi^T\Phi - \mathbb{V}(\sin(\varepsilon_1^e))\right)^{-1}\left(\frac{1}{n}\Phi\widehat{\Gamma} - \mathbb{V}(\sin(\varepsilon_1^e))\Big(\frac{1}{n}\sum_{i=1}^{n}z_i\Big)\right),
		\end{equation}
		where $\mathbb{V}(\sin(\varepsilon_1^e))= (1-e^{-2\sigma_e^2})/2$ (See Equation \eqref{lm10-5} of Lemma \ref{lem_moment_cos_sin} in the Appendix).
		\begin{thm} \label{BELS_3D_case}
			Under Assumptions \ref{assum_mea_noise_3d}-\ref{assum_projection}, the BELS estimator $\widehat{z}_n^{\rm BE}$ is $\sqrt{n}$-consistent, i.e., $\widehat{z}_n^{\rm BE} - z^0 = O_p(1/\sqrt{n})$.
		\end{thm}

		\begin{proof}
			The proof can be found in the Appendix \ref{proof_BELS_3D_case}.
		\end{proof}
		Thus, we can define the BELS estimator of $\widehat{p}_n^{\rm BE}$ by
		\begin{equation}
			\label{bels_3d}
			\widehat{p}_n^{\rm BE} = \begin{bmatrix}
				(\widehat{p}_{1:2})_n^{\rm BE}	\\
				\widehat{z}_n^{\rm BE}	
			\end{bmatrix},
		\end{equation}
		where $(\widehat{p}_{1:2})_n^{\rm BE}$ and $\widehat{z}_n^{\rm BE}$ are given in \eqref{biaseli_esti_3d_b} and \eqref{biaseli_esti_z}, respectively.

		Combining with Propostion \ref{prop_be_3d_b} and Theorem \ref{BELS_3D_case}, we obtain the $\sqrt{n}$-consistency of $\widehat{p}_n^{\rm BE}$, which is stated in the following theorem.
		\begin{thm}
			The BELS estimator $\widehat{p}_n^{\rm BE}$  given by \eqref{bels_3d} for the source $p^0$
			is $\sqrt{n}$-consistent, i.e., $\widehat{p}_n^{\rm BE} - p^0 = O_p(1/\sqrt{n})$.
		\end{thm}
		When the noise variances $\sigma_a^2$ and $\sigma_e^2$ are unknown, the BELS estimator $\widehat{p}_{n}^{\rm BE}$ in \eqref{bels_3d} remains $\sqrt{n}$-consistent if $\mathbb{V}(\sin(\varepsilon_1^a)) $ and $\mathbb{V}(\sin(\varepsilon_1^e))$ are replaced by their respective $\sqrt{n}$-consistent estimators.

		The $\sqrt{n}$-consistent estimator for $\mathbb{V}(\sin(\varepsilon_1^a))$ can refer to \eqref{sina} for the 2-D scenario, in the next subsection, so we focus on deriving a $\sqrt{n}$-consistent estimator for $\mathbb{V}(\sin(\varepsilon_1^e))$.

		\subsection{Deriving $\sqrt{n}$-consistent estimator of $\mathbb{V}(\sin(\varepsilon_1^e)) $}

		%Suppose that Assumptions \ref{assum_mea_noise_3d}-\ref{assum_coordinates_3d} hold, then deriving the $\sqrt{n}$-consistent estimator of $\mathbb{V}(\sin(\varepsilon_1^b))$ is equivalent to the case of 2-D problem, which can be achieved according to Theorem \ref{thm_var_2d}.

		For completing the BELS estimator \eqref{bels_3d}, we aim to derive a $\sqrt{n}$-consistent estimator of $\mathbb{V}(\sin(\varepsilon_1^e))$ here, which is similar to that given for $\mathbb{V}(\sin(\varepsilon_1^a))$ in the 2-D scenario following the idea from \cite[Proposition 2]{Stoica1982}.

		Denote
		\begin{equation}
			\label{RU}
			R_n \eq \frac{1}{n}\begin{bmatrix}
				\Phi^T \\
				\widehat{\Gamma}
			\end{bmatrix}
			\begin{bmatrix}
				\Phi, ~ \widehat{\Gamma}
			\end{bmatrix}, 
			\quad U_n \eq \begin{bmatrix}
				1 & \frac{1}{n}\sum\limits_{i=1}^n z_i \\
				\frac{1}{n}\sum\limits_{i=1}^n z_i & \frac{1}{n}\sum\limits_{i=1}^n \big(z_i^2+(\widehat{r}_i)^2\big)
			\end{bmatrix},
		\end{equation}
		where $\Phi$, $\widehat{\Gamma}$, and $\widehat{r}_i$ are defined by \eqref{zphi}, \eqref{hat_beta}, and \eqref{hatr}, respectively.
		Thus, we estimate $\mathbb{V}(\sin(\varepsilon_1^e)) $ by
		\begin{equation}
			\label{W}
			\widehat{v}^e_n \eq \frac{1}{\lambda_{\rm max}(R_n ^{-1}U_n)},
		\end{equation}
		which is a $\sqrt{n}$-consistent estimator of $\mathbb{V}(\sin(\varepsilon_1^e))$ given in
		the following theorem.
		\begin{thm}
			\label{thm_var_3d}
			Under Assumptions \ref{assum_mea_noise_3d}-\ref{assum_projection}, $\widehat{v}^e_n$ is a $\sqrt{n}$-consistent estimator of $\mathbb{V}(\sin(\varepsilon_1^e))$, i.e., $\widehat{v}^e_n - \mathbb{V}(\sin(\varepsilon_1^e)) = O_p(1/\sqrt{n})$.
		\end{thm}

		\begin{proof}
			The proof can be found in Appendix \ref{proof_thm_var_3d}.
		\end{proof}

		We summarize the estimation procedure of the variance of the sine of the elevation angle noise in Algorithm \ref{algo3}.

		\begin{algorithm}[!h]
			\caption{The estimation algorithm of the variance of the sine of the elevation angle noise }  
			\label{algo3}
			\begin{algorithmic}[1]
				\Require Sensor positions $\{p_i,~ i=1,...,n\}$ and bearing-only measurements $\{a_i,~e_i,~i=1,...,n\}$.
				\State Calculate the BELS estimator $(\widehat{p}_{1:2})_n^{\rm BE}$ of the first two coordinates of the source location according to Algorithm \ref{algo2} using the sensor positions $\{p_i,~i=1,...,n\}$ and the measurements $\{a_i,~i=1,...,n\}$.;
				\State Calculate $\widehat{\Gamma}$ according to $(\widehat{p}_{1:2})_n^{\rm BE}$, \eqref{hatr}, and \eqref{hat_beta};
				\State Calculate $R_n$ and $U_n$ according to \eqref{RU};
				\State Calculate the maximum eigenvalue of $R_n^{-1}U_n$;
				\Ensure The estimate of the variance of the sine of elevation angle noise $\widehat{v}^e_n = 1/\lambda_{\rm max}(R_n^{-1}U_n)$.
			\end{algorithmic}
		\end{algorithm}

		The whole procedure of the proposed two-step estimator in the 3-D scenario is summarized in Algorithm \ref{algo4}. 

		\begin{algorithm}[!h]
			\caption{The estimation algorithm for consistent and asymptotically efficient two-step estimator   using bearing-only measurements (3-D scenario)}  
			\label{algo4}
			\begin{algorithmic}[1]
				\Require Sensor locations $\{p_i,~i=1,...,n\}$, bearing-only measurements $\{a_i,~e_i,~i=1,...,n\}$, the azimuth angle noise variance $\sigma_a^2$ (if available), and the elevation angle noise variance $\sigma_e^2$ (if available).
				\State Apply Algorithm \ref{algo2} to obtain the BELS estimate $(\widehat{p}_{1:2})_n^{\rm BE} = [\widehat{x}_n^{\rm BE},~ \widehat{y}_n^{\rm BE}]^T$ of the first two coordinates of the source location;
				\If {$\sigma_e^2$ is available}
				\State Calculate the variance of the sine of noise by $\sigma_e^2$  according to Lemma \ref{lem_moment_cos_sin} in the Appendix;
				\State Calculate the BELS estimate $\widehat{z}_n^{\rm BE}$ of the third coordinate of source location according to \eqref{biaseli_esti_z};
				\Else
				\State Apply Algorithm \ref{algo3} to obtain the estimate $\widehat{v}^e_n$ for the variance of the sine of the elevation angle noise;
				\State Calculate the BELS estimate $\widehat{z}_n^{\rm BE}$ of the third coordinate of source location according to \eqref{biaseli_esti_z} with $\mathbb{V}(\sin(\varepsilon_1^e))$ being replaced by $\widehat{v}^e_n$;
				\EndIf
				\State Set $\widehat{p}^{\rm BE}_n = \left[\widehat{x}_n^{\rm BE},~ \widehat{y}_n^{\rm BE}, ~ \widehat{z}_n^{\rm BE}\right]^T$;
				\State Run a one-step GN iteration \eqref{gn_3d} and obtain $\widehat{p}_n^{\rm GN}$;
				\Ensure The source location estimate $\widehat{p}_n^{\rm GN}$.
			\end{algorithmic}
		\end{algorithm}

		In Algorithm \ref{algo3}, Line 1 has a time complexity of $\mathcal{O}(n)$, based on the time complexity of Algorithm \ref{algo2}. The remaining steps in Algorithm \ref{algo3} are similar to those in Algorithm \ref{algo1}, which also has a time complexity of $\mathcal{O}(n)$. Therefore, the overall time complexity of Algorithm \ref{algo3} is $\mathcal{O}(n)$. Similarly, in Algorithm \ref{algo4}, Line 1 invokes Algorithm \ref{algo2}, which has a time complexity of $\mathcal{O}(n)$. The rest of Algorithm \ref{algo4} follows the same structure as Algorithm \ref{algo2}, also requiring $\mathcal{O}(n)$ time. Hence, the overall time complexity of Algorithm \ref{algo4} is $\mathcal{O}(n)$.

		\section{Simulations}
		\label{sec4}

		In this section, we conduct Monte-Carlo simulations to verify our theoretical development. Simulations for the 2-D scenario and 3-D scenario are conducted separately. In 2-D scenario, we compare our estimators, denoted by  Bias-Eli and Bias-Eli+GN, respectively, with
		\begin{enumerate}[(i)]
			\item PLS: the LS estimator \eqref{p_biased} that corresponds to the linear regression model \eqref{eq8} \cite{Lingren1978,Nardone1984};
			\item MPR-SDP+GN: the 2-D version of the modified polar representation, which is produced by the GN iteration  initialized with the SDP-based method \cite{Wang2018b};
			\item Subspace: a relaxation-based linear estimator reducing errors by making use of all bearing and intersensor bearing geometric information \cite{Luo2019}.
		\end{enumerate}
		In 3-D scenario, we compare our Bias-Eli and Bias-Eli+GN estimators with 
		\begin{enumerate}[(i)]
			\item PLS: the combination of the LS estimators \eqref{p_biased} and \eqref{z_biased}, which is generalized from the 2-D version;

			\item BR-PLE: the bias reduced solution to a CWLS problem that approximates the sine and cosine functions using their first-order Taylor expansions and then expands the parameter space by one dimension while imposing a norm constraint \cite{Wang2015};

			\item MPR-EV: the modified polar representation given by computing an eigenvector with bias reduction \cite{Sun2020};

			\item MPR-SDP+GN: the modified polar representation  produced by the GN iteration,  initialized using the SDP-based method \cite{Wang2018}.
		\end{enumerate}
		We conduct $N$ Monte Carlo experiments for different realizations of measurement noises and denote the estimate obtained in the $j$-th experiment by $\widehat{p}_{n,j}$ for each estimator. The bias and root mean squared error (RMSE) of the estimators are then evaluated using the following definitions \cite{Wang2023,Zeng2024}:
		\begin{align*}
			&{\rm Bias}(\widehat{p}_n) = \sum_{i=1}^m\big(\Delta(\widehat{p}_n)\big)_i,~~ \Delta(\widehat{p}_n)  = \left| \frac{1}{N}\sum_{j=1}^N \widehat{p}_{n,j} - p^0  \right|,\\
			&{\rm RMSE}(\widehat{p}_n)= \sqrt{\frac{1}{N}\sum_{j=1}^N\|\widehat{p}_{n,j} - p^0\|^2},
		\end{align*}
		where $p^0$ is the true source location, $m$ is the dimension of the source coordinates, with $m = 2$ in the 2-D scenario and $m = 3$ in the 3-D scenario. We use the root-CRLB (RCRLB) as the performance benchmark for each estimator, assessing whether the RMSE of each estimator approaches the corresponding RCRLB.

		\subsection{2-D scenario: fixed sensors}
		\label{subsec:A}
		We set the 10 fixed sensors with the coordinates:
		\begin{align*}
			& p_1 = [0,100]^T,~p_2=[0,50]^T,~p_3=[50,50]^T,~p_4=[50,0]^T,~p_5=[50,-50]^T,\\
			& p_6 = [0,-50]^T,~p_7=[0,-100]^T,~p_8=[-50,-50]^T,~p_9=[-50,0]^T,~p_{10}=[-50,50]^T,
		\end{align*}
		which  guarantee that Assumptions \ref{assum_coordinates_2d}-\ref{assum_colinearity} hold.
		Each sensor measures $T$ round i.i.d. observations in total. With the increase of $T$, the number of bearing-only measurements can be large enough to reveal the asymptotic behaviors of these estimators. Notice that this setting is equivalent to place $T$ sensors at each of aforementioned 10 placement sites, and these $10T$ sensors make $n=10T$ i.i.d. observations in total. It is straightforward that, as $T$ increases, the sample distribution of the $10T$ sensors converges to a distribution $\mu$ satisfying that $\mu(p) = 1/10$ for $p$ at any of the aforementioned 10 placement sites, and $\mu(p)=0$, otherwise. Thus, Assumptions \ref{assum_distribution} and \ref{assum_colinearity} hold. The coordinates of source location are $p^0=[60,10]^T$. Hence, Assumption \ref{assum_coordinates_2d} holds.

		We first illustrate the biases and RMSEs for varying numbers of measurements (varying $T$, equivalently) of each estimator. The standard deviation of the measurement noise is $\sigma_a = 0.2$. We set $T$ as $10,30,100,200,300$, and $500$, respectively, and for each $T$, we conduct 1000 Monte-Carlo runs.

