		\subsection{Proof of Theorem \ref{thm_be_2d}}
		\label{proof_thm_be_2d}
		Consider the linear models \eqref{eq8} and \eqref{linear_2d_biaseli} and denote
		\begin{equation*}
			\Delta X \eq X-X^0  =
			\begin{bmatrix}
				h_1^T-e^{-\sigma_a^2/2} (h^0_1)^T\\
				h_2^T-e^{-\sigma_a^2/2} (h^0_2)^T\\
				\vdots\\
				h_n^T-e^{-\sigma_a^2/2} (h^0_n)^T\\
			\end{bmatrix}
			= \begin{bmatrix}
				(\cos(\varepsilon_1^a) - e^{-\sigma_a^2/2})(h_1^0)^T + \sin(\varepsilon_1^a)[\cos(a_1^0),~\sin(a_1^0)]	\\
				(\cos(\varepsilon_2^a) - e^{-\sigma_a^2/2})(h_2^0)^T + \sin(\varepsilon_2^a)[\cos(a_2^0),~\sin(a_2^0)]	\\
				\vdots	\\
				(\cos(\varepsilon_n^a) - e^{-\sigma_a^2/2})(h_n^0)^T + \sin(\varepsilon_n^a)[\cos(a_n^0),~\sin(a_n^0)]
			\end{bmatrix}.
		\end{equation*}
		Then we have
		\begin{equation*}
			\frac{1}{n}X^TX = \frac{1}{n}\left(X^0\right)^TX^0 + \frac{1}{n}\left(X^0\right)^T\Delta X + \frac{1}{n}(\Delta X)^TX^0 + \frac{1}{n}(\Delta X)^T\Delta X.
		\end{equation*}
		For the cross term, note that both the sequences $\{\cos(\varepsilon_i^a)-e^{-\sigma_a^2/2}\}$ and $\{\sin(\varepsilon_i^a)\}$ have zero mean   and finite variance. Thus,  by Lemma \ref{lem_sqrtm} we have
		\begin{equation}
			\begin{split}
				\label{ecos_esin}
				\frac{1}{n}\left(X^0\right)^T\Delta X %\label{ecos_esin_2}	
				=& e^{-\sigma_a^2/2}\frac{1}{n}\sum_{i=1}^{n}(\cos(\varepsilon_i^a)-e^{-\sigma_a^2/2})h_i^0(h_i^0)^T + e^{-\sigma_a^2/2}\frac{1}{n}\sum_{i=1}^{n}\sin(\varepsilon_i^a)h_i^0[\cos(a_i^0), ~ \sin(a_i^0)] \\
				%\label{ecos_esin_3}
				=& O_p(1/\sqrt{n}).
			\end{split}
		\end{equation}
		using the similar arguments as used in the proof of Theorem \ref{thm_ub_2d}.
		For the quadratic term, we have
		\begin{align*}
			\frac{1}{n}(\Delta X)^T \Delta X 
			=&\frac{1}{n}\sum_{i=1}^{n}(\cos(\varepsilon_i^a)-e^{-\sigma_a^2/2})^2 h_i^0(h_i^0)^T + \frac{1}{n}\sum_{i=1}^{n}\sin^2(\varepsilon_i^a)\begin{bmatrix}
				\cos^2(a_i^0)	& \cos(a_i^0)\sin(a_i^0) \\
				\cos(a_i^0)\sin(a_i^0)	& \sin^2(a_i^0)
			\end{bmatrix} \\
			&+\frac{1}{n}\sum_{i=1}^{n} \sin(\varepsilon_i^a)(\cos(\varepsilon_i^a)-e^{-\sigma_a^2/2})
			\left( h_i^0 [\cos(a_i^0), ~ \sin(a_i^0)] +  \begin{bmatrix}
				\cos(a_i^0)	\\
				\sin(a_i^0)	
			\end{bmatrix}  (h_i^0)^T \right).
		\end{align*}
		Assumption \ref{assum_mea_noise_2d} indicates that the second moment of $\cos(\varepsilon_i^a)$ and $\sin(\varepsilon_i^a)$ is   available by Lemmas \ref{lem_moment_cos_sin} and \ref{lem_sqrtm}, and hence we obtain
		\begin{equation}
			\label{vcos_vsin}
			\begin{split}
				%\notag
				\frac{1}{n}(\Delta X)^T \Delta X& = \frac{1}{n}\sum_{i=1}^{n}\mathbb{E}\big((\cos(\varepsilon_i^a) - e^{-\sigma_a^2/2})^2\big)h_i^0(h_i^0)^T \\
				&\hspace{5mm}+ \frac{1}{n}\sum_{i=1}^{n}\mathbb{E}\big(\sin^2(\varepsilon_i^a)\big)\begin{bmatrix}
					\cos^2(a_i^0)	& \cos(a_i^0)\sin(a_i^0) \\
					\cos(a_i^0)\sin(a_i^0)	& \sin^2(a_i^0)
				\end{bmatrix} + O_p(1/\sqrt{n})\\
				%\label{vcos_vsin_2}
				&=\frac{1}{n}\sum_{i=1}^{n}\mathbb{V}(\cos(\varepsilon_i^a))h_i^0(h_i^0)^T + \frac{1}{n}\sum_{i=1}^{n}\mathbb{V}(\sin(\varepsilon_i^a))\big(I_2-h_i^0(h_i^0)^T\big) + O_p(1/\sqrt{n})\\
				%\label{vcos_vsin_3}
				&=\big(\mathbb{V}(\cos(\varepsilon_1^a))-\mathbb{V}(\sin(\varepsilon_1^a))\big)
				\frac{1}{n}\sum_{i=1}^{n}h_i^0(h_i^0)^T+\mathbb{V}(\sin(\varepsilon_1^a))I_2 + O_p(1/\sqrt{n}),
			\end{split}
		\end{equation}
		where the second equation holds because for every $i=1,...,n$,
		\begin{equation*}
			\begin{bmatrix}
				\cos^2(a_i^0)	& \cos(a_i^0)\sin(a_i^0) \\
				\cos(a_i^0)\sin(a_i^0)	& \sin^2(a_i^0)
			\end{bmatrix} = I_2 - h_i^0(h_i^0)^T.
		\end{equation*}
		Thus, we have
		\begin{equation}
			\label{xtx}
			\frac{1}{n}X^TX = \left(1+e^{\sigma_a^2}\mathbb{V}(\cos(\varepsilon_1^a)) - e^{\sigma_a^2}\mathbb{V}(\sin(\varepsilon_1^a))\right)
			\frac{1}{n}\left(X^0\right)^TX^0 + \mathbb{V}(\sin(\varepsilon_1^a))I_2 + O_p(1/\sqrt{n}).
		\end{equation}

		Similarly, we have
		\begin{align*}
			\frac{1}{n}X^TY =& \frac{1}{n}\left(X^0\right)^TY + \frac{1}{n}(\Delta X)^TY\\
			=& \frac{1}{n}\left(X^0\right)^TY + \frac{1}{n}(\Delta X)^T W+ \frac{1}{n}(\Delta X)^TX^0p^0 \\
			=& \frac{1}{n}\left(X^0\right)^TY+ \frac{1}{n}(\Delta X)^T W + O_p(1/\sqrt{n}) .
		\end{align*}
		For the last term, using the similar argument as used in \eqref{vcos_vsin}, by Lemmas \ref{lem_moment_cos_sin} and \ref{lem_sqrtm} we derive
		\begin{align*}
			\frac{1}{n}(\Delta X)^TW =& \frac{1}{n}\sum_{i=1}^{n}\big(\cos(\varepsilon_i^a)-e^{-\sigma_a^2/2}\big)^2h_i^0(h_i^0)^Tp^0 + \frac{1}{n}\sum_{i=1}^{n}\sin^2(\varepsilon_i^a)\begin{bmatrix}
				\cos^2(a_i^0)	& \cos(a_i^0)\sin(a_i^0) \\
				\cos(a_i^0)\sin(a_i^0)	& \sin^2(a_i^0)
			\end{bmatrix}p_i\\
			&+\frac{1}{n}\sum_{i=1}^{n} \sin(\varepsilon_i^a)\big(\cos(\varepsilon_i^a)-e^{-\sigma_a^2/2}\big)\left(h_i^0\big[\cos(a_i^0),~\sin(a_i^0)\big]p_i + \begin{bmatrix}
				\cos(a_i^0)	\\
				\sin(a_i^0)	
			\end{bmatrix}  (h_i^0)^Tp^0\right)\\
			=&\frac{1}{n}\sum_{i=1}^{n}\mathbb{V}(\cos(\varepsilon_i^a))h_i^0(h_i^0)^Tp^0 + \frac{1}{n}\sum_{i=1}^{n}\mathbb{V}(\sin(\varepsilon_i^a))\left(I_2-h_i^0(h_i^0)^T\right)p_i + O_p(1/\sqrt{n})\\
			=&\big(\mathbb{V}(\cos(\varepsilon_1^a))-\mathbb{V}(\sin(\varepsilon_1^a))\big)
			\frac{1}{n}\sum_{i=1}^{n}h_i^0(h_i^0)^Tp^0+\mathbb{V}(\sin(\varepsilon_1^a))\frac{1}{n}\sum_{i=1}^{n}p_i + O_p(1/\sqrt{n}),
		\end{align*}
		where the last equation holds by using $(h_i^0)^Tp_i = (h_i^0)^T p^0$, which is obtained by reorganizing  \eqref{trigono_2d_2}.

		Notice that 
		\begin{equation*}
			\frac{1}{n}\left(X^0\right)^TY = \frac{1}{n}\left(X^0\right)^TX^0p^0 + \frac{1}{n}\left(X^0\right)^T W= \frac{1}{n}\left(X^0\right)^TX^0p^0 + O_p(1/\sqrt{n}).
		\end{equation*}
		We obtain
		\begin{equation}
			\label{xty}
			\frac{1}{n}X^TY = \big(1+e^{\sigma_a^2}\mathbb{V}(\cos(\varepsilon_1^a)) - e^{\sigma_a^2}\mathbb{V}(\sin(\varepsilon_1^a))\big)\Big(\frac{1}{n}\left(X^0\right)^TX^0p^0\Big) + \mathbb{V}(\sin(\varepsilon_1^a))\frac{1}{n}\sum_{i=1}^{n}p_i + O_p(1/\sqrt{n}).
		\end{equation}
		Therefore, there holds that
		\begin{align*}
			\widehat{p}_{n}^{\rm BE}& = \left(\frac{1}{n}X^TX -\mathbb{V}(\sin(\varepsilon_1^a))I_2\right)^{-1}\left(\frac{1}{n}X^TY-\mathbb{V}(\sin(\varepsilon_1^a))\frac{1}{n}\sum_{i=1}^{n}p_i
			\right)\\
			&= \left(\frac{K}{n}\left(X^0\right)^TX^0 + O_p(1/\sqrt{n})\right)^{-1} \left(\frac{K}{n}\left(X^0\right)^TX^0p^0 + O_p(1/\sqrt{n})\right)\\
			&=p^0 + O_p(1/\sqrt{n}),
		\end{align*}
		where $K = 1+e^{\sigma_a^2}\mathbb{V}(\cos(\varepsilon_1^a)) - e^{\sigma_a^2}\mathbb{V}(\sin(\varepsilon_1^a))=e^{-\sigma_a^2}$ is a non-zero constant by Lemma \ref{lem_moment_cos_sin}.
		Consequently, the BELS estimator $\widehat{p}_{n}^{\rm BE}$ is $\sqrt{n}$-consistent.

		This completes the proof.


		\subsection{Proof of Theorem \ref{thm_var_2d}}
		\label{proof_thm_var_2d}
		By \eqref{xtx} and \eqref{xty}, we have
		\begin{align*}
			Q_n&
			= 	\begin{bmatrix}
				e^{-\sigma_a^2}\Big(\frac{1}{n}\left(X^0\right)^TX^0  \Big)
				&e^{-\sigma_a^2}\frac{1}{n}\left(X^0\right)^TX^0p^0    \\
				e^{-\sigma_a^2}(p^0)^T\Big(\frac{1}{n}\left(X^0\right)^TX^0\Big)  & Y^TY/n
			\end{bmatrix}\\
			&\hspace{5mm}+ 	\begin{bmatrix}
				\mathbb{V}(\sin(\varepsilon_1^a))I_2  
				&  \mathbb{V}(\sin(\varepsilon_1^a))\Big(\frac{1}{n}\sum\limits_{i=1}^{n}p_i\Big)   \\
				\mathbb{V}(\sin(\varepsilon_1^a))\Big(\frac{1}{n}\sum\limits_{i=1}^{n}p_i^T\Big)  & 0
			\end{bmatrix}+ O_p(1/\sqrt{n}).
		\end{align*}
		For $Y^TY/n$, by   \eqref{trigono_2d_2}, Lemmas \ref{lem_moment_cos_sin} and \ref{lem_sqrtm}, we have
		\begin{align*}
			\frac{1}{n}Y^TY =& \frac{1}{n}\Big((p^0)^T\left(X^0\right)^TX^0p^0 + (p^0)^T\left(X^0\right)^T W + W^TX^0p^0 + W^T W\Big)\\
			=&\frac{1}{n}(p^0)^T\left(X^0\right)^TX^0p^0 + \frac{1}{n} W^T W + O_p(1/\sqrt{n})\\
			=& \frac{1}{n}(p^0)^T\left(X^0\right)^TX^0p^0 + \frac{1}{n}\sum_{i=1}^{n}\Big(\mathbb{V}(\cos(\varepsilon_i^a))(p^0)^Th_i^0(h_i^0)^Tp^0 + \mathbb{V}(\sin(\varepsilon_i^a))p_i^T\big(I_2 - h_i^0(h_i^0)^T\big)p_i\Big) + O_p(1/\sqrt{n})\\
			=&e^{-\sigma_a^2}\frac{1}{n}(p^0)^T\left(X^0\right)^TX^0p^0 + \mathbb{V}(\sin(\varepsilon_1^a))\frac{1}{n}\sum_{i=1}^{n}p_i^Tp_i + O_p(1/\sqrt{n}).
		\end{align*}
		Therefore, we have
		\begin{equation*}
			Q_n = e^{-\sigma_a^2}\frac{1}{n}\begin{bmatrix}
				\left(X^0\right)^TX^0 & \left(X^0\right)^TX^0p^0  \\
				(p^0)^T\left(X^0\right)^TX^0 & (p^0)^T\left(X^0\right)^TX^0p^0 
			\end{bmatrix} + \mathbb{V}(\sin(\varepsilon_1^a))S_n + O_p(1/\sqrt{n}).
		\end{equation*}
		By Proposition \ref{prop_noise_free_gram}, we have  $\lim_{n\to \infty}Q_n$ exists. 
		Moreover, by the similar arguments used in the proof of Lemma \ref{lem_converge_M}, under Assumptions \ref{assum_coordinates_2d}-\ref{assum_distribution}, we can derive that   $\lim_{n \to \infty}S_n$ exists. Thus, we denote $Q_\infty \eq \lim_{n\to \infty}Q_n$ and $S_{\infty} \eq \lim_{n \to \infty}S_n$, and obtain that
		\begin{equation*}
			Q_{\infty} \eq \lim_{n\to \infty}Q_n= e^{-\sigma_a^2}\lim_{n\to \infty}\frac{1}{n}\begin{bmatrix}
				\left(X^0\right)^TX^0 & \left(X^0\right)^TX^0p^0  \\
				(p^0)^T\left(X^0\right)^TX^0 & (p^0)^T\left(X^0\right)^TX^0p^0 
			\end{bmatrix} + \mathbb{V}(\sin(\varepsilon_1^a))S_{\infty}.
		\end{equation*}
		Notice that
		\begin{equation*}
			\lim_{n\to \infty}\frac{1}{n}\begin{bmatrix}
				\left(X^0\right)^TX^0 & \left(X^0\right)^TX^0p^0  \\
				(p^0)^T\left(X^0\right)^TX^0 & (p^0)^T\left(X^0\right)^TX^0p^0 
			\end{bmatrix}
		\end{equation*}
		is positive semi-definite and is singular since the columns are linearly dependent.
		By Lemma \ref{lem_eigen}, we have
		\begin{equation*}
			\lambda_{\rm max}(Q_{\infty}^{-1}\mathbb{V}(\sin(\varepsilon_1^a))S_\infty) = 1.
		\end{equation*}
		Note that $Q_n-Q_\infty = O_p(1/\sqrt{n})$ and $S_n-S_\infty = O_p(1/\sqrt{n})$, and $\lambda_{\rm max}(Q_n^{-1}S_n)$ is a continuous function of $Q_n$ and $S_n$.
		Thus, we have
		\begin{equation*}
			\lambda_{\rm max}(Q_n^{-1}S_n)-\lambda_{\rm max}(Q_\infty^{-1}S_\infty) = O_p(1/\sqrt{n})
		\end{equation*}
		and further
		\begin{equation*}
			\widehat{v}^a_n = \frac{1}{\lambda_{\rm max}(Q_n^{-1}S_n)} = \frac{1}{\lambda_{\rm max}(Q_\infty^{-1}S_\infty)} + O_p(1/\sqrt{n}) = \mathbb{V}(\sin(\varepsilon_1^a)) + O_p(1/\sqrt{n}).
		\end{equation*}
		This completes the proof.



		\subsection{Proof of Lemma \ref{lem_uniq_3d}}
		\label{proof_lem_3d}
		It is straightforward by Assumption \ref{assum_projection}   that
		\begin{equation}
			\label{expect_ml_3d}
			\begin{split}
				&\lim_{n \to \infty}\frac{1}{n}\sum_{i=1}^n \Big(f_{i}(p)-f_{i}(p^0)\Big)^T\Big(f_{i}(p)-f_{i}(p^0)\Big)  \\
				=& \sigma_a^{-2}\mathbb{E}_\mu   \left(\arctan\left(\frac{\tilde{y}-y}{\tilde{x}-x}\right)-\arctan\left(\frac{\tilde{y}-y^0}{\tilde{x}-x^0}\right)\right)^2  \\
				&+\sigma_e^{-2}\mathbb{E}_\mu   \left(\arctan\left(\frac{\tilde{z}-z}{\sqrt{(\tilde{x}-x)^2+(\tilde{y}-y)^2}}\right)-\arctan\left(\frac{\tilde{z}-z^0}{\sqrt{(\tilde{x}-x^0)^2+(\tilde{y}-y^0)^2}}\right)\right)^2  ,
			\end{split}
		\end{equation}
		where $\mathbb{E}_\mu$ is taken over $\tilde{p}=[\tilde{x},~\tilde{y},~\tilde{z}]^T$ with respect to $\mu$. 
		Notice that 
		\begin{align*}
			&\lim_{n \to \infty}\frac{1}{n}\sum_{i=1}^n\Big(f_{i}(p)-f_{i}(p^0)\Big)^T\Big(f_{i}(p)-f_{i}(p^0)\Big) \geq 0,~\text{for any}~p\in \mathbb{R}^3 \\
			&\lim_{n \to \infty}\frac{1}{n}\sum_{i=1}^n\Big(f_{i}(p)-f_{i}(p^0)\Big)^T\Big(f_{i}(p)-f_{i}(p^0)\Big)=0.
		\end{align*}
		Thus, the loss function on the right hand side of  \eqref{expect_ml_3d} achieves its minimum at $p=p^0$. In the following, for completing the proof, it suffices to prove that $p^0$ is its unique minimum.

		We have the conclusion that
		\begin{equation}
			\label{E_arctanyx}
			\mathbb{E}_\mu   \left(\arctan\left(\frac{\tilde{y}-y}{\tilde{x}-x}\right)-\arctan\left(\frac{\tilde{y}-y^0}{\tilde{x}-x^0}\right)\right)^2  
		\end{equation}
		reaches its unique minimum at $p_{1:2}=p^0_{1:2}$ by Lemma \ref{lem_uniq_2d} for the 2-D scenario, where $p_{1:2}$ and $p^0_{1:2}$ represent the first two coordinates of $p$ and $p^0$, respectively.  
		Therefore,  it suffices to verify that
		\begin{equation*}
			\mathbb{E}_\mu \left(\arctan\left(\frac{\tilde{z}-z}{\sqrt{(\tilde{x}-x)^2+(\tilde{y}-y)^2}}\right)-\arctan\left(\frac{\tilde{z}-z^0}{\sqrt{(\tilde{x}-x^0)^2+(\tilde{y}-y^0)^2}}\right)\right)^2 
		\end{equation*}
		is uniquely minimized at $p= p^0$. 
		Define $$\mathcal{P}'_p \eq \left\{\tilde{p}\in \mathcal{P}~\Bigg|~\arctan\left(\frac{\tilde{z}-z}{\sqrt{(\tilde{x}-x)^2+(\tilde{y}-y)^2}}\right)=\arctan\left(\frac{\tilde{z}-z^0}{\sqrt{(\tilde{x}-x^0)^2+(\tilde{y}-y^0)^2}}\right),~ p_{1:2}=p^0_{1:2}\right\}.$$ Suppose that there exists a $p \neq p^0$ such that $p_{1:2}=p^0_{1:2}$ and $\mathbb{E}_\mu \left(\arctan\left(\frac{\tilde{z}-z}{\sqrt{(\tilde{x}-x)^2+(\tilde{y}-y)^2}}\right)-\arctan\left(\frac{\tilde{z}-z^0}{\sqrt{(\tilde{x}-x^0)^2+(\tilde{y}-y^0)^2}}\right)\right)^2 =0$. Then $\mu(\mathcal{P}'_p)=1$.
		Note that
		$
		[\tilde{x}-x, ~ \tilde{y}-y]^T = \tilde{p}_{1:2}-p_{1:2}=\tilde{p}_{1:2}-p^0_{1:2} = [\tilde{x}-x^0, ~ \tilde{y}-y^0]^T.
		$
		Thus, $\arctan\left(\frac{\tilde{z}-z}{\sqrt{(\tilde{x}-x)^2+(\tilde{y}-y)^2}}\right)=\arctan\left(\frac{\tilde{z}-z^0}{\sqrt{(\tilde{x}-x^0)^2+(\tilde{y}-y^0)^2}}\right)$ is equivalent to $\tilde{z}-z = \tilde{z}-z^0$. This derives that $z=z^0$ and further $p=p^0$.

		% Denote $\tilde{r}^0 = \sqrt{(\tilde{x}-x^0)^2+(\tilde{y}-y^0)^2}$ and $\tilde{d}^0=\sqrt{(\tilde{x}-x^0)^2+(\tilde{y}-y^0)^2+(\tilde{z}-z^0)^2}$. 
		The existence of the limiting matrix of $\frac{1}{n}\sum_{i=1}^n\big(\nabla f_{i}(p^0)\big)^T \nabla f_{i}(p^0)$ can be derived similar to the proof of Lemma \ref{lem_converge_M} for the 2-D scenario. 
		Further, it is straightforward that 
		\begin{align*}
			M^0&=\lim_{n\to \infty}\frac{1}{n}\sum_{i=1}^n\big(\nabla f_{i}(p^0)\big)^T \nabla f_{i}(p^0)\\
			&= \mathbb{E}_\mu \left( \frac{\sigma_a^{-2}}{\|\tilde{p}_{1:2}-p^0_{1:2}\|^4}\begin{bmatrix}
				\tilde{y}-y^0\\ -\tilde{x}+x^0\\ 0
			\end{bmatrix}[\tilde{y}-y^0,~ -\tilde{x}+x^0,~0] \right. \\
			& \hspace{2mm}\left. + \frac{\sigma_e^{-2}}{\|\tilde{p}-p^0\|^4\|\tilde{p}_{1:2}-p^0_{1:2}\|^2}\begin{bmatrix}
				(\tilde{x}-x^0)(\tilde{z}-z^0) \\ (\tilde{y}-y^0)(\tilde{z}-z^0)\\ -(\tilde{x}-x^0)^2-(\tilde{y}-y^0)^2
			\end{bmatrix}[(\tilde{x}-x^0)(\tilde{z}-z^0),~(\tilde{y}-y^0)(\tilde{z}-z^0),~-(\tilde{x}-x^0)^2-(\tilde{y}-y^0)^2] \right),
		\end{align*}
		where $\mathbb{E}_\mu$ is taken over $\tilde{p}=[\tilde{x},~\tilde{y},~\tilde{z}]^T$ with respect to $\mu$. Suppose there exists some $\theta = [\theta_1, ~\theta_2,~\theta_3]^T\in \mathbb{R}^3,~ \theta \neq 0 $ such that $\theta^T \lim_{n \to \infty}\frac{1}{n}\big(\nabla f_{i}(p^0)\big)^T \nabla f_{i}(p^0) \theta = 0$. Then there holds that 
		\begin{align}
			\label{M_3d_quadra_1}
			&\mathbb{E}_\mu \left( \theta^T \begin{bmatrix} \tilde{y}-y^0\\ -\tilde{x}+x^0\\ 0
			\end{bmatrix}[\tilde{y}-y^0,~-\tilde{x}+x^0,~0]\theta \right)=0,\\ \label{M_3d_quadra_2}
			&\mathbb{E}_\mu\left(\theta^T \begin{bmatrix}
				(\tilde{x}-x^0)(\tilde{z}-z^0) \\ (\tilde{y}-y^0)(\tilde{z}-z^0)\\ -(\tilde{x}-x^0)^2-(\tilde{y}-y^0)^2
			\end{bmatrix}[(\tilde{x}-x^0)(\tilde{z}-z^0),~(\tilde{y}-y^0)(\tilde{z}-z^0),~-(\tilde{x}-x^0)^2-(\tilde{y}-y^0)^2]\theta \right) = 0.
		\end{align}

		By Lemma \ref{lem_invertM_2d}, it is straightforward to derive that \eqref{M_3d_quadra_1} is equivalent to $\theta_1=\theta_2=0$. Thus, \eqref{M_3d_quadra_2} is equivalent to
		\begin{equation*}
			\mathbb{E}_\mu\left(\big[(\tilde{x}-x^0)^2+(\tilde{y}-y^0)^2\big](\theta_3)^2 \right) = 0.
		\end{equation*}
		Thus, we obtain $\theta_3=0$ as well, which contradicts the supposition $\theta \neq 0$. Therefore, $M^0$ is positive definite.

		This completes the proof.

		\subsection{Proof of Theorem \ref{thm_ub_z}}
		\label{proof_thm_ub_z}
		It follows from \eqref{gg} that
		\begin{equation*}
			\widehat{z}_n^{\rm UB} = \left((\Phi^0)^T\Phi^0\right)^{-1}(\Phi^0)^T(\Phi^0 z^0 + \omega) = z^0 + \left(\frac{1}{n}(\Phi^0)^T\Phi^0\right)^{-1}\Big(\frac{1}{n}(\Phi^0)^T\omega\Big).
		\end{equation*}
		Under Assumption \ref{assum_coordinates_3d}, each element of the  noise  sequence of the model \eqref{gg} is zero mean and its variance  
		\begin{align*}
			&\mathbb{E}\Big(-\big(\cos(\varepsilon_i^e)-e^{-\sigma_e^2/2}\big)\cos(e_i^0)z^0+\sin(\varepsilon_i^e)\big(d_i^0+\sin(e_i^0)z^0\big)\Big)^2\\
			&=\mathbb{E}\Big(\big(\cos(\varepsilon_i^e)-e^{-\sigma_e^2/2}\big)^2\cos^2(e_i^0)(z^0)^2\Big) + \mathbb{E}\Big(\sin^2(\varepsilon_i^e)\big(d_i^0+\sin(e_i^0)z^0\big)^2\Big)\\
			&\leq \mathbb{V}(\cos(\varepsilon_i^e))(z^0)^2 + 2\mathbb{V}(\sin(\varepsilon_i^e))\big((d_i^0)^2 + (z^0)^2\big),
		\end{align*}
		is uniformly bounded by Lemma \ref{lem_moment_cos_sin}. 
		Thus, by Lemma \ref{lem_sqrtm}, we have
		\begin{equation}
			\label{phiomega}
			\frac{1}{n}(\Phi^0)^T\omega = O_p(1/\sqrt{n}).
		\end{equation}
		Additionally, combining with Proposition \ref{prop3} one derives that
		\begin{equation*}
			\widehat{z}_n^{\rm UB} - z^0  = O(1)O_p(1/\sqrt{n}) = O_p(1/\sqrt{n}).
		\end{equation*}
		This completes the proof.



		\subsection{Proof of Theorem \ref{BELS_3D_case}}
		\label{proof_BELS_3D_case}
		It follows from \eqref{zphi} and \eqref{gg} that
		\begin{equation*}
			\Delta\Phi \eq \Phi - \Phi^0 
			=\begin{bmatrix}
				-\cos(e_1)+e^{-\sigma_e^2/2}\cos(e_1^0)\\
				-\cos(e_2)+e^{-\sigma_e^2/2}\cos(e_2^0)\\
				\vdots\\
				-\cos(e_n)+e^{-\sigma_e^2/2}\cos(e_n^0)
			\end{bmatrix}
			= \begin{bmatrix}
				-(\cos(\varepsilon_1^e)-e^{-\sigma_e^2/2})\cos(e_1^0) + \sin(\varepsilon_1^e)\sin(e_1^0)	\\
				-(\cos(\varepsilon_2^e)-e^{-\sigma_e^2/2})\cos(e_2^0) + \sin(\varepsilon_2^e)\sin(e_2^0)	\\
				\vdots	\\
				-(\cos(\varepsilon_n^e)-e^{-\sigma_e^2/2})\cos(e_n^0) + \sin(\varepsilon_n^e)\sin(e_n^0)
			\end{bmatrix}.
		\end{equation*}
		Then we have
		\begin{equation*}
			\frac{1}{n}\Phi^T\Phi = \frac{1}{n}(\Phi^0)^T\Phi^0 + \frac{2}{n}(\Phi^0)^T\Delta\Phi + \frac{1}{n}(\Delta\Phi)^T\Delta\Phi.
		\end{equation*}
		For the cross term, by the similar argument as \eqref{ecos_esin}, we have
		\begin{align*}
			\frac{2}{n}(\Phi^0)^T\Delta\Phi 
			=&e^{-\sigma_e^2/2}\frac{2}{n}\sum_{i=1}^{n}\big(\cos(\varepsilon_i^e)-e^{-\sigma_e^2/2}\big)\cos^2(e_i^0) - e^{-\sigma_e^2/2}\frac{1}{n}\sum_{i=1}^{n}\sin(\varepsilon_i^e)\sin(e_i^0)\cos(e_i^0)\\
			=&O_p(1/\sqrt{n}).
		\end{align*}
		For the quadratic term, we have
		\begin{align*}
			\frac{1}{n}(\Delta\Phi)^T\Delta\Phi&= \frac{1}{n}\sum_{i=1}^{n}(\cos(\varepsilon_i^e)-e^{-\sigma_e^2/2})^2\cos^2(e_i^0)	+\frac{1}{n}\sum_{i=1}^{n} \sin^2(\varepsilon_i^e)\sin^2(e_i^0) \\
			&\hspace{5mm}- \frac{2}{n}\sum_{i=1}^{n}\sin(\varepsilon_i^e)(\cos(\varepsilon_i^e)-e^{-\sigma_e^2/2})\sin(e_i^0)\cos(e_i^0).
		\end{align*}
		By the similar argument as \eqref{vcos_vsin}, we derive
		\begin{align*}
			\frac{1}{n}(\Delta\Phi)^T\Delta\Phi& = \frac{1}{n}\sum_{i=1}^{n}\mathbb{E}\big((\cos(\varepsilon_i^e)-e^{-\sigma_e^2/2})^2\cos^2(e_i^0)\big) + \frac{1}{n}\sum_{i=1}^{n} \mathbb{E}\left(\sin^2(\varepsilon_i^e)\right)\sin^2(e_i^0) + O_p(1/\sqrt{n})\\
			&= \frac{1}{n}\sum_{i=1}^{n}\mathbb{V}(\cos(\varepsilon_i^e))\cos^2(e_i^0) + \frac{1}{n}\sum_{i=1}^{n}\mathbb{V}(\sin(\varepsilon_i^e))(1-\cos^2(e_i^0)) + O_p(1/\sqrt{n})\\
			&= e^{\sigma_e^2}\big(\mathbb{V}(\cos(\varepsilon_i^e))-\mathbb{V}(\sin(\varepsilon_i^e))\big)\Big(\frac{1}{n}(\Phi^0)^T\Phi^0 \Big)+ \mathbb{V}(\sin(\varepsilon_1^e)) + O_p(1/\sqrt{n}).
		\end{align*}
		Thus, there holds that
		\begin{equation}
			\label{hatphihatphi}
			\frac{1}{n}\Phi^T\Phi = \left(1+e^{\sigma_e^2}\mathbb{V}(\cos(\varepsilon_i^e)) - e^{\sigma_e^2}\mathbb{V}(\sin(\varepsilon_i^e))\right)\Big(\frac{1}{n}(\Phi^0)^T\Phi^0 \Big) + \mathbb{V}(\sin(\varepsilon_1^e)) + O_p(1/\sqrt{n}).
		\end{equation}

		Additionally, $\Phi^T\widehat{\Gamma}/n$ can be decomposed as
		\begin{equation*}
			\frac{1}{n}\Phi^T\widehat{\Gamma} = \frac{1}{n}\Phi^T\Gamma + \frac{1}{n}\Phi^T(\widehat{\Gamma}-\Gamma)= \frac{1}{n}\Phi^T\Gamma + \frac{1}{n}\sum_{i=1}^{n}\cos(e_i)(\widehat{r}_i-r_i^0)\sin(e_i).
		\end{equation*}
		Since $\widehat{r_i}-r_i^0 = O_p(1/\sqrt{n})$ for all $i=1,...,n$ by \eqref{rr}, we have $\Phi^T\widehat{\Gamma}/n-\Phi^T\Gamma/n = O_p(1/\sqrt{n})$.
		By the similar argument as used for \eqref{ecos_esin} and \eqref{vcos_vsin}, we have
		\begin{align*}
			\frac{1}{n}\Phi^T\Gamma =& \frac{1}{n}(\Phi^0)^T\Gamma + \frac{1}{n}(\Delta\Phi)^T\Gamma\\
			=&\frac{1}{n}(\Phi^0)^T\Gamma + \frac{1}{n}(\Delta\Phi)^T\Phi^0 z^0+ \frac{1}{n}(\Delta\Phi)^T\omega\\
			=&\frac{1}{n}(\Phi^0)^T\Gamma+ \frac{1}{n}(\Delta\Phi)^T\omega + O_p(1/\sqrt{n}),
		\end{align*}
		where
		\begin{align*}
			\frac{1}{n}(\Delta\Phi)^T\omega =& \frac{1}{n}\sum_{i=1}^{n}\big(\cos(\varepsilon_i^e)- e^{-\sigma_e^2/2}\big)^2\cos^2(e_i^0)z^0 + \frac{1}{n}\sum_{i=1}^{n}\sin^2(\varepsilon_i^e)\big(\sin(e_i^0)d_i^0+\sin^2(e_i^0)z^0\big)\\
			&-\frac{1}{n}\sum_{i=1}^{n}\sin(\varepsilon_i^e)\big(\cos(\varepsilon_i^e)-e^{-\sigma_e^2/2}\big)\big(\sin(e_i^0)\cos(e_i^0)z^0+\cos(e_i^0)(d_i^0+\sin(e_i^0)z^0)\big)\\
			=&\frac{1}{n}\sum_{i=1}^{n}\mathbb{V}(\cos(\varepsilon_i^e))\cos^2(e_i^0)z^0 + \frac{1}{n}\sum_{i=1}^{n}\mathbb{V}(\sin(\varepsilon_i^e))(z_i-\cos^2(e_i^0)z^0) + O_p(1/\sqrt{n})\\
			=& \frac{1}{n}\sum_{i=1}^{n}\mathbb{V}(\cos(\varepsilon_i^e))\cos^2(e_i^0)z^0 + \frac{1}{n}\sum_{i=1}^{n}\mathbb{V}(\sin(\varepsilon_i^e))(z_i-\cos^2(e_i^0)z^0) + O_p(1/\sqrt{n})\\
			=&e^{\sigma_e^2}\left(\mathbb{V}(\cos(\varepsilon_1^e))-\mathbb{V}(\sin(\varepsilon_1^e)\right)\Big(\frac{1}{n}(\Phi^0)^T\Phi^0 \Big)z^0 + \mathbb{V}(\sin(\varepsilon_1^e))\Big(\frac{1}{n}\sum_{i=1}^{n}z_i\Big) + O_p(1/\sqrt{n}).
		\end{align*}
		Notice that
		\begin{equation*}
			\frac{1}{n}(\Phi^0)^T\Gamma = \frac{1}{n}(\Phi^0)^T\Phi^0 z^0 + \frac{1}{n}(\Phi^0)^T\omega = \frac{1}{n}(\Phi^0)^T\Phi^0 z^0 + O_p(1/\sqrt{n}).
		\end{equation*}
		We obtain
		\begin{equation}
			\label{hatphihatbeta}
			\frac{1}{n}\Phi^T\widehat{\Gamma} = \left(1+e^{\sigma_e^2}\mathbb{V}(\cos(\varepsilon_1^a)) - e^{\sigma_e^2}\mathbb{V}(\sin(\varepsilon_1^e))\right)
			\Big(\frac{1}{n}(\Phi^0)^T\Phi^0 z^0\Big)
			+\mathbb{V}(\sin(\varepsilon_1^e))\Big(\frac{1}{n}\sum_{i=1}^{n}z_i\Big) + O_p(1/\sqrt{n}).
		\end{equation}
		Therefore, combining \eqref{hatphihatphi} with \eqref{hatphihatbeta} derives that
		\begin{align*}
			\widehat{z}_n^{\rm BE} = & \left(\frac{1}{n}\Phi^T\Phi - \mathbb{V}(\sin(\varepsilon_1^e))\right)^{-1}\left(\frac{1}{n}\Phi^T\widehat{\Gamma} - \mathbb{V}(\sin(\varepsilon_1^e))\frac{1}{n}\sum_{i=1}^{n}z_i\right)\\
			=& \left(\frac{K'}{n}(\Phi^0)^T\Phi^0 + O_p(1/\sqrt{n})\right)^{-1}\left(\frac{K'}{n} (\Phi^0)^T\Phi^0 z^0 + O_p(1/\sqrt{n})\right)\\
			=&z^0 + O_p(1/\sqrt{n}),
		\end{align*}
		where $K' = 1+e^{\sigma_e^2}\mathbb{V}(\cos(\varepsilon_1^e)) - e^{\sigma_e^2}\mathbb{V}(\sin(\varepsilon_1^e))=e^{-\sigma_e^2}$ is a non-zero constant by Lemma \ref{lem_moment_cos_sin}.
		Consequently, the BELS estimator $\widehat{z}_n^{\rm BE}$ is $\sqrt{n}$-consistent.

		This completes the proof.

		\subsection{Proof of Theorem \ref{thm_var_3d}}
		\label{proof_thm_var_3d}

		It follows from \eqref{hatphihatphi} and \eqref{hatphihatbeta} that
		\begin{align*}
			R_n
			&=   \begin{bmatrix}
				\Phi^T\Phi/n & \Phi^T\widehat{\Gamma}/n\\
				\widehat{\Gamma}^T\Phi/n & \widehat{\Gamma}^T\widehat{\Gamma}/n
			\end{bmatrix} = \begin{bmatrix}
				e^{-\sigma_e^2}(\Phi^0)^T\Phi^0/n & e^{-\sigma_e^2}(\Phi^0)^T\Phi^0 z^0/n\\
				e^{-\sigma_e^2}(\Phi^0)^T\Phi^0 z^0/n &\widehat{\Gamma}^T\widehat{\Gamma}/n
			\end{bmatrix}\\
			&\hspace{40mm}+\begin{bmatrix}
				\mathbb{V}(\sin(\varepsilon_1^e)) & \mathbb{V}(\sin(\varepsilon_1^e))\Big(\frac{1}{n}\sum_{i=1}^{n}z_i\Big)\\
				\mathbb{V}(\sin(\varepsilon_1^e))\Big(\frac{1}{n}\sum_{i=1}^{n}z_i\Big) &0
			\end{bmatrix}+ O_p(1/\sqrt{n}).
		\end{align*}

		The term $\widehat{\Gamma}^T\widehat{\Gamma}/n$ can be decomposed as
		\begin{align*}
			\frac{1}{n}\widehat{\Gamma}^T\widehat{\Gamma} &= \frac{1}{n}(\Gamma+\widehat{\Gamma}-\Gamma)^T(\Gamma+\widehat{\Gamma}-\Gamma)\\
			&=\frac{1}{n}\Gamma^T\Gamma + \frac{2}{n}\Gamma^T(\widehat{\Gamma}-\Gamma) + \frac{1}{n}\|\widehat{\Gamma}-\Gamma\|^2.
		\end{align*}
		For the last addend, we have
		\begin{equation*}
			\frac{1}{n}\|\widehat{\Gamma}-\Gamma\|^2 =  \frac{1}{n}\sum_{i=1}^n\sin^2(e_i)(\widehat{r_i}-r_i^0)^2 \leq \frac{1}{n}\sum_{i=1}^n(\widehat{r_i}-r_i^0)^2 = O_p(1/n)
		\end{equation*}
		following from $\widehat{r_i}-r_i^0 = O_p(1/\sqrt{n})$.

		For the term $2\Gamma^T(\widehat{\Gamma}-\Gamma)/n$, we have
		\begin{equation*}
			\frac{2}{n}\Gamma^T(\widehat{\Gamma}-\Gamma) = \frac{2}{n}\sum_{i=1}^n\big(\sin(e_i)r_i+\cos(e_i)z_i\big)\sin(e_i)(\widehat{r_i}-r_i^0)= O_p(1/\sqrt{n})
		\end{equation*} 
		by the uniform boundedness of $\{(\sin(e_i)r_i^0+\cos(e_i)z_i)\sin(e_i),~i=1,...,n\}$
		under Assumption \ref{assum_coordinates_3d}.

		For the term $\Gamma^T\Gamma/n$, there holds that
		\begin{equation*}
			\frac{1}{n}\Gamma^T\Gamma = \frac{1}{n}(\Phi^0)^T\Phi^0 (z^0)^2 + \frac{1}{n} z^0(\Phi^0)^T\omega + \frac{1}{n}\omega^T\omega.
		\end{equation*}
		By \eqref{phiomega}, we have
		\begin{equation*}
			\frac{2}{n}z^0 (\Phi^0)^T\omega = O_p(1/\sqrt{n}).
		\end{equation*}
		For the addend $\omega^T\omega/n$, we have
		\begin{align*}
			\frac{1}{n}\omega^T\omega& = \frac{1}{n}\sum_{i=1}^n\left(-\big(\cos(\varepsilon_i^e)-e^{-\sigma_e^2/2}\big)\cos(e_i^0)z^0+\sin(\varepsilon_i^e)(d_i^0+\sin(e_i^0)z^0)\right)^2\\
			&= \frac{1}{n}\sum_{i=1}^n\Big((\cos(\varepsilon_i^e)-e^{-\sigma_e^2/2})^2\cos^2(e_i^0)(z^0)^2 + \sin^2(\varepsilon_i^e)\big(d_i^0+\sin(e_i^0)z^0\big)^2 \\
			&\hspace{15mm}- 2\big(\cos(\varepsilon_i^e)-e^{-\sigma_e^2/2}\big)\cos(e_i^0)z^0\sin(\varepsilon_i^e)\big(d_i^0+\sin(e_i^0)z^0\big)\Big).
		\end{align*}
		Note that
		\begin{align*}
			(d_i^0 + \sin(e_i^0)z^0)^2& = (d_i^0)^2 + 2d_i^0\sin(e_i^0)z^0 + \sin^2(e_i^0)(z^0)^2\\
			&= (r_i^0)^2+(z_i-z^0)^2 + 2(z_i-z^0) z^0+ (z^0)^2-\cos^2(e_i^0)(z^0)^2\\
			& = (r_i^0)^2 + z_i^2 + (z^0)^2 - 2z_iz^0 - (z^0)^2 + 2z_iz^0-\cos^2(e_i^0)(z^0)^2\\
			& = \widehat{r_i}^2 +z_i^2 -\cos^2(e_i^0)(z^0)^2 + O_p(1/n).
		\end{align*}
		Under Assumption \ref{assum_coordinates_3d}, by Lemma \ref{lem_moment_cos_sin}  we derive
		\begin{align*}
			&\frac{1}{n}\sum_{i=1}^n (\cos(\varepsilon_i^e)-e^{-\sigma_e^2/2})^2\cos^2(e_i^0)(z^0)^2 = e^{\sigma_e^2}\mathbb{V}(\cos(\varepsilon_1^e))\Big(\frac{1}{n}(\Phi^0)^T\Phi^0\Big) (z^0)^2 + O_p(1/\sqrt{n}),\\
			&\frac{1}{n}\sum_{i=1}^n \sin^2(\varepsilon_i^e)(d_i^0+\sin(e_i^0)z^0)^2 = \mathbb{V}(\sin(\varepsilon_i^e))\frac{1}{n}\sum_{i=1}^n \left(\widehat{r_i}^2+z_i^2\right) - e^{\sigma_e^2}\mathbb{V}(\sin(\varepsilon_i^e))\Big(\frac{1}{n}(\Phi^0)^T\Phi^0 \Big)(z^0)^2 + O_p(1/\sqrt{n}),\\
			&\frac{1}{n}\sum_{i=1}^n 2(\cos(\varepsilon_i^e)-e^{-\sigma_e^2/2})\cos(e_i^0)z^0\sin(\varepsilon_i^e)(d_i^0-\sin(e_i^0)z^0) = O_p(1/\sqrt{n}).
		\end{align*}
		Thus, we have
		\begin{equation*}
			\frac{1}{n}\widehat{\Gamma}^T\widehat{\Gamma} = e^{-\sigma_e^2}\frac{1}{n}(\Phi^0)^T\Phi^0 (z^0)^2 + \mathbb{V}(\sin(\varepsilon_i^e))\frac{1}{n}\sum_{i=1}^n \big(\widehat{r_i}^2+z_i^2\big) + O_p(1/\sqrt{n}).
		\end{equation*}
		Therefore, it holds that
		\begin{equation*}
			R_n = e^{-\sigma_e^2}\frac{1}{n}\begin{bmatrix}
				(\Phi^0)^T\Phi^0 & (\Phi^0)^T\Phi^0 z^0\\
				(\Phi^0)^T\Phi^0 z^0 & (\Phi^0)^T\Phi^0 (z^0)^2
			\end{bmatrix} + \mathbb{V}(\sin(\varepsilon_1^e))U_n + O_p(1/\sqrt{n}).
		\end{equation*}

		By the similar arguments as used in the proof of Theorem \ref{thm_var_2d}, we obtain that both the limits of  $R_n$ and $U_n$ exist. Thus, we denote their limits by $R_\infty \eq \lim_{n\to \infty}R_n$ and $U_\infty \eq \lim_{n \to \infty} U_n$. Then, there holds that
		\begin{equation*}
			R_\infty = e^{-\sigma_e^2}\lim_{n\to \infty}\frac{1}{n}\begin{bmatrix}
				(\Phi^0)^T\Phi^0 & (\Phi^0)^T\Phi^0 z^0\\
				(\Phi^0)^T\Phi^0 z^0 & (\Phi^0)^T\Phi^0 (z^0)^2
			\end{bmatrix} + \mathbb{V}(\sin(\varepsilon_1^e))U_\infty.
		\end{equation*}
		Notice that
		\begin{equation*}
			\lim_{n\to \infty} \frac{1}{n}\begin{bmatrix}
				(\Phi^0)^T\Phi^0 & (\Phi^0)^T\Phi^0 z^0\\
				(\Phi^0)^T\Phi^0 z^0 & (\Phi^0)^T\Phi^0 (z^0)^2
			\end{bmatrix}
		\end{equation*}
		is positive semi-definite and further is
		singular due to the linearly dependent  columns. By Lemma \ref{lem_eigen}, we have
		\begin{equation*}
			\lambda_{\rm max}(R_\infty^{-1}\mathbb{V}(\sin(\varepsilon_1^e))U_{\infty})=1.
		\end{equation*}
		By the similar argument in the proof of Theorem \ref{thm_var_2d}, we obtain
		\begin{equation*}
			\widehat{v}_n^e = \frac{1}{\lambda_{\rm max}(R_n^{-1}U_n)} = \frac{1}{\lambda_{\rm max}(R_\infty^{-1}U_{\infty})} + O_p(1/\sqrt{n}) = \mathbb{V}(\sin(\varepsilon_1^e)) + O_p(1/\sqrt{n}).
		\end{equation*}
		This completes the proof.

