		\begin{lem}\cite[Equation (5-73)]{Papoulis2002}
			\label{lem_moments_gaussian}
			Let $X$ be a Gaussian random variable with mean 0 and variance $\sigma^2$. Thus, for any $k=0,1,2,...$, there holds that
			\begin{equation*}
				\mathbb{E}X^{2k} = \frac{(2k)!}{2^k(k!)}\sigma^{2k}.
			\end{equation*}
		\end{lem}

		\begin{lem}
			\label{lem_moment_cos_sin}
			Let $X$ be a Gaussian random variable with mean zero and finite variance $\sigma^2$.
			Then there holds that
			\begin{subequations}
				\begin{align}
					&\mathbb{E}(\cos(X)) = e^{-\sigma^2/2},\\
					&\mathbb{E}(\sin(X)) = 0,\\
					&\mathbb{E}(\sin(X)\cos(X)) = 0,\\
					&\mathbb{V}(\cos(X)) = \frac{1}{2}(e^{-2\sigma^2} + 1 -2e^{-\sigma^2}),\\
					&\mathbb{V}(\sin(X)) = \frac{1}{2}(1-e^{-2\sigma^2}).\label{lm10-5}
				\end{align}
			\end{subequations}
			Moreover, the $4$-th moments of $\sin(X)$ and $\cos(X)$ are finite.
		\end{lem}

		\begin{proof}
			The Taylor series of $\cos(X)$ is given by
			\begin{equation*}
				\cos(X) = \sum_{k=0}^\infty\frac{(-1)^kX^{2k}}{(2k)!}
			\end{equation*}
			with convergence domain $(-\infty,\infty)$. Thus, by Lemma \ref{lem_moments_gaussian}, it holds that
			\begin{align*}
				\mathbb{E}(\cos(X))&=\mathbb{E}\left[\sum_{k=0}^\infty\frac{(-1)^kX^{2k}}{(2k)!}\right]\\
				&=\sum_{k=0}^\infty\frac{(-1)^k}{(2k)!}\frac{(2k)!}{2^k(k!)}\sigma^{2k}\\
				&=e^{-\sigma^2/2}.
			\end{align*}

			It is obvious that $\mathbb{E}(\sin(X)) = 0$ and $\mathbb{E}(\sin(X)\cos(X)) = 0$ since $\sin(\cdot)$ and $\sin(\cdot)\cos(\cdot)$ are odd functions and $\mathbb{E}X=0$.

			Next we derive the variance of $\cos(X)$ and $\sin(X)$. Notice that $2X$ is a Gaussian random variable with mean 0 and variance $4\sigma^2$, it holds that
			\begin{equation*}
				\mathbb{V}(\sin(X)) = \mathbb{E}(\sin^2(X)) = \mathbb{E}\left(\frac{1-\cos(2X)}{2}\right) = \frac{1}{2}(1-e^{-2\sigma^2}).
			\end{equation*}
			Moreover, it holds that
			\begin{equation*}
				\mathbb{V}(\cos(X)) = \mathbb{E}(\cos^2(X))-(\mathbb{E}(\cos(X)))^2 = 1-\mathbb{E}(\sin^2(X)) - e^{-\sigma^2} = \frac{1}{2}(e^{-2\sigma^2} + 1 -2e^{-\sigma^2}).
			\end{equation*}

			Notice that $\sin^4(X) = \cos(4X)/8-\cos(2X)/2+3/8$, and the mean of $\cos(2X)$ and $\cos(4X)$ exist, thus $\mathbb{E}(\sin^4(X))$ exists and is finite. The similar result holds for $\cos^4(X)$.
		\end{proof}

