\end{figure}

\begin{theorem}[Memory Dependence in Non-Augmented Neural DDEs \cite{KuehnKuntz2025}] \label{cekk_th:memory}
\index{Universal Approximation} Let $\Phi_\theta \in \textup{NDDE}_{\tau,\textup{N}}^k(\R^d,\R^q)$, $k\geq 1$, be a non-augmented neural DDE with $m = \max\{d,q\}$ and delay $\tau\geq0$. Let the underlying vector field $F$ be globally Lipschitz continuous with respect to the second variable with Lipschitz constant $K$. Fix some constants $w, \tilde w \in (0,\infty)$ and $A \geq 0$. Then the following assertions hold:
\begin{enumerate}[label=(\alph*), font=\normalfont]
\item There exists a continuous function $\tau_0((0,\infty),[0,T])$ with $K\tau_0(K)e<1$ for $K\in(0,\infty)$, such that if $\tau\in[0,\tau_0(K))$, the class of neural DDEs $\textup{NDDE}^k_{\tau,\textup{N}}(\R^d,\R^q)$ with $\vert\vert{F(t,0)}\vert\vert_\infty \leq A$ for all $t\in [0,T]$ and weight matrices $W, \widetilde{W}$ fulfilling $\vert\vert W \vert\vert_\infty \leq w$, $\vert\vert\widetilde W\vert\vert_\infty \leq \tilde w$, does not have the universal approximation property with respect to the space $C^j(\R^d,\R^q)$,$j\geq 0$.
\item Let $\Psi\in C^k_b(\R^d,\R^q)$, $k\geq 1$ with global Lipschitz constant $K_\Psi$. Then if
\begin{equation*}
	K\tau \geq 2\left(1+\frac{K_\Psi}{w \tilde w}\right),
\end{equation*}
the map $\Psi$ can be represented by a neural DDE $\Phi_\theta\in\textup{NDDE}^k_{\tau,\textup{N}}(\R^d,\R^q)$ with weight matrices $W, \widetilde{W}$ with $\vert\vert{W}\vert\vert_\infty = w$, $\vert\vert\widetilde W\vert\vert_\infty = \tilde w$, delay $\tau$ and global Lipschitz constant $K$ in the second variable.
\end{enumerate}
\end{theorem}

From part (a), it follows by deleting arbitrary components of the vector field that for all  $m \leq \max\{d,q\}$, neural DDEs cannot have the universal approximation property. The statement from part~(b) generalizes to all $m\geq \max\{d,q\}$ by adding additional zero components to the vector field. For $m \geq d+q$, it follows analogously to Theorem~\ref{cekk_th:universalembedding}, that also neural DDEs $\Phi_\theta\in\textup{NDDE}^k_{\tau,\textup{A}}$ have the universal embedding property \index{Universal Embedding} with respect to the space $C^k(\R^d,\R^q)$ \cite{KuehnKuntz2025}. All results obtained for the memory dependence of neural DDEs are visualized in Figure \ref{cekk_fig:NDDEtheorem}. In summary, Theorem~\ref{cekk_th:memory} provides a mathematically precise statement regarding the role of memory in network architectures, i.e., how increasing memory enables universal approximation and universal embedding.




