\begin{table}[htbp]
\centering
\caption{Comparison of Twin Prime Counting Function Approximations (Corrected Model)}
\label{tab:comparison}
\begin{tabular}{@{}lrrrrr@{}}
\toprule
$x$ & $\pi_2(x)$ (True) & $\pi_{2,\text{HL}}(x)$ & Rel. Err. (HL) & $\pi_{2,\text{approx}}(x)$ & Rel. Err. (This work) \\
\midrule
$10^4$ & 205 & 214 & 4.39\% & 209 & 1.95\% \\
$10^5$ & 1,224 & 1,249 & 2.04\% & 1,227 & 0.25\% \\
$10^6$ & 8,169 & 8,167 & -0.02\% & 8,164 & -0.06\% \\
$10^7$ & 58,980 & 58,754 & -0.38\% & 58,782 & -0.34\% \\
