\subsubsection{Stage 1 -- Local Leader Election}
Stage 1 concerns with electing local leaders among $k$ agents. Stage 1 differs for singleton and non-singleton agents.  Singleton agents run {\em Singleton\_Election} and non-singleton agents run {\em Non\_Singleton\_Election}. % to become local leaders. 
We describe them separately below.

\vspace{2mm}
\noindent{\bf Singleton Election.}
The pseudocode of {\em Singleton\_Election} is in Algorithm \ref{algorithm:local_electionk}. Let $r_u$  be the agent positioned at node $u$; we write $\psi(u)=r_u$. % to denote an agent that belongs to $u$. %Let $N_{occ}(u)$ be the neighbors the neighbors with agents positioned. 
For $\psi(u)$ to eligible to become a local leader, % each node in $N_{occ}(u)$ 
either all neighbors in $N(u)$ have to be empty or all the non-empty neighbors in $N(u)$ must have a singleton agent. If this condition is true, then $\psi(u)$ becomes a local leader if 
one of the following conditions is satisfied:
\begin{itemize}
\item {\bf Condition I.} $\forall v\in N(u), \delta_v>\delta_u$. In other words, $u$ has the unique smallest degree among the nodes in $N(u)$. % and all nodes in $N_{occ}$ has a singleton agent. %, $\psi(u)$ becomes a local leader. 
%Let $N_{occ}(u)$ be the neighbor nodes of $u$ in $G$ that are occupied with agents.
\item {\bf Condition II.} $\forall v\in N(v), \delta_v\geq \delta_u$ with no node $v'\in N(u)$ with $\delta_{v'}=\delta_u$ is empty, and $\psi(u).ID>\psi(v').ID$. In other words, $\psi(u)$ has a higher ID than $\psi(v')$ when $u$ and $v'$ have the same smallest degree.
\item {\bf Condition III.} $\forall v\in N(v), \delta_v\geq \delta_u$ with (at least one) node $v'\in N(u)$ with $\delta_{v'}=\delta_u$ is empty, $\psi(u)$ runs $Neighbor\_Exploration\_with\_Padding(\psi(u))$ (Algorithm \ref{algorithm:padding}) and $v'$ remains empty even after  Algorithm \ref{algorithm:padding} finishes. In other words, $\psi(u)$ finds that the same smallest degree neighbor $v'$ is empty. 
\end{itemize}

%Agent $\psi(u)$ becomes a local leader running 
%{\em Singleton\_Election} if and only if
%\begin{itemize}
%\item $\delta_u$ is the smallest among the nodes in $N_{occ}(u)$. If $\exists v\in N_{occ}(u)$ with $\delta_v=\delta_u$, $\psi(u).ID<\psi(v).ID$.
