\subsubsection{Analysis of the Algorithm}
We now analyze our stabilizing algorithm (Algorithm \ref{algorithm:leader_election}). We have $k<n$ and agents have no parameter knowledge.  We start with Stage 1 procedure {\em Singleton\_Election} (Algorithm \ref{algorithm:local_electionk}). Recall that {\em Singleton\_Election} is run by singleton agents.


\begin{lemma}
\label{lemma:padding}
 Suppose $\forall v\in N(u), \delta_v\geq \delta_u$ and $\exists v'\in N(u), \delta_{v'}=\delta_u$. Agent $\psi(u)$ meets a singleton agent $\psi(v')$ (if any positioned initially at node $v'$) or vice-versa in $O(\delta_u \log^2 k)$ rounds, running  $Neighbor\_Exploration\_with\_Padding(\psi(u))$ (Algorithm \ref{algorithm:padding}). 
\end{lemma} 


\begin{proof}
%Since agent IDs are from the interval $[1, k^{O(1)}]$, 
Each agent has a unique ID of size $\leq c\cdot \log k$, for some constant $c$. Therefore, for any two neighboring agents $\psi(u)$ and $\psi(v')$, the number of bits on their IDs are either equal or unequal. Consider the equal case first. If $\psi(u)$ and $\psi(v')$ have an equal number of bits (say, $b$) then their IDs must differ by at least a bit, i.e., if one has bit `1' at $\beta$-th place from MSB, another must have bit `0' at $\beta$-th place from MSB. Since an agent explores neighbors in $N(u)$ while the bit is `1' and stays at $u$ when the bit is `0', $\psi(u)$ finds $\psi(v')$ within $2 \delta_{u} \cdot b$ rounds. 
%
%Since the bit may be different at the $b$-th place from MSB, the total time taken for $r_u$ to meet $r_v$ is $O(\delta_{u} \log n)$ rounds.

Now consider the unequal case. Let $\psi(u)$ and $\psi(v')$, respectively, have  $b$ and $d$ bits in their IDs, $b\neq d$. W.l.o.g., suppose $b>d$, i.e., $b = d+c_1$, $d, c_1 \geq 1$. Consider now the padding. %of bits `10' $b^2$ times. 
The $b$ bit ID becomes $b+2b^2$ bit ID and the $d$ bit ID becomes $d+2d^2$ bit ID. 
We have that 
$$b+2b^2=(d+c_1) + 2(d+c_1)^2 = 2d^2+2c_1^2+4 \cdot d \cdot c_1+d+c_1.$$ 
The difference in the number of bits of the IDs of $\psi(u)$ and $\psi(v')$ is $$2c_1^2+4 \cdot d \cdot c_1+c_1.$$ 

Since $d,c_1\geq 1$, $2c_1^2+4 \cdot d \cdot c_1+c_1$ is at least  $7$-bit long, and out of the $7$ bits, at least  $3$ bits are `1'.
    What that means is, if $\psi(v')$ (the smaller ID than $\psi(u)$) stops after $2\delta_{v}(d+2d^2)$ rounds, then there are at least $3$ chances for $\psi(u)$ to meet $\psi(v')$ at  $v'$. Therefore, the round complexity becomes   $O(2\delta_{u} (b+2b^2))=O(\delta_u \log ^2k)$ rounds, since $b\leq c\cdot \log k$. %The lemma follows.
\end{proof}



\begin{lemma}\label{lem:rounds_with_same_degree_leader}
     If $\psi(u)$  becomes a local leader running $Singleton\_Election(\psi(u))$, no singleton agent $\psi(v),~v\in N(u),$ becomes local leader running $Singleton\_Election(\psi(v))$.
     $Singleton\_Election(\psi(u))$ finishes in $O(\delta_u \log^2 k)$ rounds.
    \end{lemma}
\begin{proof}
Suppose $\forall v\in N(u), \delta_v>\delta_u$.  Consider a singleton agent $\psi(v)$ at any node $v\in N(u)$. When $\psi(v)$ runs  $Singleton\_Election(\psi(v))$ it finds that $\delta_u<\delta_v$ and $\psi(v)$ becomes a non-candidate. An unoccupied node $v'\in N(u)$ does not run {\em Singleton\_Election}. Therefore, for $\psi(u)$, visiting all neighbors in $N(u)$ finishes in $2\delta_u$ rounds.

Now  suppose $\forall v\in N(u), \delta_v\geq \delta_u$ and $\exists v'\in N(u), \delta_{v'}=\delta_u$.  We have from Lemma \ref{lemma:padding} that $\psi(u)$ either finds $v'$ has no singleton agent or meets singleton agent $\psi(v')$ in  $O(\delta_u \log ^2k)$ rounds running $Neighbor\_Exploration\_with\_Padding(\psi(u))$ (Algorithm \ref{algorithm:padding}). 
If there is singleton agent $\psi(v')$ at $v'$, then $\psi(u)$ becomes a local leader if $\psi(u).ID>\psi(v').ID$, otherwise a non-candidate. If $v$ is unoccupied, $\psi(u)$ becomes a local leader and no agent in $N(u)$ becomes a local leader. The time complexity is to first visit all the neighbors in $N(u)$, which finishes in $2\delta_u$ rounds, and after that time to run  
$Neighbor\_Exploration\_with\_Padding(\psi(u))$ (Algorithm \ref{algorithm:padding}). Therefore, the total time complexity of $Singleton\_Election(\psi(u))$ is    $2\delta_u+O(\delta_u \log ^2k)=O(\delta_u \log ^2k)$ rounds.   
\end{proof}

 \begin{lemma}
     \label{lemma:dispersed-election}
Consider a dispersed initial configuration. At least one singleton agent $\psi(u)$ at node $u$  becomes a local leader running 
$Singleton\_Election(\psi(u))$
(Algorithm \ref{algorithm:local_electionk}).   \end{lemma}


\begin{proof}
    Let $u$ be the smallest degree node in $G$, i.e., $\delta_u=\min_{v\in G}\delta_v$. 
    We have two cases: (I) $\forall v'\in G, v'\neq u, \delta_u<\delta_{v'}$
    %, i.e., there is no other node $v\in G$ such that $\delta_u=\delta_{v}$ 
    (II) $\exists v'\in G, \delta_{v'}=\delta_u$.
    In Case (I), since $u$ is the unique smallest degree node, $\psi(u)$ becomes a local leader  in $O(\delta_u \log^2 n)$ rounds. No singleton agent $\psi(w)$ in $N(u)$ becomes a local leader since $\delta_w>\delta_u$. Now consider Case (II). We have two sub-cases: (II.A) $v'\in N(u)$ (II.B) $v'\notin N(u)$. In Case (II.B), $\psi(u)$ is elected as a local leader as discussed in Case (I). For Case (II.A), we have from Lemma \ref{lem:rounds_with_same_degree_leader} that $\psi(u)$ meets $\psi(v')$ (or vice-versa) in $O(\delta_u\log^2k)$ rounds. After that, either $\psi(u)$ or $\psi(v')$ becomes a non-candidate depending on their IDs. Suppose $\psi(u).ID>\psi(v').ID$, $\psi(v')$ becomes non-candidate, $\psi(u)$ becomes a local leader, and we are done. Otherwise, if $\psi(u).ID<\psi(v').ID$, $\psi(u)$ becomes a non-candidate. Now suppose even with $\psi(u).ID<\psi(v').ID$, $\psi(v')$ becomes a non-candidate. Then, there must be the case that $v'$ has a neighbor $v''\in N(v'')$ with $\delta_{v''}=\delta_{v'}=\delta_u$ and $\psi(v'').ID>\psi(v').ID$. This chain stops at the first node $v*$ such that $\psi(v''').ID< \psi(v*).ID>\ldots>\psi(v'').ID>\psi(v').ID>\psi(u).ID$, $v'''\neq v*\neq \ldots \neq v''\neq v'\neq u$, if $v'''$ has a singleton agent. If $v'''$ is empty, this chain stops at $v*$. In both cases, agent $\psi(v*)$ in this chain becomes a local leader.    
 \end{proof}


