\begin{theorem}[{\bf Stabilizing MST, $k<n$}]
\label{theorem:stabilizingMST}
There is a stabilizing deterministic algorithm for constructing MST for each component $C_j$ in the agentic model, without agents knowing any graph parameter a priori.  The time complexity of the algorithm is $O(\Delta\log^2k+|C_{\max}|(\Delta+\log |C_{\max}|))$ rounds and the memory complexity is 
 $O(\max\{\ell_{\max},\zeta_{\max},\Delta,\log (k+\Delta)\} \log (k+\Delta))$ bits per agent.
%$O(\Delta \log n)$ bits at each agent,  % ({\bf Section \ref{sec: MST construction}})
\end{theorem}


