\title{The cohomology ring of the boundary manifold of a combinatorial line arrangement}
\author{Sakumi Sugawara}
\date{\today}
\address{Department of Mathematics, Faculty of Science, Hokkaido University, North 10, West 8, Kita-ku, Sapporo 060-0810, JAPAN. }
\email{math.skm.sugawara@gmail.com}
