\centering
\includegraphics[width=0.6\textwidth]{eqs_fix.pdf}
\caption{Interpreting equations reduces them to fundamental physical principles. The physical principle is analogous to a latent variable that decodes to different equations for different physical systems.}
\label{latent}
\end{figure}




