\section{A fractional Schrödinger equation}
\label{sec6}
As a special case we mentioned in section 3.3, $\varepsilon$ is pure imaginary will lead a Schrödinger equation with the half Laplacian. Suppose $\gamma = -\mathrm{i}\varepsilon$ for $\varepsilon\in\RR^+$, we consider to apply Doubling procedure for
\begin{equation}
    \left\{\begin{aligned}
   & \mathrm{i}~\frac{\partial u}{\partial t}= \gamma(-\Delta)^\frac{1}{2}u + Vu,\qquad (x,t) \in (0, L)\times \RR^+,~ \gamma \in \RR,\\
   & u(x,0) = u_0(x),
\end{aligned}\right.\label{schrodinger}
\end{equation}
where $V$ is the potential term independent with $x$ and $t$. 
\begin{theorem}
    Suppose $u=v+\mathrm{i} ~ w$ for $v,w\in H^1_0((0,L))\cap H^2((0,L))$, then 
    \begin{equation}
        u(x,t) = \frac{e^{\mathrm{-i}Vt}}{2}[u_0(x+\gamma t)+u_0(x-\gamma t)+\mathrm{i}~ \mathcal{H}(u_0(x+\gamma t))-\mathrm{i}~ \mathcal{H}(u_0(x-\gamma t))]\label{sol_schrodinger}
    \end{equation}
    solves (\ref{schrodinger}). If furthermore, \( u_0 = v_0+ \mathrm{i} w_0\) with \(v_0, w_0 \in H^1_0(0, L) \), then (\ref{sol_schrodinger}) is equivalent to
    \begin{equation}
        u(x,t) = \frac{2}{L}\sum^\infty_{n=1}C_n\sin\left(\frac{\pi n x}{L}\right)e^{\mathrm{i} (\gamma\pi n/L-V) t},
    \end{equation}
    where
    \(C_n=\int^L_0 u_0(\xi)\sin\left(\frac{\pi n \xi}{L}\right)d\xi.\)
\end{theorem}

\begin{proof}
We employ a transform similar to that used in Appendix B.3 by letting $u = e^{-\mathrm{i}Vt}\widetilde{u}$ to cancel the term $Vu$ in (\ref{schrodinger}). We then use the spectrum doubling procedure of (\ref{schrodinger}) arrive at the wave system
\begin{equation}
    \left\{\begin{aligned}
  &  \widetilde{u}''=\gamma^2\mathcal{D}^2\widetilde{u},~~~~ (x,t) \in (0, L)\times \RR^+\\
  &  \widetilde{u}(x,0) = \widetilde{u}_0(x),~\widetilde{u}'(x,0) = -\mathrm{i}\gamma \mathcal{H}(\mathcal{D}\widetilde{u}_0(x)).
\end{aligned}\right.\label{D_schrodinger}
\end{equation}
Writing $\widetilde{u}=v+\mathrm{i} ~ w$ and \( \widetilde{u_0} = v_0+ \mathrm{i} w_0\) we arrive at two real wave system with respect to $v,w$. By using the identity $\mathcal{H}(\mathcal{D}\widetilde{u}_0)=\mathcal{D}\mathcal{H}(\widetilde{u}_0)$ along with d'Alembert's formula, we obtain the solution to these two system
\begin{align}
     &   v(x,t) = \frac{1}{2}\left(v_0(x+\gamma t)+v_0(x-\gamma t)\right) -\frac{1}{2}\left(\mathcal{H}\left(w_0(x+\gamma t)\right)-\mathcal{H}\left(w_0(x-\gamma t)\right)\right),\tag{6.5a}\label{v}\\
      &  w(x,t) = \frac{1}{2}\left(w_0(x+\gamma t)+w_0(x-\gamma t)\right) +\frac{1}{2}\left(\mathcal{H}\left(v_0(x+\gamma t)\right)-\mathcal{H}\left(v_0(x-\gamma t)\right)\right),\tag{6.5b}\label{w}
\end{align}
which directly give the solution of (\ref{D_schrodinger}):
\[\widetilde{u}(x,t) = \frac{1}{2}[\widetilde{u}_0(x+\gamma t)+\widetilde{u}_0(x-\gamma t)+\mathrm{i} \mathcal{H}(\widetilde{u}_0(x+\gamma t))-\mathrm{i} \mathcal{H}(\widetilde{u}_0(x-\gamma t))].\]
% \setcounter{equation}{31}
We define \( \widetilde{v_0} \) as the periodic extension of \( v_0 \), i.e.,
\[
\widetilde{v_0}(x) := \begin{cases}
    -v_0(x), & \text{if } x \in [(k-1)L, kL], \\
    ~~v_0(x), & \text{if } x \in (kL, (k+1)L),
\end{cases}~~~k\in\mathbb{Z},
\]
ensuring  \( \widetilde{v_0} \in C(\RR) \). Its Fourier series leads to
\setcounter{equation}{5}
\begin{equation}
    v_0(x) = \frac{2}{L} \sum_{n=1}^\infty \sin\left(\frac{\pi n x}{L}\right) \int_0^L \sin\left(\frac{\pi n \xi}{L}\right) v_0(\xi) \, d\xi,~~~x\in(0,L),\label{fourier_v0}
\end{equation}
and similarly for for $w_0(x)$:
\begin{equation}
    w_0(x) = \frac{2}{L} \sum_{n=1}^\infty \sin\left(\frac{\pi n x}{L}\right) \int_0^L \sin\left(\frac{\pi n \xi}{L}\right) w_0(\xi) \, d\xi,~~~x\in(0,L).\label{fourier_w0}
\end{equation}
Substituting (\ref{fourier_v0}-\ref{fourier_w0}) into (\ref{v}-\ref{w}) and finally multiplying by the factor $e^{-\mathrm{i}Vt}$ completes the proof.

\end{proof}
