\section{Analytical solutions for (\ref{original_half})}
\subsection{The homogeneous half-diffsuion equation}
Continue with the (\ref{fenli}), since $-\varepsilon^2\Delta$ on (0,L) with Dirichlet boundary conditions has eigenfunctions $e_n(x) = \sin{\left(\frac{\varepsilon n\pi}{L}\right)}$ and eigenvalues $\left(\frac{\varepsilon n\pi}{L}\right)^2$ for $n=1,2,...$ and $(-\Delta)^{\frac{1}{2}}$ is nonnegative, then we derive 
\[\left\{\begin{aligned}
  &  U_{T,n}(t) = \exp(-\varepsilon\frac{n\pi t}{L})\\
  &  U_{X,n}(x) = C_n \sin\left(\frac{n\pi x}{L}\right).
\end{aligned}\right.\]
Thus,
\begin{equation}
    u(x,t) = \sum_{n=1}^\infty C_n\sin\left(\frac{n\pi x}{L}\right)e^{-\varepsilon\frac{n\pi}{L}t},
\end{equation}
where \(C_n = \frac{2}{L}\int^L_0u_0(s)\sin\left(\frac{n\pi s}{L}\right) ds\). The general solution for fractional order \(\alpha\in(0,2)\) can be found in \cite{YANG2010}.
\subsection{The non-homogeneous half-diffusion equation: \texorpdfstring{$\mathcal{L}=0, f\neq 0$}.}
We have already solved the homogeneous PDE (\ref{original_half}) with $\mathcal{L}=0$.
By using of the eigenfunction expansion, see \cite{rauch2012partial}, to write the nonhomogeneous PDE in terms of the homogeneous problem
\[u(x,t) = \sum^\infty_{n=1}T_n(t)X_n(x)= \frac{2}{L}\sum^\infty_{n=1}T_n(t)\sin\left(\frac{n\pi x}{L}\right).\]
From Dirichlet's convergence theorem, we can expand \( u_0(x) \) and \( f(x,t) \) as follows:
\begin{equation}
    u_0(x) = \sum_{n=1}^\infty u_{0,n} \sin\left(\frac{n\pi x}{L}\right),\ 
    f(x,t) = \sum_{n=1}^\infty f_n(t) \sin\left(\frac{n\pi x}{L}\right),\tag{$\star$}\label{u_and_f}
\end{equation}
where \( u_{0,n}\) and \( f_n(t) \) are Fourier coefficients.
Substitute (\ref{u_and_f}) into (\ref{heat}) we have
\[\sum^\infty_{n=1}\left[T'_n(t)+\varepsilon\frac{n\pi}{L}T_s(t) -f_n(t)\right]  \sin\left(\frac{n\pi x}{L}\right) = 0.\]
From the orthogonality of the eigenfunctions on \([0,L]\) we have
\[
T'_n(t) +\varepsilon \frac{n \pi}{L}T_n = f_n(t),
\]
with \(T_n(0) = u_{0,n}\). Solving this ode system it gives 
\[T_n(t) = e^{-\varepsilon\frac{n\pi t}{L}}\left(u_{0,n} + \int^t_0 e^{\varepsilon\frac{n\pi \tau}{L}}f_n(\tau)d\tau\right).\]
And thus,
\begin{equation}
   \begin{aligned}
        u(x,t) = &\int^L_0 u_0(\xi)G(x,\xi,t)  + \int^t_0\int^L_0 f(\xi,\tau)G(x,\xi,t-\tau)d\xi d\tau,\\
&G(x,\xi,t) = \frac{2}{L}\sum^\infty_{n=1}e^{-\varepsilon\frac{n\pi t}{L}}\sin\left(\frac{n\pi x}{L}\right) \sin\left(\frac{n\pi \xi}{L}\right).
    \end{aligned}\label{classical_sol_0}
\end{equation}
\subsection{The non-homogeneous mass transfer equation with the half-diffusion term: $\mathcal{L}=\delta\mathcal{I}, f\neq 0$}
The substitution \(u = e^{\delta t}u\) leads to the nonhomogeneous equation (\ref{heat})
\[\frac{\partial u}{\partial t}=-\varepsilon(-\Delta)^\frac{1}{2}u +e^{-\delta t}f(x,t).\]
Then from (A.2) we have the following solution of (\ref{diffusion_u}):
\begin{equation}
    u(x,t) = \int^L_0 u_0(\xi)G(x,\xi,t)d\xi + \int^t_0\int^L_0f(\xi,\tau)G(x,\xi,t-\tau)d\xi d\tau,\label{classical_sol_u}
\end{equation}
where 
\[G(x,\xi,t)=\frac{2}{L}e^{\delta t}\sum^\infty_{n=1}\sin\left(\frac{\pi n x}{L}\right)\sin\left(\frac{\pi n \xi}{L}\right)e^{-\frac{\varepsilon\pi n t}{L}}.\]
\subsection{The non-homogeneous advection dominated equation with half-diffusion: $\mathcal{L} = \delta \mathcal{D}, f\ne0$}
Under the assumption $u,f\in H^1_{\text{per}}(\Omega_{\text{per}})$, this is a equation involves an advection term, and we consider solutions of the form \( w(s,t) = u(x+\delta t,t) \) to eliminate the advection. The key step is the translation-invariance of the half-Laplacian \((-\Delta)^{\frac12}\). By its Fourier definition, \((-\Delta)^{\frac12}\) acts as a Fourier multiplier, ensuring that \((-\Delta)^{\frac12}u(x+a,t) = ((-\Delta)^{\frac12}u)(x+a,t)\) for any shift \(a\). Similarly, the Hilbert transform \(\mathcal{H}\) shares this property \cite{hilbert_book}. Consequently, the shifted coordinate system eliminates the linear transport term without altering the half-Laplacian or the Hilbert transform. Substituting the solution $w(s,t)$ leads to the non-homogeneous half-diffusion equation (\ref{heat})
\[\frac{\partial w}{\partial t}=-\varepsilon(-\Delta)^\frac{1}{2}w +f(s-\delta t,t),\]
then use \eqref{classical_sol_0} and transform back to the original variable $x$, the solution is given by
\begin{equation}
        u(x,t) = \int^L_0 u_0(\xi)G(x+\delta t,\xi,t)d\xi  + \int^t_0\int^L_0 f(\xi,\tau)G(x+\delta (t-\tau),\xi,t-\tau)d\xi d\tau,\label{classical_sol_ux}
\end{equation}
where 
\[G(x,\xi,t) = \frac{2}{L}\sum^\infty_{n=1}e^{-\varepsilon\frac{n\pi t}{L}}\sin\left(\frac{n\pi x}{L}\right) \sin\left(\frac{n\pi \xi}{L}\right).\]


\section{Practical solutions of Eq. (\ref{sec4.19}) }
For simplicity, we only show how to solve one of this sequence of linear systems (\ref{sec4.19}) without the subscript $j$:
\begin{equation}
\begin{bmatrix}
\widetilde{\lambda} I  &   -I \\
   -P      & \widetilde{\lambda} I - Q
\end{bmatrix}\begin{bmatrix}
{\bm v}^{(1)}_2  \\
{\bm v}^{(2)}_2  
\end{bmatrix} = 
\begin{bmatrix}
{\bm v}^{(1)}_1\\
{\bm v}^{(2)}_1
\end{bmatrix} 
\end{equation} 
where we can eliminate ${\bm v}^{(2)}_2$ from the equations, as follows.
\begin{equation}
{\bm v}^{(2)}_2 = \widetilde{\lambda}{\bm v}^{(1)}_2 - {\bm v}^{(1)}_1,
\label{eqB2}
\end{equation} 
Substituting this expression into the second equation yields
\[
\left[\widetilde{\lambda}(\widetilde{\lambda} I - Q) - P\right]{\bm v}^{(1)}_2 = {\bm v}^{(2)}_1 + (\widetilde{\lambda} I - Q){\bm v}^{(1)}_1,
%u(x,0) = u_0(x), \quad v(x,0) = v_0(x), \quad u(0,t) = u(L,t) = 0, \quad t \in [0, T],{\bm v}^{(2)}_2 
\]
Solving the above reduced equation with half the size (via some sparse direct solvers, e.g., {\tt MUMPS} solver \url{https://mumps-solver.org/index.php}), the vector ${\bm v}^{(1)}_2$ is given and then substitute it into Eq. \eqref{eqB2} to get ${\bm v}^{(2)}_2$, we work out the solution 
$$\widetilde{{\bm v}}_2 = 
\begin{bmatrix}
{\bm v}^{(1)}_2\\
{\bm v}^{(2)}_2
\end{bmatrix}
$$
for one of the sequence of linear systems \eqref{sec4.19}.


