\begin{restatable}{proposition}{LocalToGlobalWithErrors}\label{prop:local_approx_w_errors}
    Let $\sfA$ be a $k$-uniform $\alpha$-approximation \LOCAL algorithm for \minDS in a hereditary class of graphs $\sC$ with round complexity $r$. %\cyril{I would write "... with round complexity $r$." So, do we need in the proof that $r\neq 0$? The new proof does not requires $r\ge 1$ anymore.}
    Let $\sD$ be a graph class with a $d$-dimensional control function $f$. Then, there exists a $k$-uniform $(\alpha (d+1)+1)$-approximation algorithm $\sfB$ on $\sD$ with round complexity $T+\delta+2$, where $T = f(2k+2) + \max\set{k+1,r}$ and where $\delta$ is the maximum weak diameter in any $G\in\sD$ of any connected component of $G[N^2[X]]$, $X$ being the $T$-errors of $G$ w.r.t. $\sC$. %\cyril{It would be nice to say that $\sfB$ is also $k'$-uniform for some $k'$, since we could re-apply it (as long as it is hereditary and still of small asdim.}
    Furthermore, if $\sD$ is $T$-locally-$\sC$ (i.e., there is no $T$-errors), then the approximation ratio of $\sfB$ is $\alpha (d+1)$.
    %\cyril{I suggest to add: ``Furthermore, if $\sD$ is $T$-locally-$\sC$ (i.e., $X = \emptyset$), then the approximation ratio of $\sfB$ is $\alpha (d+1)$.'' This allows us to catch for free the uniform property of $\sfB$ if $\sD$ is $T$-locally-$\sC$.}
\end{restatable}

The proof is an adaptation of that of Proposition~\ref{prop:local_approx}, and we include it in~\cref{sec:propwitherrors}. However, we already describe the corresponding algorithm $\sfB$.

\begin{algorithm}
\caption{Generic algorithm $\sfB$ from \cref{prop:local_approx_w_errors}.}\label{algo:MDS}
\begin{algorithmic}[1]

\Require A $k$-uniform $\alpha$-approximate \LOCAL algorithm $\sfA$ for \minDS in a hereditary class of graphs $\sC$ with round complexity $r$, a graph class $\sD$ with a $d$-dimensional control function $f$, $G\in\sD$ with $T$-errors $X$ where $T = f(2k+2) + \max\set{k+1,r}$. %\cyril{I think it is more clear that we speak in term of "$d$-dimensional control function $f$" when we care about about $f$, and of "asymptotic dimension $d$" when we do not care about $f$. In fact here (and in the above proposition) we really don't care about $d$ for the input. For the input we care about the control function. Whereas we care of $d$ in the output (approx ratio).}

\Ensure A dominating set $S$ of $G$ such that $\card{S} \le (\alpha (d+1)+1) \cdot \MDS(G)$.

\State $S \gets \emptyset$

\State Each vertex $u$ computes $G[N^T[u]]$ and checks whether it belongs to $\sC$; as a consequence, it decides whether it belongs to $X$. 

%\cyril{I've removed "the next" in "for the next $r$ rounds". this is because to can run in parallel Step~2 and Step~3 to get a slighlty better running time.}
\State Each vertex $u$ runs $\sfA$ for $r$ rounds, and gets added to $S$ only if $u\in \sfA(G)\setminus X$.

\State $S \gets S \cup S'$, where $S'$ is a brute-forced minimum set of $G$ that dominates $V(G)\setminus N[S]$.

\end{algorithmic}
\end{algorithm}

To illustrate \cref{prop:local_approx_w_errors}, assume that $\sC$ and $\sD$ are respectively the class of planar and Euler genus-$g$ graphs, for a given $g\ge 1$. Moreover, assume that we are given a \LOCAL algorithm $\sfA$ with round complexity $r$ for \minDS that is a $k$-uniform $\alpha$-approximation on $\sC$, where $k,\alpha,r$ are small constants.

Euler genus-$g$ graphs exclude $K_{3,2g+3}$, and thus have asymptotic dimension at most two~\cite[Theorem~1.9]{BBEGx24}, and even Assouad-Nagata dimension at most two. So, there is a $2$-dimensional control function $f(x) \le c(g) \cdot x$, for some function $c$.

Consider a graph $G \in\sD$ with $T$-error set $X$, where $T = f(2k+2) + \max\set{k+1,r} = O_g(1)$. 

According to \cref{prop:local_approx_w_errors} applied on $\sC$, $\sD$ and $\sfA$, Algorithm $\sfB$ has approximate ratio $2(\alpha+1)+1 = O(1)$ for $G$ and has round complexity $T + \delta + 2 = O_g(1) + \delta$. To conclude that the round complexity of $\sfB$ is in $O_g(1)$, we show that:

\begin{claim}\label{claim:genus_additivity}
     $\delta < g\cdot(2T+5)$, for any $g\ge 1$.
\end{claim}

\begin{proof}
    To derive a contradiction, consider a connected component $H$ of $G[N^2[X]]$, and assume that $H$ has weak diameter $\delta \ge g \cdot (2T+5)$ in $G$. As $g\ge 1$, $X$ and $H$ are not empty. So, $H$ must contain some path $P$ such that the distance in $G$ between its endpoints, say $s$ to $t$, is $\delta$. In particular, for each $d \in\set{0,1,\dots,\delta}$, there must exist a vertex of $P$ that is at distance exactly $d$ in $G$ from~$s$. This is because the distance in $G$ from $s$, when moving along an edge of~$P$, is a function that can vary by at most one unit, and this distance goes from $0$ (at $s$) to $\delta$ (at $t$). For every $i \in\set{0,1,\dots,g}$, let $u_i$ be any vertex of $P$ at distance exactly $d_i =  i\cdot (2T+5)$ in $G$ from $s$. So $u_0 = s$, $u_g = t$, and all the $u_i$'s exist in $P$ (so in $H$) since $d_i \in\set{0,1,\dots,\delta}$. By definition of $H$, each $u_i$ intersects $N^2[X]$. So, for each $u_i$ one can select a vertex $x_i\in X$ at distance in $G$ at most~2 from $u_i$. By the triangle inequality, for all $0\le i<j\le g$, $x_i$ and $x_j$ are at distance in $G$ at least $(d_j-2) - (d_i+2) = (j-i) \cdot(2T+5) - 4 \ge 2T+1$. It follows that $N^T[x_i]$ and $N^T[x_j]$ are disjoint. By definition of $X$, the subgraphs $G[N^T[x_i]]$'s are not planar, thus of Euler genus $\ge 1$. By additivity of the Euler genera
    % Cyril{genera = plurial of genus.}
    of these $g+1$ pairwise disjoint subgraphs of $G$ (cf.~\cite[Theorem~4.4.3]{MT01}),
    % Cyril{In fact this theorem says that the Euler genus of a graph is the sum of its Euler genera of its blocks. So deleting edges in $G$, we can obtain one block of each subgraph.}
    we get a contradiction that $G$ has Euler genus $g$. Thus $\delta < g\cdot (2T+5)$ as claimed.
\end{proof}

We remark that \cref{claim:genus_additivity} is the only place where Euler genus is used. From the above discussion, to prove our approximation result on Euler genus-$g$ graphs (\cref{th:bounded_genus}), we simply need to design a $O(1)$-uniform $O(1)$-approximation algorithm $\sfA$ for planar graphs. In other words, we have made a reduction of $3\alpha$-approximation for Euler genus-$g$ graphs from $O(1)$-uniform $\alpha$-approximation algorithm for planar graphs.

\begin{restatable}{proposition}{PropUniformPlanar}\label{prop:uniform_planar}
    There is a $4$-uniform $\RATIOP$-approximation \LOCAL algorithm $\sfA$ for \minDS in planar graphs with round complexity~$5$.
\end{restatable}

We present a very short proof of~\cref{prop:uniform_planar} in~\cref{sec:localplanar}. A direct application of \cref{prop:local_approx_w_errors} and of the above discussion, is that Algorithm~$\sfB$ is a $\RATIO$-approximation for Euler genus-$g$ graphs. However, it is possible to obtain a much better ratio for planar graphs, with significantly more work. Although it is not explicitly stated in their paper, we can observe the following.

\begin{observation}\label{obs:localplanar}
 The algorithm described in~\cite[Theorem~2.3]{HKOSV25} is a $7$-uniform $(11+\eps)$-approximation \LOCAL algorithm for \minDS in planar graphs with round complexity $C(\eps)$, for some function $C$.
\end{observation}%TODO : vérifier 7 + regarder où y'a le epsilon

From~\cref{obs:localplanar} and~\cref{prop:local_approx_w_errors}, and from the above discussion, we immediately obtain our first main result:

\begin{theorem}\label{th:bounded_genus}
    For any $\eps>0$, for any $g$, there is a $7$-uniform $(\RATIOG +\eps)$-approximation \LOCAL algorithm for \minDS in Euler genus-$g$ graphs with round complexity $C(\eps,g)$ for some function $C$.
\end{theorem}%TODO : vérifier fonction de contrôle, est-ce que c'est bien linéaire ?
%TODO: est-ce bien $O(\eps^{-1})$-uniform?

We can even go one step further by applying \cref{prop:local_approx} to the uniform approximation \LOCAL algorithm derived from~\cref{th:bounded_genus}, and the class $\sC$ of Euler genus-$g$ graphs. We immediately obtain our second main result:

\begin{theorem}\label{th:locally_bounded_genus}
    Let $\sC$ be the class of Euler genus-$g$ graphs, and $\sD$ be a graph class of asymptotic dimension $d$ that is $r$-locally-$\sC$ for some $r$ large enough. Then, there is a $\RATIOGO (d+1)$-approximation \LOCAL algorithm for \minDS in $\sD$ with round complexity $C(d,g,r)$ for some function $C$.
\end{theorem}

