\section{Self-contained proof of Proposition~\ref{prop:local_approx_w_errors}}\label{sec:propwitherrors}

\LocalToGlobalWithErrors*

\begin{proof}
    %\cyril{For setminus operator, please choose between $X\setminus Y$ (that I prefer) and $X-Y$. Please check and uniformize in all the paper. }\tim{$\setminus$ is for sets, $-$ is for graphs.}
    Let $G\in \sD$. As $\sD$ has $d$-dimensional control function $f$, the graph $G^{2k+2}$ admits a $(d+1)$-coloring $f(2k+2)$-bounded in $G$. Fix such a coloring, and, for each $i\in\set{0,1,\dots,d}$, let $C_i$ be the set of color-$i$ vertices in $G^{2k+2}$ (and also in $G$). We denote by $\CC_i$ the set of connected components of $G^{2k+2}[C_i]$. 
    So, by definition, all components of $\CC_i$ have weak diameter in $G$ at most $f(2k+2)$, and are pairwise at distance at least $2k+3$ in $G$ (because distinct components of $\CC_i$ cannot be adjacent in $G^{2k+2}$).

    We run Algorithm~$\sfB$ on $G$. It is easy to check that $\sfB(G)$ is a valid dominating set for $G$. By definition, $\card{\sfB(G)} \le |S| + |S'|$, where $S = \sfA(G)\setminus X$ (Step~3) and $S'$ is a brute-forced minimum set dominating $V(G)\setminus N[S]$ (Step~4). Clearly, $\card{S'} \le \MDS(G)$, and $\card{S'} = 0$ if there is no $T$-errors ($X=\emptyset$). Moreover, by definition of the coloring, $\card{\sfA(G)\setminus X} = \sum_{i=0}^d \card{(\sfA(G)\cap C_i)\setminus X}$. In other words,
    \begin{equation}\label{eq:B(G)}
    \card{\sfB(G)} ~\le~ \sum_{i=0}^d \card{(\sfA(G)\cap C_i)\setminus X} + \left\{%
        \begin{array}{ll}
        0 &\mbox{if $X=\emptyset$}\\
        \MDS(G) &\mbox{otherwise}
        \end{array}
        \right.
    \end{equation}

    To upper bound the term $\card{(\sfA(G)\cap C_i)\setminus X}$, consider some color $i\in\set{0,1,\dots,d}$ and some component $C\in \CC_i$ such that $C\not\subseteq X$. Consider some $v\in C\setminus X$, and denote $G_v = G[N^T[v]]$. Note that, by definition of $X$ and as $v\notin X$, $G_v \in\sC$.

    Along the proof, we will use several times the following fact:

    \begin{fact}\label{fact:dom}
        For any graph $H$ and $W \subseteq V(H)$, to dominate $W$ in $H$, it is enough to select vertices taken from $N[W]$.
    \end{fact}

    In the following, to differentiate the neighborhoods in $G$ and in $G_v$, we write them using either $N_G$ or $N_{G_v}$ notations.
    Notice that, for each non-negative integer $t\le \max\set{k+1,r}$, $G[N_{G}^t[C]]\subseteq G_v$. This is because $C$ has weak diameter in $G$ at most $f(2k+2)$ and thus $G[N_{G}^t[C]]$ has weak diameter in $G$ at most $f(2k+2) + t \le T$, by the choice of $T$. Moreover, as $\sC$ is hereditary, we have that $G[N_{G}^t[C]]\in \sC$.

    As $G[N^t_G[C]]\subseteq G_v$, vertices in $C$ have the same distance $t$-neighborhood in $G$ and $G_v$. In particular, $G[N^t_G[C]] = G_v[N^t_{G_v}[C]]$. From~\cref{fact:dom}, any minimum set of vertices of $G$ that dominates $N^k_G[C]$ is contained in $G[N^{k+1}_G[C]]$, and similarly if we replace $G$ by $G_v$. It follows that $\MDS(G,N^k_{G}[C]) = \MDS(G_v,N^k_{G_v}[C])$. Because Algorithm~$\sfA$ is a $k$-uniform $\alpha$-approximation on $\sC$, and $G_v\in \sC$, we get
    \[
        \card{\sfA(G_v)\cap C} ~\le~ \alpha \cdot \MDS(G_v,N_{G_v}^k[C]) = \alpha \cdot \MDS(G, N^k_G[C]) ~.
    \]
    Since $G[N^r_G[C]] = G_v[N^r_{G_v}[C]]$, Algorithm~$\sfA$, which runs in $r$ rounds, returns the same vertex set in $G$ and $G_v$ for vertices in $C$. Therefore, $\card{\sfA(G)\cap C} = \card{\sfA(G_v)\cap C}$. Combining with the previous inequality, we get
    \[
        \card{\sfA(G)\cap C} ~\le~ \alpha \cdot \MDS(G, N_G^k[C]),\quad\forall C\in\CC_i, C\not\subseteq X.
    \]
    Recall that any two connected components $C, C' \in \CC_i$ are at distance in $G$ at least $2k+3$. So $G[N^{k+1}_G[C]]$ and $G[N^{k+1}_G[C']]$ are disjoint subgraphs, and, as to dominate $V(G)$ we need to dominate $N^{k}_G[C]$ and $N^{k}_G[C']$, by disjunction of theses sets and by~\cref{fact:dom}, we have
    %
    \def\ccix{\substack{C\in\CC_i\\ C\not\subseteq X}}
    %
    \[
        \sum_{\ccix} \MDS(G, N_G^k[C]) ~\le~ \sum_{C\in \CC_i} \MDS(G, N_G^k[C]) ~\le~ \MDS(G,V(G)) ~=~ \MDS(G) ~.
    \]
    We remark that $\card{(\sfA(G)\cap C)\setminus X} = 0$ if $C \subseteq X$. So, by combining previous inequalities, we obtain the following. %\cyril{I'm wondering in the 2nd line below (when removing the "$\setminus X$"), whether we cannot remove vertices of $S'$ that must be in all $X$, isn't? so winning le +1 in the approx.}

    \begin{eqnarray*}
        \card{(\sfA(G)\cap C_i)\setminus X} &=& \sum_{C\in\CC_i} \card{(\sfA(G)\cap C)\setminus X} ~=~ \sum_{\ccix} \card{(\sfA(G)\cap C)\setminus X}\\
        &\le& \sum_{\ccix} \card{\sfA(G)\cap C} ~\le~ \alpha \sum_{\ccix} \MDS(G,N^k_G[C]) \\
        &\le& \alpha\cdot \MDS(G) ~.
    \end{eqnarray*}

    Putting in \cref{eq:B(G)}, we get that Algorithm~$\sfB$ is an $(\alpha(d+1)+1)$-approximation, and even an $\alpha(d+1)$-approximation if $X=\emptyset$.

    To see that $\sfB$ is also a $k$-uniform approximation it is sufficient to see that, for any $W \subseteq V(G)$, the bound obtained is $\card{\sfB(G)\cap W} \le \alpha (d+1)\cdot \MDS(G, N_G^k[W]) + \MDS(G, N_G[W])$ where the first part is due to running $\sfA$ and the second part is due to running the brute-force.
    Indeed, if the brute-force computed a set whose intersection with $W$ was smaller than $\MDS(G, N_G[W])$, we could replace it by the minimum dominating set of $N_G[W]$ in $G$ and obtain a smaller dominating set, a contradiction. Note that $\MDS(G, N_G[W]) \le \MDS(G, N^k_G[W])$ for $k\ge 1$, proving that $\sfB$ is a $k$-uniform with an approximate ratio $\alpha(d+1)+1$ (or $\alpha(d+1)$ if $X=\emptyset$, as the brute-force is not required in that case).

    Now, let us prove that Algorithm~$\sfB$ has the desired round complexity.
    \begin{itemize}

        \item Computing $X$ in Step~2 takes $T+1$ rounds.

        \item Running $\sfA$ in Step~3 takes~$r$ rounds.

        \item For Step~4, consider the set $S$ computed by $\sfB$ at Step~3, before the brute-force.
        Observe that the set $W = V(G)\setminus N_G[X]$ is dominated by $S$. This is because vertices of $W$ are at distance at least two from $X$ and thus vertices of $N_G[W]$ cannot be in $X$. Thus, $\sfA$ applies to all vertices of $N_G[W]$, and so $W$ is indeed dominated by $S$ (\cref{fact:dom}).
        Therefore, to dominate $N_G[X]$ it is enough to select a set $S'$ from $N^2_G[X]$ (\cref{fact:dom}) as done in Step~4.
        By assumption, the connected components of $N_G^2[X]$ have weak diameter in $G$ at most $\delta$ (obviously, if $X = \emptyset$, $\delta = 0$). Therefore, the brute-force (Step~4) will take at most $\delta+1$ rounds. 

    \end{itemize}
    Naively, Steps~2 and~3 together take $(T+1) + r$ rounds. As Algorithm~$\sfA$ is not guaranteed to work when executed on vertices of $X$, Step~3 must be run only after Step~2. However, both steps can be run in parallel as follows. We run $\sfA$ for $r$ rounds exactly and stop it just after (since its running time on a vertex of $X$ could result into more than $r$ rounds). Then, the decision to add $u$ in $S$ (if selected by $\sfA$) is delayed for the next $T+1 - r$ rounds (this is non-negative from the choice of $T$). In parallel, $G[N^T[u]]$ is computed and is checked to be in $\sC$ or not after $T+1$ rounds. So, after $\max\set{r,T+1} = T+1$ rounds, set $S$ in Step~3 has been completed.

    Step~4 takes $\delta+1$ steps, so that the total round complexity of $\sfB$ is $T+\delta+2$, completing the proof of \cref{prop:local_approx_w_errors}.
\end{proof}

