\section*{ APPENDIX - Pseudocode for Key Dynamics}



\begin{algorithm}
\caption{Public Goods Game (PGG) Process}
\begin{algorithmic}[1]
\For{each patch representing a proto-Aksumite site (PGG center)}
    \State \textbf{Define} radius of participation (e.g., 3 patches)
    \State Identify turtles within the participation radius

    \State \textbf{Calculate threshold for success:}
    \State \hspace{1em} base\_threshold $\gets 0.1$
    \State \hspace{1em} population\_threshold $\gets$ number of turtles $\times 0.05$
    \State \hspace{1em} resource\_threshold $\gets$ sum of 5\% of each turtle's resources
    \State threshold $\gets$ base\_threshold + population\_threshold + resource\_threshold

    \State Mark patches within the radius (visual indicator)

    \State total\_donation $\gets 0$
    \State total\_donors $\gets 0$

    \For{each turtle within the radius}
        \If{donation\_probability $>$ 0.5} \Comment{Cooperator donates}
            \State donation $\gets$ 10\% of turtle's sugar
            \State Reduce turtle's sugar by donation
            \State total\_donation $\gets$ total\_donation + donation
            \State total\_donors $\gets$ total\_donors + 1
        \EndIf
    \EndFor

    \If{total\_donation $\geq$ threshold}
        \State Increment successful PGG counter
        \State Increase fertility (max\_psugar) of patches within the radius
    \EndIf
\EndFor
\end{algorithmic}
\end{algorithm}



\begin{algorithm}
\caption{Movement and Eating}
\begin{algorithmic}[1]
\For{each turtle}
    \State Identify candidate patches within vision range with no turtles
    \State Select the patch with the highest resource (psugar)
    \State Move to the closest patch with maximum psugar
    \State Update sugar level: 
    \State \hspace{1em} sugar $\gets$ sugar - metabolism + psugar of the patch
    \State Set patch's psugar to 0
\EndFor
\end{algorithmic}
\end{algorithm}



\begin{algorithm}
\caption{Reproduction Mechanism}
\begin{algorithmic}[1]
\If{turtle's sugar $\geq$ 2 $\times$ metabolism \textbf{and} reproduction\_count $<$ 2}
    \State Hatch a new turtle (offspring):
    \State \hspace{1em} Give half of the parent's sugar to offspring
    \State \hspace{1em} Inherit parent's donation\_probability with 95\% probability
    \State \hspace{1em} Set offspring's age to 0
    \State \hspace{1em} Set random max\_age (between 40 and 60)
    \State \hspace{1em} Set metabolism to 2
    \State \hspace{1em} Set reproduction\_count for offspring to 0

    \State Increment parent's reproduction\_count by 1
\EndIf
\end{algorithmic}
\end{algorithm}


\begin{algorithm}
\caption{Resource Regrowth and Degradation}
\begin{algorithmic}[1]
\For{each patch}
    \State psugar $\gets$ max\_psugar \Comment{Regrow resources}
    \If{max\_psugar $>$ initial\_max\_psugar}
        \State Reduce max\_psugar by degradation factor (e.g., 0.7)
    \Else
        \State Reset max\_psugar to initial\_max\_psugar
    \EndIf
\EndFor
\end{algorithmic}
\end{algorithm}


\begin{algorithm}
\caption{Starvation and Aging}
\begin{algorithmic}[1]
\For{each turtle}
    \State Increment age by 1
    \If{sugar $<$ 0 \textbf{or} age $>$ max\_age}
        \State Remove turtle (dies)
    \EndIf
\EndFor
\end{algorithmic}
\end{algorithm}


\begin{algorithm}
\caption{Main Execution Loop}
\begin{algorithmic}[1]
\While{turtles exist}
    \State Run Public Goods Game (PGG) on proto-Aksumite site patches

    \For{each patch}
        \State Regenerate resources (psugar)
        \State Apply degradation to fertility (max\_psugar)
    \EndFor

    \For{each turtle}
        \State Move to the best patch (based on psugar)
        \State Consume resources (eat)
        \State Increment age
        \State Check for reproduction conditions
        \State Check for starvation or aging-related death
    \EndFor

    \State Update turtle colors based on cooperation status
    \State Update patch colors based on resource levels
    \State Advance the simulation tick
\EndWhile
\end{algorithmic}
\end{algorithm}
